// ─── PHASE 6: OPERATIONS HUB SCREENS ────────────────────────────────────────

// ── Shared helpers ────────────────────────────────────────────────────────────
function _p6WOStatusClass(s) {
  return { scheduled:'wo-status--scheduled', 'in-progress':'wo-status--inprogress',
    completed:'wo-status--completed', cancelled:'wo-status--cancelled',
    hold:'wo-status--hold', 'on-hold':'wo-status--onhold' }[s] || 'wo-status--scheduled';
}
function _p6WOStatusLabel(s) {
  const _T = (typeof window._t === 'function') ? window._t : (x => x);
  return { scheduled:_T('Scheduled'),'in-progress':_T('In Progress'),completed:_T('Completed'),
    cancelled:_T('Cancelled'), hold:_T('Hold — awaiting acceptance'), 'on-hold':_T('On Hold') }[s] || s || _T('Scheduled');
}
// Traffic-light dot for schedule cards: yellow = hold (pre-acceptance),
// green = confirmed/scheduled, red = cancelled/declined.
function _p6WOTrafficDot(s) {
  const color = _sbStatusColor(s);
  const title = s === 'hold' ? 'HOLD — waiting for the client to accept the estimate' : (s === 'cancelled' ? 'Cancelled / declined' : 'Confirmed');
  return `<span class="sb-traffic-dot" title="${title}" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${color};flex:0 0 auto;${s==='hold' ? 'box-shadow:0 0 0 3px rgba(234,179,8,.25);animation:sbHoldPulse 1.8s ease-in-out infinite' : ''}"></span>`;
}
window._p6WOTrafficDot = _p6WOTrafficDot;
function _sbStatusColor(s) {
  return s === 'hold' || s === 'on-hold' ? '#D99A05'
    : s === 'cancelled' ? '#C94B43'
    : s === 'in-progress' ? '#3978C5'
    : '#239A5B';
}
function _p6AssetLabel(s) {
  return { active:'Active', idle:'Idle', maintenance:'In Maintenance',
    retired:'Retired', rented:'Rented Out', pending:'Pending',
    'out-of-service':'Out of Service' }[s] || s || 'Active';
}
function _p6InvtLabel(s) {
  return { ok:'In Stock','low-stock':'Low Stock','out-of-stock':'Out of Stock',
    reorder:'Reorder Now', discontinued:'Discontinued',
    'on-order':'On Order', reserved:'Reserved' }[s] || s || 'In Stock';
}
function _p6ReadinessLabel(s) {
  return { ready:'Ready','not-ready':'Not Ready','partial':'Partial Ready',
    loading:'Loading','en-route':'En Route','on-site':'On Site',
    'wrapping-up':'Wrapping Up',completed:'Completed',
    cancelled:'Cancelled',delayed:'Delayed' }[s] || s || 'Ready';
}
function _p6FreqLabel(f) {
  return { weekly:'Weekly', biweekly:'Bi-Weekly', monthly:'Monthly',
    bimonthly:'Bi-Monthly', quarterly:'Quarterly',
    semiannual:'Semi-Annual', annual:'Annual' }[f] || f || '—';
}
function _p6WONum(wo) {
  return wo.woNumber || ('WO-' + String(wo.id || '').slice(-5).padStart(5,'0'));
}
function _p6AssetCat(c) {
  return { vehicle:'Vehicle', trailer:'Trailer', equipment:'Equipment',
    tool:'Tool', tech:'Technology', other:'Other' }[c] || c || '—';
}

// ── 1. Operations Hub landing ─────────────────────────────────────────────────
function opsHub() {
  const R = window.GW && window.GW.record;
  const wos    = state.workOrders     || [];
  const assets = state.assets         || [];
  const inv    = state.inventory      || [];
  const plans  = state.recurringPlans || [];
  const maint  = state.maintenance    || [];

  const openWOs      = wos.filter(w => w.status === 'scheduled' || w.status === 'in-progress').length;
  const inProgressWO = wos.filter(w => w.status === 'in-progress').length;
  const dueToday     = wos.filter(w => w.date && w.date.slice(0,10) === new Date().toISOString().slice(0,10)).length;
  const lowInv       = inv.filter(i => Number(i.onHand||0) <= Number(i.reorderAt||0)).length;
  const overdueMaint = maint.filter(m => !m.completedDate && m.dueDate && m.dueDate < new Date().toISOString().slice(0,10)).length;
  const activePlans  = plans.filter(p => p.status === 'active').length;
  const idleAssets   = assets.filter(a => a.status === 'idle').length;

  const statsHtml = R ? R.OpsStatusBar([
    { val: openWOs,      label: 'Open WOs',        accent: 'action',   filter: 'workOrderList' },
    { val: inProgressWO, label: 'In Progress',      accent: 'accent3',  filter: 'dispatchBoard' },
    { val: dueToday,     label: 'Due Today',        accent: 'accent2',  filter: 'scheduleBoard' },
    { val: activePlans,  label: 'Active Plans',     accent: 'emerald',  filter: 'recurringServices' },
    { val: lowInv,       label: 'Low Inventory',    accent: 'amber',    filter: 'inventoryList', delta: lowInv > 0 ? '!' : '' },
    { val: overdueMaint, label: 'Overdue Maint.',   accent: 'red',      filter: 'maintenanceQueue', delta: overdueMaint > 0 ? '!' : '' },
    { val: idleAssets,   label: 'Idle Assets',      accent: 'text-muted', filter: 'assetList' },
  ]) : '';

  const recentWOs = wos.slice(-5).reverse().map(wo => `
    <div class="wo-row" onclick="show('workOrderDetail','${wo.id}')" style="cursor:pointer">
      <span class="wo-number">${_p6WONum(wo)}</span>
      <span class="wo-client">${escapeHtml(wo.clientName||wo.oppId||'—')}</span>
      <span class="wo-type">${escapeHtml(wo.type||'Service')}</span>
      <span><span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}">${_p6WOStatusLabel(wo.status)}</span></span>
      <span class="wo-date">${wo.date ? _p5FmtDate(wo.date) : '—'}</span>
    </div>`).join('') || '<p style="padding:16px;color:var(--gw-text-muted);font-style:italic">No work orders yet. <button class="rp-btn-sm" onclick="show(\'workOrderList\')">Create First WO</button></p>';

  const duePlans = plans.filter(p => p.status === 'active').slice(0,5).map(p => `
    <div class="recur-row" onclick="show('recurringServices')" style="cursor:pointer">
      <span class="recur-client">${escapeHtml(p.clientName||p.clientId||'—')}</span>
      <span class="recur-freq">${_p6FreqLabel(p.freq)}</span>
      <span class="recur-next">${p.nextVisit ? _p5FmtDate(p.nextVisit) : '—'}</span>
      <span class="recur-crew">${escapeHtml(p.crew||'Unassigned')}</span>
    </div>`).join('') || '<p style="padding:12px 0;color:var(--gw-text-muted);font-style:italic">No active recurring plans.</p>';

  view.innerHTML = `
  <div class="ops-hub-wrap gw-ops-shell">
    <header class="rp-header gw-ops-header">
      <div class="rp-header-left">
        <h1 class="rp-title">Operations Hub</h1>
        <p class="rp-subtitle">Scheduling · Dispatch · Work Orders · Assets · Inventory</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('scheduleBoard')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="2" y="3" width="12" height="11" rx="1.5"/><path d="M5 1v3M11 1v3M2 7h12"/></svg>
          Schedule
        </button>
        <button class="rp-btn" onclick="show('dispatchBoard')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="8" cy="8" r="6"/><path d="M8 4v4l3 2"/></svg>
          Dispatch
        </button>
        <button class="rp-btn rp-btn--primary" onclick="show('workOrderList')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1z"/><path d="M5 5h6M5 8h6M5 11h3"/></svg>
          + Work Order
        </button>
      </div>
    </header>

    <div style="max-width:1200px;margin:0 auto;padding:16px 24px 0">${statsHtml}</div>

    <div class="ops-hub-grid" style="max-width:1200px;margin:0 auto;padding:20px 24px;display:grid;grid-template-columns:1fr 1fr;gap:20px">

      <!-- Work Orders panel -->
      <div class="rp-card" style="grid-column:1/-1">
        <div class="rp-card-head">
          <span class="rp-card-title">Recent Work Orders</span>
          <button class="rp-btn-sm" onclick="show('workOrderList')">View All</button>
        </div>
        <div class="wo-list-shell" style="padding:0">
          ${recentWOs}
        </div>
      </div>

      <!-- Recurring plans panel -->
      <div class="rp-card">
        <div class="rp-card-head">
          <span class="rp-card-title">Active Recurring Plans</span>
          <button class="rp-btn-sm" onclick="show('recurringServices')">View All</button>
        </div>
        <div style="padding:4px 0">
          <div style="display:grid;grid-template-columns:1fr auto auto auto;gap:8px;padding:4px 0 8px;border-bottom:1px solid var(--gw-border)">
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Client</span>
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Freq</span>
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Next Visit</span>
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Crew</span>
          </div>
          ${duePlans}
        </div>
      </div>

      <!-- Quick links panel -->
      <div class="rp-card">
        <div class="rp-card-head">
          <span class="rp-card-title">Operations Quick Links</span>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:8px 0">
          ${[
            ['scheduleBoard',     'Schedule Board',    'M2 4h12v2H2zM2 8h12v2H2zM2 12h8v2H2z'],
            ['dispatchBoard',     'Dispatch Board',    'M8 2a6 6 0 100 12A6 6 0 008 2zM8 6v4l2.5 1.5'],
            ['recurringServices', 'Recurring Services','M3 8a5 5 0 0110 0M8 5v3l2 1'],
            ['workOrderList',     'Work Orders',       'M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1zM5 5h6M5 8h6M5 11h3'],
            ['assetList',         'Assets',            'M2 12V6l6-4 6 4v6l-6 4-6-4z'],
            ['maintenanceQueue',  'Maintenance',       'M8 2a6 6 0 100 12M8 5v3l2 1.5'],
            ['inventoryList',     'Inventory',         'M2 4h12v10H2zM5 4V2h6v2M6 8h4M6 11h2'],
            ['timeTracker',       'Time Tracker',      'M8 4v4l2.5 1.5M8 1a7 7 0 100 14A7 7 0 008 1z'],
          ].map(([view, label, path]) => `
            <button class="rp-btn" style="justify-content:flex-start;gap:8px" onclick="show('${view}')">
              <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7"><path d="${path}"/></svg>
              <span style="font-size:12px">${label}</span>
            </button>`).join('')}
        </div>
      </div>

    </div>
  </div>`;
}
window.opsHub = opsHub;

// ── 2. Schedule Board ─────────────────────────────────────────────────────────
// ── Schedule Board State ──────────────────────────────────────────────────────
window._sbState = window._sbState || {
  viewMode: 'week',        // 'week' | 'timeline' | 'month' | 'agenda'
  weekOffset: 0,
  monthOffset: 0,
  hiddenCrews: new Set(),
  crews: [],
  workOrders: [],
  backlog: [],
  // Per-crew capacity for the visible week, from /api/scheduling/week. Null
  // until loaded, or if that fetch fails — the lane metric degrades to showing
  // scheduled hours without a percentage rather than blocking the board.
  capacity: null,
  loaded: false,
  crewLanes: true,         // show crew-lane rows in week view
  density: 'compact',
  showMetrics: false,
  timelineDate: gwToday(),
  workdayStart: 6,
  workdayEnd: 20,
  snapMinutes: 15,
  undoStack: [],
};

// Saved service packages for the visit modal's "Add Package" picker — a
// simple module-level cache refetched on first open, not part of _sbState
// (mirrors _pbItems in pricing.js / _prCustomTpls in proposals.js, the two
// closest "load once, fetch() directly, no DB.js client" precedents in this
// codebase — see /api/service-packages).
let _sbPackages = null;
async function _sbLoadPackages() {
  try {
    const r = await fetch('/api/service-packages', { credentials: 'include' });
    const j = await r.json();
    _sbPackages = Array.isArray(j.packages) ? j.packages : [];
  } catch (e) { _sbPackages = []; }
  return _sbPackages;
}
function _sbParseJsonField(v) {
  if (Array.isArray(v)) return v;
  try { return JSON.parse(v || '[]'); } catch (e) { return []; }
}

function _sbCurrentDateRange() {
  const sb = window._sbState || {};
  if (sb.viewMode === 'timeline') {
    const date = sb.timelineDate || gwToday();
    return { from: date, to: date };
  }
  if (sb.viewMode === 'month') {
    const m = _sbGetMonthDays(sb.monthOffset || 0);
    const start = new Date(m.first); start.setDate(start.getDate() - start.getDay());
    const end = new Date(m.last); end.setDate(end.getDate() + (6 - end.getDay()));
    return { from: gwDateISO(start), to: gwDateISO(end) };
  }
  const days = _sbGetWeekDays(sb.weekOffset || 0);
  return { from: gwDateISO(days[0]), to: gwDateISO(days[6]) };
}

async function _sbLoadData() {
  try {
    // Field roles only see their assigned crew — pass rep_id to filter server-side
    const _sbRep = window._d1SessionRep || (window.getCurrentRep ? window.getCurrentRep() : null);
    const _sbFieldRoles = window._GW_FIELD_ROLES || ['foreman','laborer','field_supervisor'];
    const _sbIsField = _sbRep && _sbFieldRoles.includes(_sbRep.role);
    const range = _sbCurrentDateRange();
    const _woParams = new URLSearchParams({ limit: '1000', date_from: range.from, date_to: range.to });
    if (_sbIsField && _sbRep) _woParams.set('rep_id', _sbRep.id);
    // One row per scheduled DAY, not per job — the grid draws each phase of a
    // multi-day job as its own card. Every other caller wants one row per job and
    // now gets that by default; see the expand=days note in src/index.tsx.
    _woParams.set('expand', 'days');
    const _woUrl = '/api/work-orders?' + _woParams.toString();
    const [cr, wo, rr, backlog, cap] = await Promise.all([
      fetch('/api/crews', {credentials:'include'}).then(r=>r.json()),
      fetch(_woUrl, {credentials:'include'}).then(r=>r.json()),
      fetch('/api/reps', {credentials:'include'}).then(r=>r.json()).catch(()=>null),
      // The Job Pool, from the endpoint built for it.
      //
      // This used to be a SECOND full /api/work-orders fetch at limit=300,
      // filtered client-side for rows with no date — so every board load pulled
      // the work-order list twice, and anything past the 300th row simply did
      // not exist as far as the pool was concerned. /api/scheduling/backlog does
      // the bucketing server-side, strips money for field roles, and had been
      // sitting there with tests and no callers since it was written.
      fetch('/api/scheduling/backlog?limit=500', {credentials:'include'}).then(r=>r.json()).catch(()=>null),
      // Real crew capacity: people on the crew x productive minutes per working
      // day. One payload for the whole week — see src/scheduling/api.ts. Failing
      // this fetch must not break the board, so the metric falls back to the
      // old scheduled-hours-only display rather than the grid refusing to draw.
      fetch('/api/scheduling/week?start=' + encodeURIComponent(range.from), {credentials:'include'})
        .then(r=>r.json()).catch(()=>null),
    ]);
    if (rr && rr.ok) window._gwAllReps = rr.data || rr.reps || [];
    window._sbState.capacity = (cap && cap.ok) ? cap : null;
    if (cr.ok) {
      // Field roles: only show their own crew(s) in the crew filter bar
      if (_sbIsField && _sbRep) {
        window._sbState.crews = (cr.data || []).filter(crew =>
          crew.members && crew.members.some(m => m.id === _sbRep.id || m.rep_id === _sbRep.id)
        );
        // If no crew memberships found, show all crews anyway (graceful fallback)
        if (window._sbState.crews.length === 0) window._sbState.crews = cr.data || [];
      } else {
        window._sbState.crews = cr.data || [];
      }
    }
    if (wo.ok)  window._sbState.workOrders = wo.data  || [];
    if (backlog && backlog.ok) {
      // Three buckets, kept apart, each tagged so the pool can filter on them.
      // See src/scheduling/api.ts for why 'tentative' wins over 'needs
      // scheduling': a held job is work the client has not bought yet, and the
      // next action on it is to close the sale, not to find it a Tuesday.
      window._sbState.pool = [
        ...(backlog.needs_scheduling || []).map(w => ({ ...w, pool_state: 'needs_scheduling' })),
        ...(backlog.needs_crew       || []).map(w => ({ ...w, pool_state: 'needs_crew' })),
        ...(backlog.tentative        || []).map(w => ({ ...w, pool_state: 'tentative' })),
      ].map(w => ({ ...w, id: w.work_order_id }));
      // Kept for the timeline view's own "Unscheduled" aside, which reads it.
      window._sbState.backlog = window._sbState.pool.filter(w => w.pool_state === 'needs_scheduling');
    }
    window._sbState.loaded = true;
  } catch(e) {
    console.warn('[scheduleBoard] API load failed, using localStorage fallback', e);
    // Fallback: convert localStorage workOrders to D1 shape
    window._sbState.workOrders = (state.workOrders||[]).map(w=>({
      id:w.id, wo_number:w.woNumber||w.id,
      client_name:w.clientName||'', type:w.type||'Service',
      status:w.status||'scheduled', readiness:w.readiness||'ready',
      scheduled_date:w.date||null, scheduled_time:w.time||null,
      notes:w.notes||'', crew_id:null, crew_name:w.crew||'',
      crew_color:'#94a3b8', checklist:w.checklist||[], materials:w.materials||[],
    }));
    window._sbState.loaded = true;
  }
}

function _sbGetWeekDays(offset) {
  const today = new Date();
  const sunday = new Date(today);
  sunday.setDate(today.getDate() - today.getDay() + offset*7); // snap to Sunday
  return Array.from({length:7}, (_,i) => {
    const d = new Date(sunday); d.setDate(sunday.getDate()+i); return d;
  });
}

function _sbGetMonthDays(offset) {
  const now = new Date();
  const y = now.getFullYear(), m = now.getMonth() + offset;
  const first = new Date(y, m, 1);
  const last  = new Date(y, m+1, 0);
  return { first, last, month: first.toLocaleDateString('en-US',{month:'long',year:'numeric'}) };
}

function _sbCrewPill(crew) {
  if (!crew) return '';
  const c = crew.crew_color || crew.color || '#94a3b8';
  return `<span class="sb-crew-pill" style="background:${c}20;color:${c};border-color:${c}40">${escapeHtml(crew.crew_name||crew.name||'')}</span>`;
}

function _sbMdColor(id) {
  const palette = ['#2D7A55','#3B82F6','#8B5CF6','#D97706','#0F766E','#BE123C','#4F46E5'];
  let h = 0; String(id || '').split('').forEach(ch => { h = ((h << 5) - h) + ch.charCodeAt(0); h |= 0; });
  return palette[Math.abs(h) % palette.length];
}

function _sbMinutes(value, fallback) {
  const m = String(value || '').match(/^(\d{1,2}):(\d{2})/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : fallback;
}
function _sbClock(minutes) {
  const m = Math.max(0, Math.min(1439, Math.round(minutes)));
  return String(Math.floor(m / 60)).padStart(2,'0') + ':' + String(m % 60).padStart(2,'0');
}
function _sbDisplayTime(value) {
  const mins = _sbMinutes(value, null);
  if (mins == null) return '';
  const h = Math.floor(mins / 60), m = mins % 60;
  return `${h % 12 || 12}:${String(m).padStart(2,'0')} ${h < 12 ? 'AM' : 'PM'}`;
}
function _sbEventRange(wo) {
  const start = _sbMinutes(wo.scheduled_time, 8 * 60);
  let end = _sbMinutes(wo.scheduled_end_time, null);
  const duration = Number(wo.scheduled_duration_minutes) || (Number(wo.duration_hours) ? Number(wo.duration_hours) * 60 : 60);
  if (end == null || end <= start) end = Math.min(24 * 60, start + Math.max(30, duration));
  return { start, end, duration: end - start };
}
function _sbConflictMap(rows) {
  const out = new Map(), groups = new Map();
  (rows || []).forEach(w => {
    const key = `${w.scheduled_date || ''}:${w.md_crew_id || w.crew_id || 'unassigned'}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(w);
  });
  groups.forEach(list => {
    const timed = list.map(w => ({ w, ..._sbEventRange(w) })).sort((a,b)=>a.start-b.start);
    for (let i=0;i<timed.length;i++) for (let j=i+1;j<timed.length && timed[j].start < timed[i].end;j++) {
      const a = timed[i].w, b = timed[j].w;
      out.set(`${a.id}:${a.md_day_number || 0}`, 'Crew time conflict');
      out.set(`${b.id}:${b.md_day_number || 0}`, 'Crew time conflict');
    }
  });
  return out;
}
function _sbPreferencePayload() {
  const sb = window._sbState;
  return { density: sb.density, showMetrics: sb.showMetrics, crewLanes: sb.crewLanes, snapMinutes: sb.snapMinutes, workdayStart: sb.workdayStart, workdayEnd: sb.workdayEnd };
}
function _sbSavePreferences() {
  const value = JSON.stringify(_sbPreferencePayload());
  localStorage.setItem('gw_schedule_preferences', value);
  fetch('/api/settings', { method:'PUT', credentials:'include', headers:{'Content-Type':'application/json'}, body:JSON.stringify({key:'schedule_preferences', value}) }).catch(()=>{});
}
function _sbLoadPreferences() {
  try { Object.assign(window._sbState, JSON.parse(localStorage.getItem('gw_schedule_preferences') || '{}')); } catch (_) {}
}
_sbLoadPreferences();


// ── Job Day rail ─────────────────────────────────────────────────────────────
//
// The day drawer, docked beside the board rather than covering it.
//
// It was a full-screen overlay: opening a job hid the schedule, so comparing a
// day against the rest of the week meant closing it, looking, and opening it
// again. A scheduler works between the two constantly. The rail keeps both on
// screen, which is the whole point of the layout in the reference.
//
// The overlay modal is kept for every OTHER entry point — client detail,
// estimates, My Day — where there is no board to dock against.

window._sbOpenDayRail = function(woId, dayNumber) {
  const sb = window._sbState;
  const key = `${woId}:${dayNumber || 0}`;
  // Clicking the selected card again closes the rail, which is what people try.
  sb.selectedDayId = sb.selectedDayId === key ? null : key;
  sb.selectedRail = null;
  _sbRender();
  if (sb.selectedDayId) _sbLoadRail(woId, dayNumber);
};
window._sbCloseRail = function() {
  window._sbState.selectedDayId = null;
  window._sbState.selectedRail = null;
  _sbRender();
};

async function _sbLoadRail(woId, dayNumber) {
  try {
    const r = await fetch(`/api/work-orders/${encodeURIComponent(woId)}`, { credentials: 'include' });
    const d = await r.json();
    if (!d.ok) return;
    let wo = d.data;
    // The board holds one row per DAY, so a specific day's fields come from
    // there — the work-order read joins whichever day matches its own date.
    if (dayNumber) {
      const row = (window._sbState.workOrders || []).find(w => w.id === woId && Number(w.md_day_number) === Number(dayNumber));
      if (row) wo = { ...wo, ...{
        md_day_id: row.md_day_id, md_day_number: row.md_day_number, md_scope: row.md_scope,
        md_phase_name: row.md_phase_name, md_crew_id: row.md_crew_id, md_status: row.md_status,
        scheduled_date: row.scheduled_date, scheduled_time: row.scheduled_time,
        scheduled_end_time: row.scheduled_end_time, schedule_locked: row.schedule_locked,
      } };
    }
    window._sbState.selectedRail = wo;
    _sbRender();
    _sbLoadHours(woId);
    // Equipment is a separate read because it is a separate TABLE — the work
    // order's `equipment` field is free text somebody typed, wo_day_equipment is
    // what is actually booked to this day. The rail showed the former for months
    // because nothing read the latter.
    if (wo.md_day_id) _sbLoadDayEquipment(wo.md_day_id);
  } catch (e) { /* rail simply stays in its loading state */ }
}

async function _sbLoadDayEquipment(dayId) {
  try {
    const r = await fetch(`/api/scheduling/days/${encodeURIComponent(dayId)}/equipment`, { credentials: 'include' });
    const d = await r.json();
    if (!d || !d.ok) return;
    // Keyed by day so a fast click through three cards cannot leave the second
    // card's equipment showing under the third card's heading.
    window._sbState.dayEquipment = { day_id: dayId, ...d };
    _sbRender();
    // Needed to populate the picker; render again once it lands rather than
    // blocking the bookings behind the catalogue.
    if (!window._sbState.assets) { await _sbLoadAssets(); _sbRender(); }
  } catch (e) { /* the section falls back to the job's free-text notes */ }
}

async function _sbLoadAssets() {
  // Fetched once per board session. The catalogue is small and changes rarely,
  // and re-fetching it on every card click would put a request behind an
  // interaction that should feel instant.
  if (window._sbState.assets) return window._sbState.assets;
  try {
    const r = await fetch('/api/assets', { credentials: 'include' });
    const d = await r.json();
    window._sbState.assets = (d && d.ok && d.data && d.data.assets) ? d.data.assets : [];
  } catch (e) { window._sbState.assets = []; }
  return window._sbState.assets;
}

window._sbBookEquipment = async function(dayId, assetId) {
  if (!assetId) return;
  try {
    const r = await fetch(`/api/scheduling/days/${encodeURIComponent(dayId)}/equipment`, {
      method: 'POST', credentials: 'include',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ asset_id: assetId }),
    });
    const d = await r.json();
    if (!d.ok) { showToast(d.error || 'Could not book that equipment', 'error'); return; }
    window._sbState.dayEquipment = { day_id: dayId, ...d };
    _sbRender();
    // The double-booking warning is the whole reason this returns the full day
    // rather than the one row — booking is exactly when somebody needs to hear
    // that the machine is already spoken for.
    if (d.conflicts && d.conflicts.length) showToast(d.conflicts[d.conflicts.length - 1].message, 'warning');
  } catch (e) { showToast('Could not book that equipment', 'error'); }
};

/**
 * Advance a booking: needed -> loaded -> on site -> needed.
 *
 * A cycle rather than a dropdown because this gets tapped on a phone at 6am by
 * somebody standing next to the trailer, and three states do not justify a
 * menu. It wraps so a mis-tap is one more tap to fix, not a dead end.
 */
window._sbCycleEquipmentStatus = async function(dayId, assetId, current) {
  const order = ['needed', 'loaded', 'on_site'];
  const next = order[(order.indexOf(current) + 1) % order.length];
  try {
    const r = await fetch(`/api/scheduling/days/${encodeURIComponent(dayId)}/equipment`, {
      method: 'POST', credentials: 'include',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ asset_id: assetId, status: next }),
    });
    const d = await r.json();
    if (!d.ok) { showToast(d.error || 'Could not update that equipment', 'error'); return; }
    window._sbState.dayEquipment = { day_id: dayId, ...d };
    _sbRender();
  } catch (e) { showToast('Could not update that equipment', 'error'); }
};

window._sbUnbookEquipment = async function(dayId, assetId) {
  try {
    const r = await fetch(`/api/scheduling/days/${encodeURIComponent(dayId)}/equipment/${encodeURIComponent(assetId)}`,
      { method: 'DELETE', credentials: 'include' });
    const d = await r.json();
    if (!d.ok) { showToast(d.error || 'Could not release that equipment', 'error'); return; }
    _sbLoadDayEquipment(dayId);
  } catch (e) { showToast('Could not release that equipment', 'error'); }
};

/**
 * The "book a machine" control.
 *
 * Renders nothing without a day id — an unsaved or unscheduled day has nothing
 * to book against, and an inert dropdown that silently fails is worse than no
 * dropdown. Already-booked machines are filtered out rather than disabled: the
 * list is short, and a menu of things you cannot pick is noise.
 */
function _sbEquipmentPickerHtml(eq, bookings) {
  if (!eq || !eq.day_id) return '';
  const all = window._sbState.assets;
  if (!all) return '<p class="sb-rail-eqhint">Loading equipment&hellip;</p>';
  const taken = new Set((bookings || []).map(b => b.asset_id));
  const free = all.filter(a => !taken.has(a.id));
  if (!free.length) {
    return all.length
      ? '<p class="sb-rail-eqhint">Everything in the yard is on this day.</p>'
      : '<p class="sb-rail-eqhint">No equipment on file yet.</p>';
  }
  return `<div class="sb-rail-eqadd">
    <select class="sb-rail-eqsel" onchange="_sbBookEquipment('${escapeHtml(eq.day_id)}', this.value); this.value='';">
      <option value="">+ Book equipment&hellip;</option>
      ${free.map(a => `<option value="${escapeHtml(a.id)}">${escapeHtml(a.name || a.asset_tag || 'Untitled')}${a.asset_tag && a.name ? ` &middot; ${escapeHtml(a.asset_tag)}` : ''}</option>`).join('')}
    </select>
  </div>`;
}

/**
 * One collapsible section of the day rail.
 *
 * Which sections are open is STATE, not DOM. It used to live only in the
 * `is-open` class, so any _sbRender() — booking a machine, cycling a status,
 * the capacity refresh — silently collapsed everything the user had opened.
 * Found by booking equipment in a browser: the section you were working in
 * shut itself the moment you used it.
 *
 * The key is derived from the title so it survives re-render without every
 * caller having to invent an id.
 */
window._sbToggleRailSec = function(el, key) {
  const open = el.parentElement.classList.toggle('is-open');
  (window._sbState.railSecs || (window._sbState.railSecs = {}))[key] = open;
};

function _sbRailSection(title, count, body, open) {
  const key = String(title).replace(/&[a-z]+;/g, '').replace(/[^a-z]/gi, '').toLowerCase();
  const remembered = (window._sbState.railSecs || {})[key];
  // A remembered choice wins over the caller's default in both directions —
  // a section the user closed stays closed too.
  const isOpen = remembered === undefined ? open !== false : remembered;
  return `<section class="sb-rail-sec${isOpen ? ' is-open' : ''}">
    <header class="sb-rail-sec-head" onclick="_sbToggleRailSec(this,'${key}')">
      <h4>${title}</h4>${count != null ? `<span class="sb-rail-count">${count}</span>` : ''}
      <span class="sb-rail-caret" aria-hidden="true">&rsaquo;</span>
    </header>
    <div class="sb-rail-sec-body">${body}</div>
  </section>`;
}

function _sbDayRailHtml() {
  const sb = window._sbState;
  const wo = sb.selectedRail;
  if (!wo) {
    return `<aside class="sb-rail" aria-label="Job day details" aria-busy="true">
      <div class="sb-rail-head"><div class="sb-rail-skel-line" style="width:40%"></div><button class="sb-rail-close" onclick="_sbCloseRail()" aria-label="Close">&times;</button></div>
      <div class="sb-rail-body">${'<div class="sb-rail-skel"></div>'.repeat(4)}</div>
    </aside>`;
  }

  const crews = sb.crews || [];
  const crewId = wo.md_crew_id || wo.crew_id;
  const crew = crews.find(c => c.id === crewId);
  const total = Number(wo.total_days || 0), dayN = Number(wo.md_day_number || 0);
  const cap = sb.capacity;
  const assignment = (cap?.assignments || []).find(a => a.day_id === wo.md_day_id);
  const people = assignment?.employees || [];
  const checklist = Array.isArray(wo.checklist) ? wo.checklist : [];
  const doneCount = checklist.filter(x => x && (x.done || x.checked)).length;
  const materials = Array.isArray(wo.materials) ? wo.materials : [];
  // Real bookings from wo_day_equipment, but only if they belong to THIS day —
  // otherwise a slow response repaints the previous card's equipment here.
  const eqState = window._sbState.dayEquipment;
  const eq = (eqState && eqState.day_id && eqState.day_id === wo.md_day_id) ? eqState : {};
  const bookings = Array.isArray(eq.bookings) ? eq.bookings : [];
  // Free text typed before the table existed. Shown as "Note only" so nobody
  // mistakes a word somebody typed for a machine that is actually reserved.
  const notes = Array.isArray(eq.unbooked_notes) ? eq.unbooked_notes
    : (Array.isArray(wo.equipment) ? wo.equipment.map(e => typeof e === 'string' ? e : (e && e.name) || '').filter(Boolean) : []);
  const photos = [...(Array.isArray(wo.before_photos) ? wo.before_photos : []), ...(Array.isArray(wo.after_photos) ? wo.after_photos : [])];

  const sib = (target) => (sb.workOrders || []).find(w => w.id === wo.id && Number(w.md_day_number) === target);
  const navBtn = (target, label, glyph) => (total > 1 && sib(target))
    ? `<button class="sb-daynav-btn" onclick="_sbOpenDayRail('${escapeHtml(wo.id)}',${target})" aria-label="${label}" title="${label}">${glyph}</button>`
    : `<button class="sb-daynav-btn" disabled aria-hidden="true">${glyph}</button>`;

  return `<aside class="sb-rail" aria-label="Job day details">
    <div class="sb-rail-head">
      <div class="sb-rail-daynav">
        ${total > 1 ? `${navBtn(dayN - 1, 'Previous day', '&lsaquo;')}<span class="sb-rail-dayof">Day ${dayN} of ${total}</span>${navBtn(dayN + 1, 'Next day', '&rsaquo;')}` : '<span class="sb-rail-dayof">Single day</span>'}
      </div>
      <button class="sb-rail-close" onclick="_sbCloseRail()" aria-label="Close details">&times;</button>
    </div>

    <div class="sb-rail-title">
      <div class="sb-rail-wo">
        <span class="sb-rail-wonum">${escapeHtml(wo.wo_number || '')}</span>
        <span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}">${_p6WOStatusLabel(wo.status)}</span>
      </div>
      <h3>${escapeHtml(wo.title || wo.client_name || 'Job')}</h3>
      <dl class="sb-rail-facts">
        ${wo.property_addr ? `<div><dt>Site</dt><dd>${escapeHtml(wo.property_addr)}</dd></div>` : ''}
        <div><dt>Date</dt><dd>${escapeHtml(gwDateFormat(wo.scheduled_date, { weekday:'short', month:'short', day:'numeric' }))}${wo.scheduled_time ? ' &middot; ' + escapeHtml(_sbDisplayTime(wo.scheduled_time)) : ''}</dd></div>
        <div><dt>Crew</dt><dd>${crew ? `<span class="sb-rail-crewdot" style="background:${crew.color}"></span>${escapeHtml(crew.name)}` : 'Not assigned'}</dd></div>
      </dl>
    </div>

    <div class="sb-rail-body">
      ${_sbRailSection('Labor', null, `
        <div class="sb-rail-hours" id="sbm-hours">
          <div class="sb-rail-skel" style="height:44px"></div>
        </div>`)}

      ${_sbRailSection('Crew &amp; employees', people.length, people.length
        ? `<ul class="sb-rail-people">${people.map(p => `<li>
             <span class="sb-rail-avatar">${escapeHtml((p.rep_name || '?').split(' ').map(w => w[0]).slice(0,2).join('').toUpperCase())}</span>
             <span class="sb-rail-pname">${escapeHtml(p.rep_name || '')}</span>
             ${p.crew_role === 'foreman' ? '<span class="sb-rail-role">Foreman</span>' : ''}
             <span class="sb-rail-pmin">${((p.planned_minutes || 0) / 60).toFixed(1)}h</span>
           </li>`).join('')}</ul>`
        : '<p class="sb-rail-empty">Nobody is on this day yet. Assign a crew and its roster is planned in automatically.</p>')}

      ${_sbRailSection("Today&rsquo;s scope", null,
        (wo.md_scope || wo.notes)
          ? `<p class="sb-rail-scope">${escapeHtml(wo.md_scope || wo.notes)}</p>`
          : '<p class="sb-rail-empty">No scope written for this day.</p>')}

      ${_sbRailSection('Checklist', checklist.length ? `${doneCount}/${checklist.length}` : null, checklist.length
        ? `<ul class="sb-rail-check">${checklist.map(x => `<li class="${x && (x.done || x.checked) ? 'is-done' : ''}"><span class="sb-rail-box" aria-hidden="true"></span>${escapeHtml((x && (x.text || x.label)) || String(x))}</li>`).join('')}</ul>`
        : '<p class="sb-rail-empty">No checklist items.</p>')}

      ${_sbRailSection('Materials &amp; equipment', (materials.length + bookings.length + notes.length) || null,
        (materials.length || bookings.length || notes.length)
          ? `${eq.conflicts && eq.conflicts.length ? `<div class="sb-rail-eqwarn">${eq.conflicts.map(x => escapeHtml(x.message)).join('<br>')}</div>` : ''}
             <ul class="sb-rail-kit">
              ${materials.map(m => `<li><span class="sb-rail-kit-name">${escapeHtml(m.name || String(m))}</span>${m.status ? `<span class="sb-rail-kit-status">${escapeHtml(m.status)}</span>` : ''}</li>`).join('')}
              ${bookings.map(b => `<li class="sb-rail-kit-booked${b.conflict ? ' is-conflict' : ''}">
                  <span class="sb-rail-kit-name">${escapeHtml(b.asset_name || b.asset_tag || 'Equipment')}</span>
                  <button type="button" class="sb-rail-kit-status sb-eq-${escapeHtml(b.status)}"
                          title="Mark as ${b.status === 'needed' ? 'loaded' : b.status === 'loaded' ? 'on site' : 'needed'}"
                          onclick="_sbCycleEquipmentStatus('${escapeHtml(eq.day_id)}','${escapeHtml(b.asset_id)}','${escapeHtml(b.status)}')">${escapeHtml(b.status_label)}</button>
                  <button type="button" class="sb-rail-kit-x" title="Release this equipment"
                          onclick="_sbUnbookEquipment('${escapeHtml(eq.day_id)}','${escapeHtml(b.asset_id)}')">&times;</button>
                </li>`).join('')}
              ${notes.map(n => `<li class="sb-rail-kit-note"><span class="sb-rail-kit-name">${escapeHtml(n)}</span><span class="sb-rail-kit-status">Note only</span></li>`).join('')}
             </ul>
             ${_sbEquipmentPickerHtml(eq, bookings)}`
          : `<p class="sb-rail-empty">Nothing recorded for this day.</p>${_sbEquipmentPickerHtml(eq, bookings)}`, false)}

      ${_sbRailSection('Client update', photos.length || null, `
        <div class="sb-rail-photos">
          ${photos.slice(0, 4).map(u => `<img src="${escapeHtml(typeof u === 'string' ? u : (u.url || ''))}" alt="" loading="lazy">`).join('')}
          <button class="sb-rail-addphoto" onclick="_sbOpenVisitModal('${escapeHtml(wo.id)}',${dayN || 0})" title="Add photos and publish an update">+</button>
        </div>`, false)}
    </div>

    <div class="sb-rail-actions">
      <button class="sb-rail-danger" onclick="_sbUnscheduleDay('${escapeHtml(wo.id)}')">Unschedule day</button>
      <div class="sb-rail-actions-right">
        <button class="rp-btn" onclick="_sbOpenVisitModal('${escapeHtml(wo.id)}',${dayN || 0})">Open full job</button>
        <button class="rp-btn rp-btn--primary" onclick="_sbCompleteVisit('${escapeHtml(wo.id)}','${escapeHtml(wo.type||'Service')}')">Mark day complete</button>
      </div>
    </div>
  </aside>`;
}

// ── Job Pool ─────────────────────────────────────────────────────────────────
//
// Work that is not yet on the grid, beside the grid rather than pretending to be
// a crew in it. Backed by GET /api/scheduling/backlog, which buckets server-side.
//
// Three states, and they answer different questions:
//   needs_scheduling  no date. Nobody knows when.
//   needs_crew        has a date, nobody to do it.
//   tentative         status 'hold' — the client has not bought it yet.
//
// Drag out to schedule; drag a card back in to unschedule it.

const _GW_POOL_TABS = [
  { id: 'all',              label: 'All' },
  { id: 'needs_scheduling', label: 'Needs Scheduling' },
  { id: 'needs_crew',       label: 'Needs Crew' },
  { id: 'tentative',        label: 'Tentative' },
];

const _GW_POOL_SORTS = [
  { id: 'priority', label: 'Priority' },
  { id: 'deadline', label: 'Deadline' },
  { id: 'hours',    label: 'Sold hours' },
  { id: 'client',   label: 'Client' },
];

/** Urgent first. Anything unset sorts BELOW everything stated. */
const _GW_PRIORITY_RANK = { urgent: 0, high: 1, normal: 2, low: 3 };

function _sbPoolFiltered() {
  const sb = window._sbState;
  const pool = sb.pool || [];
  const tab = sb.poolTab || 'all';
  const q = (sb.poolQuery || '').trim().toLowerCase();
  const type = sb.poolType || '';
  return pool.filter(w => {
    if (tab !== 'all' && w.pool_state !== tab) return false;
    if (type && (w.type || '') !== type) return false;
    if (!q) return true;
    return [w.wo_number, w.client_name, w.title, w.property_addr, w.type]
      .some(v => String(v || '').toLowerCase().includes(q));
  }).sort(_sbPoolComparator(sb.poolSort || 'priority'));
}

/**
 * Pool ordering.
 *
 * Every comparator pushes UNSET values to the bottom rather than treating them
 * as zero or as an empty string. A job with no deadline is not due first, and a
 * job with no priority is not the least urgent thing in the list — both are
 * simply unstated, and the list should show what IS stated first.
 *
 * Ties break on wo_number so the order never reshuffles between renders.
 */
function _sbPoolComparator(sort) {
  const last = (v) => (v === null || v === undefined || v === '');
  const tie = (a, b) => String(a.wo_number || '').localeCompare(String(b.wo_number || ''));
  return (a, b) => {
    if (sort === 'deadline') {
      const av = a.required_completion_date, bv = b.required_completion_date;
      if (last(av) !== last(bv)) return last(av) ? 1 : -1;
      if (!last(av) && av !== bv) return av < bv ? -1 : 1;
    } else if (sort === 'hours') {
      const av = a.budget_minutes, bv = b.budget_minutes;
      if (last(av) !== last(bv)) return last(av) ? 1 : -1;
      if (av !== bv) return (bv || 0) - (av || 0); // biggest first: it needs the most planning
    } else if (sort === 'client') {
      const c = String(a.client_name || '').localeCompare(String(b.client_name || ''));
      if (c) return c;
    } else {
      const ar = _GW_PRIORITY_RANK[String(a.priority || '').toLowerCase()];
      const br = _GW_PRIORITY_RANK[String(b.priority || '').toLowerCase()];
      if ((ar === undefined) !== (br === undefined)) return ar === undefined ? 1 : -1;
      if (ar !== undefined && ar !== br) return ar - br;
    }
    return tie(a, b);
  };
}
window._sbSetPoolSort = function(v) { window._sbState.poolSort = v; _sbRender(); };

function _sbPoolCard(w) {
  const hrs = w.budget_minutes != null ? (w.budget_minutes / 60) : (w.duration_minutes != null ? w.duration_minutes / 60 : null);
  const stateLabel = { needs_scheduling: 'Needs scheduling', needs_crew: 'Needs crew', tentative: 'Tentative' }[w.pool_state] || '';
  return `
    <article class="sb-pool-card sb-pool-card--${w.pool_state}"
             draggable="true"
             data-wo="${escapeHtml(w.id)}"
             ondragstart="_sbDragStart(event,'${escapeHtml(w.id)}',0)">
      <header>
        <strong>${escapeHtml(w.client_name || w.title || 'Job')}</strong>
        <span class="sb-pool-wonum">${escapeHtml(w.wo_number || '')}</span>
      </header>
      ${w.title && w.client_name ? `<p class="sb-pool-title">${escapeHtml(w.title)}</p>` : ''}
      <div class="sb-pool-meta">
        ${w.type ? `<span>${escapeHtml(w.type)}</span>` : ''}
        ${hrs != null ? `<span>${hrs.toFixed(hrs % 1 ? 1 : 0)} sold hrs</span>` : ''}
        ${w.scheduled_date ? `<span>${escapeHtml(gwDateFormat(w.scheduled_date, { month:'short', day:'numeric' }))}</span>` : ''}
      </div>
      ${w.property_addr ? `<div class="sb-pool-addr">${escapeHtml(w.property_addr)}</div>` : ''}
      ${(w.priority || w.required_completion_date) ? `<div class="sb-pool-flags">
        ${w.priority ? `<span class="sb-pool-pri sb-pool-pri--${escapeHtml(String(w.priority).toLowerCase())}">${escapeHtml(w.priority)}</span>` : ''}
        ${w.required_completion_date ? `<span class="sb-pool-due" title="Must be finished by">by ${escapeHtml(gwDateFormat(w.required_completion_date, { month:'short', day:'numeric' }))}</span>` : ''}
      </div>` : ''}
      <span class="sb-pool-state">${stateLabel}</span>
    </article>`;
}

/**
 * The week in four numbers.
 *
 * Replaces a band that counted Scheduled Visits / Holds / In Progress /
 * Completed / Crews. Those are all facts, and none of them answers the question
 * a scheduler is actually holding in their head on a Monday morning: can I take
 * more work this week, and what is stopping me?
 *
 * So: what is booked, the labor behind it, what capacity is left, and how much
 * work is sitting in the pool waiting for a crew. Planned labor and capacity are
 * people-hours from wo_day_employees, NOT calendar time — the distinction this
 * whole engine exists to keep.
 */
function _sbKpiBandHtml(totalScheduled, totalUniqueJobs) {
  const cap = window._sbState.capacity;
  const crews = (cap?.crews) || [];
  const plannedMin  = crews.reduce((n, c) => n + (c.week_planned_minutes || 0), 0);
  const capacityMin = crews.reduce((n, c) => n + (c.week_capacity_minutes || 0), 0);
  const remainingMin = Math.max(0, capacityMin - plannedMin);
  const pct = capacityMin > 0 ? Math.round((plannedMin / capacityMin) * 100) : null;
  const remainingPct = capacityMin > 0 ? Math.round((remainingMin / capacityMin) * 100) : null;
  const needCrew = (window._sbState.pool || []).filter(w => w.pool_state === 'needs_crew').length;
  const needSched = (window._sbState.pool || []).filter(w => w.pool_state === 'needs_scheduling').length;
  const h = (m) => (m / 60).toFixed(1) + 'h';

  const card = (mod, value, label, sub) => `
    <div class="gwp-kpi-card${mod ? ' gwp-kpi-card--' + mod : ''}">
      <div class="gwp-kpi-body">
        <div class="gwp-kpi-value">${value}</div>
        <div class="gwp-kpi-label">${label}</div>
        ${sub ? `<div class="gwp-kpi-sub">${sub}</div>` : ''}
      </div>
    </div>`;

  return `<div class="gwp-kpi-row" style="margin-bottom:14px">
    ${card('blue', totalScheduled, 'Jobs Scheduled', `${totalUniqueJobs} job${totalUniqueJobs === 1 ? '' : 's'} this week`)}
    ${card('', h(plannedMin), 'Planned Labor', pct == null ? 'no crew capacity set' : `${pct}% of capacity`)}
    ${card(remainingPct != null && remainingPct < 10 ? 'yellow' : 'green', capacityMin > 0 ? h(remainingMin) : '—', 'Remaining Capacity',
      remainingPct == null ? 'add people to a crew' : `${remainingPct}% remaining`)}
    ${card(needCrew ? 'yellow' : 'muted', needCrew, 'Jobs Needing Crew', needSched ? `${needSched} not scheduled yet` : 'pool is clear')}
  </div>
  ${_sbWarningsHtml()}`;
}

/**
 * Conflicts, from the week payload.
 *
 * Deliberately quiet: nothing renders when there is nothing wrong. A strip that
 * is always there is a strip nobody reads.
 */
function _sbWarningsHtml() {
  const list = (window._sbState.capacity?.warnings) || [];
  if (!list.length) return '';
  const errors = list.filter(w => w.severity === 'error');
  const shown = [...errors, ...list.filter(w => w.severity !== 'error')].slice(0, 4);
  return `<div class="sb-warnings${errors.length ? ' sb-warnings--error' : ''}">
    <strong>${errors.length ? errors.length + ' conflict' + (errors.length === 1 ? '' : 's') : list.length + ' thing' + (list.length === 1 ? '' : 's') + ' to check'}</strong>
    <ul>${shown.map(w => `<li class="sb-warn sb-warn--${w.severity}">
      <span class="sb-warn-date">${escapeHtml(gwDateFormat(w.date, { month:'short', day:'numeric' }))}</span>
      ${escapeHtml(w.message)}
    </li>`).join('')}</ul>
    ${list.length > shown.length ? `<small>and ${list.length - shown.length} more</small>` : ''}
  </div>`;
}

function _sbPoolHtml() {
  const sb = window._sbState;
  if (sb.poolCollapsed) {
    return `<aside class="sb-pool sb-pool--collapsed">
      <button class="sb-pool-toggle" onclick="_sbTogglePool()" title="Show the Job Pool" aria-label="Show the Job Pool">
        <span class="sb-pool-toggle-count">${(sb.pool || []).length}</span>
        <span class="sb-pool-toggle-label">Job Pool</span>
      </button>
    </aside>`;
  }
  const rows = _sbPoolFiltered();
  const counts = (sb.pool || []).reduce((acc, w) => { acc[w.pool_state] = (acc[w.pool_state] || 0) + 1; return acc; }, {});
  const types = [...new Set((sb.pool || []).map(w => w.type).filter(Boolean))].sort();

  return `<aside class="sb-pool"
      ondragover="event.preventDefault();this.classList.add('drag-over')"
      ondragleave="this.classList.remove('drag-over')"
      ondrop="_sbDropOnPool(event)">
    <header class="sb-pool-head">
      <div>
        <strong>Job Pool</strong>
        <small>${(sb.pool || []).length} waiting</small>
      </div>
      <button class="sb-pool-toggle" onclick="_sbTogglePool()" title="Hide the Job Pool" aria-label="Hide the Job Pool">&laquo;</button>
    </header>
    <div class="sb-pool-tabs">
      ${_GW_POOL_TABS.map(t => {
        const n = t.id === 'all' ? (sb.pool || []).length : (counts[t.id] || 0);
        return `<button class="sb-pool-tab${(sb.poolTab || 'all') === t.id ? ' is-active' : ''}"
                        onclick="_sbSetPoolTab('${t.id}')">${t.label}<b>${n}</b></button>`;
      }).join('')}
    </div>
    <div class="sb-pool-filters">
      <input class="sb-pool-search" type="search" placeholder="Search jobs" value="${escapeHtml(sb.poolQuery || '')}"
             oninput="_sbSetPoolQuery(this.value)" aria-label="Search the Job Pool">
      <select class="sb-pool-sort" onchange="_sbSetPoolSort(this.value)" aria-label="Sort the Job Pool" title="Sort the Job Pool">
        ${_GW_POOL_SORTS.map(o => `<option value="${o.id}"${(sb.poolSort||'priority')===o.id?' selected':''}>${o.label}</option>`).join('')}
      </select>
      ${types.length ? `<select class="sb-pool-type" onchange="_sbSetPoolType(this.value)" aria-label="Filter by service type">
        <option value="">All types</option>
        ${types.map(t => `<option value="${escapeHtml(t)}"${sb.poolType === t ? ' selected' : ''}>${escapeHtml(t)}</option>`).join('')}
      </select>` : ''}
    </div>
    <div class="sb-pool-list">
      ${rows.length
        ? rows.map(_sbPoolCard).join('')
        : `<div class="sb-pool-empty">${(sb.pool || []).length ? 'Nothing matches those filters.' : 'Everything is scheduled.'}</div>`}
    </div>
    <footer class="sb-pool-foot">Drag a job onto a crew and day to schedule it. Drag one back here to unschedule.</footer>
  </aside>`;
}

window._sbTogglePool = function() {
  window._sbState.poolCollapsed = !window._sbState.poolCollapsed;
  _sbSavePreferences();
  _sbRender();
};
window._sbSetPoolTab = function(tab) { window._sbState.poolTab = tab; _sbRender(); };
window._sbSetPoolType = function(t) { window._sbState.poolType = t; _sbRender(); };
window._sbSetPoolQuery = function(v) {
  // Re-render on every keystroke would blow away the input and its caret, so the
  // value is stashed and the list is filtered in place.
  window._sbState.poolQuery = v;
  const list = document.querySelector('.sb-pool-list');
  if (!list) return _sbRender();
  const rows = _sbPoolFiltered();
  list.innerHTML = rows.length
    ? rows.map(_sbPoolCard).join('')
    : `<div class="sb-pool-empty">${(window._sbState.pool || []).length ? 'Nothing matches those filters.' : 'Everything is scheduled.'}</div>`;
};

/**
 * Drop a scheduled job back into the pool — i.e. unschedule it.
 *
 * DELETE /api/scheduling/days/:id/schedule clears the date but keeps the day row
 * and the people on it, so re-scheduling the job does not lose its staffing.
 * That endpoint has existed since the router was written and had no UI at all:
 * there was no way to take a job off the grid short of editing it.
 */
window._sbDropOnPool = async function(e) {
  e.preventDefault();
  document.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));
  const woId = e.dataTransfer.getData('text/plain');
  if (!woId) return;
  const wo = (window._sbState.workOrders || []).find(w => w.id === woId);
  if (!wo) return;                    // already in the pool — nothing to undo
  if (!wo.md_day_id) return;
  if (wo.schedule_locked) return showToast('Unlock this visit before unscheduling it','error');
  try {
    const r = await fetch(`/api/scheduling/days/${encodeURIComponent(wo.md_day_id)}/schedule`, {
      method:'DELETE', credentials:'include'
    });
    const d = await r.json().catch(()=>({}));
    if (!r.ok || d.ok === false) throw new Error(d.error || 'Could not unschedule');
    showToast('Moved to the Job Pool','success');
    await _sbRefresh();
  } catch(err) {
    showToast((err && err.message) || 'Could not unschedule','error');
  }
};

function _sbTimelineHtml(sb, visibleWOs, allCrews) {
  const date = sb.timelineDate || gwToday();
  // Real crews only; unscheduled and uncrewed work lives in the Job Pool.
  const crews = allCrews.filter(c=>!sb.hiddenCrews.has(c.id));
  const start = Number(sb.workdayStart || 6) * 60, end = Number(sb.workdayEnd || 20) * 60;
  const ppm = 1.15, height = (end - start) * ppm;
  const hours = Array.from({length: Math.max(1, (end-start)/60 + 1)}, (_,i)=>start+i*60).filter(m=>m<=end);
  const now = new Date(), nowMinutes = now.getHours()*60+now.getMinutes();
  const today = gwToday();
  const timeRail = `<div class="sb-time-rail" style="height:${height}px">${hours.map(m=>`<span style="top:${(m-start)*ppm}px">${_sbDisplayTime(_sbClock(m))}</span>`).join('')}</div>`;
  const columns = crews.map(cr => {
    const jobs = visibleWOs.filter(w => (w.scheduled_date||'').slice(0,10)===date && ((w.md_crew_id||w.crew_id)===cr.id));
    return `<div class="sb-timeline-crew"><div class="sb-timeline-crew-head" style="--crew-color:${cr.color}"><span></span>${escapeHtml(cr.name)}<small>${jobs.length} visits</small></div><div class="sb-timeline-track" style="height:${height}px" data-date="${date}" data-crew="${cr.id}" ondragover="event.preventDefault()" ondrop="_sbDropOnTimeline(event,this)">
      ${hours.map(m=>`<i style="top:${(m-start)*ppm}px"></i>`).join('')}
      ${today===date && nowMinutes>=start && nowMinutes<=end ? `<b class="sb-now-line" style="top:${(nowMinutes-start)*ppm}px"></b>` : ''}
      ${jobs.map(w=>{
        const r=_sbEventRange(w), top=Math.max(0,(r.start-start)*ppm), h=Math.max(32,Math.min(height-top,r.duration*ppm));
        // Crew colour, always. This used to swap to a per-job hash colour for
        // multi-day jobs, so the same visual channel meant "which crew" for one
        // card and "which multi-day plan" for the next one beside it.
        // Multi-day now gets its own channel: a class, and its own inset ring.
        const color=w.crew_color||cr.color;
        const isMdEvent=!!(w.is_multiday||w.md_day_number);
        const conflict=window._sbConflicts?.get(`${w.id}:${w.md_day_number||0}`);
        return `<article class="sb-time-event${conflict?' has-conflict':''}${w.schedule_locked?' is-locked':''}${isMdEvent?' sb-time-event--multiday':''}" data-status="${escapeHtml(w.status||'scheduled')}" style="top:${top}px;height:${h}px;--event-color:${color};--type-color:${_sbTypeColor(w.type)};--md-color:${isMdEvent?_sbMdColor(w.id):'transparent'}" draggable="${w.schedule_locked?'false':'true'}" ondragstart="_sbDragStart(event,'${w.id}',${Number(w.md_day_number||0)})" onclick="_sbOpenVisitModal('${w.id}')">
          <div class="sb-time-event-time">${_p6WOTrafficDot(w.status)}<span>${_sbDisplayTime(_sbClock(r.start))} - ${_sbDisplayTime(_sbClock(r.end))}</span></div><strong>${escapeHtml(w.client_name||w.title||'Job')}</strong><small>${escapeHtml(w.md_phase_name||w.type||'Service')}</small>${conflict?`<em>${conflict}</em>`:''}          ${w.schedule_locked?'':`<span class="sb-time-resize" title="Drag to change end time" onpointerdown="event.stopPropagation();_sbResizeStart(event,'${w.id}',${Number(w.md_day_number||0)})"></span>`}
        </article>`;
      }).join('')}
    </div></div>`;
  }).join('');
  const backlog = (sb.backlog || []).slice(0,20);
  return `<div class="sb-timeline-layout"><aside class="sb-backlog"><header><strong>Unscheduled</strong><span>${sb.backlog.length}</span></header><p>Drag work onto a crew timeline.</p>${backlog.map(w=>`<article draggable="true" ondragstart="_sbDragStart(event,'${w.id}',${Number(w.md_day_number||0)})"><strong>${escapeHtml(w.client_name||w.title||'Job')}</strong><small>${escapeHtml(w.type||'Service')}</small></article>`).join('')||'<div class="sb-backlog-empty">All work is scheduled.</div>'}</aside><div class="sb-timeline-shell"><div class="sb-timeline-toolbar"><label>Date <input type="date" value="${date}" onchange="_sbTimelineDate(this.value)"></label><label>Snap <select onchange="_sbSetSnap(this.value)">${[15,30,60].map(n=>`<option value="${n}"${Number(sb.snapMinutes)===n?' selected':''}>${n} min</option>`).join('')}</select></label><span>Drag events to move them. Drag the bottom edge to change the end time.</span><button onclick="_sbUndo()"${sb.undoStack.length?'':' disabled'}>Undo</button></div><div class="sb-timeline-scroll"><div class="sb-timeline-grid" style="--timeline-crews:${crews.length}">${timeRail}${columns}</div></div></div></div>`;
}
function _sbAgendaHtml(sb, visibleWOs, allCrews) {
  const byDate = new Map();
  visibleWOs.slice().sort((a,b)=>String(a.scheduled_date||'').localeCompare(String(b.scheduled_date||''))||String(a.scheduled_time||'').localeCompare(String(b.scheduled_time||''))).forEach(w=>{const d=(w.scheduled_date||'Unscheduled').slice(0,10);if(!byDate.has(d))byDate.set(d,[]);byDate.get(d).push(w);});
  return `<div class="sb-agenda">${[...byDate].map(([date,jobs])=>`<section><header><strong>${date==='Unscheduled'?'Unscheduled':new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</strong><span>${jobs.length} visits</span></header>${jobs.map(w=>`<button onclick="_sbOpenVisitModal('${w.id}')"><time>${_sbDisplayTime(w.scheduled_time)||'Flexible'}${w.scheduled_end_time?' - '+_sbDisplayTime(w.scheduled_end_time):''}</time><span><strong>${escapeHtml(w.client_name||w.title||'Job')}</strong><small>${escapeHtml(w.md_phase_name||w.type||'Service')} · ${escapeHtml(w.crew_name||'Unassigned')}</small></span><em>${escapeHtml(_p6WOStatusLabel(w.status))}</em></button>`).join('')}</section>`).join('')||'<div class="sb-agenda-empty">No scheduled visits in this range.</div>'}</div>`;
}

function _sbMdWarningMap(rows) {
  const out = new Map();
  const byJob = new Map();
  (rows || []).filter(w => w.is_multiday || w.md_day_number).forEach(w => {
    if (!byJob.has(w.id)) byJob.set(w.id, []);
    byJob.get(w.id).push(w);
  });
  const dayVal = v => { const t = Date.parse(String(v || '') + 'T12:00:00Z'); return Number.isFinite(t) ? Math.round(t / 86400000) : null; };
  byJob.forEach(list => {
    const sorted = list.slice().sort((a,b)=>(Number(a.md_phase_sequence || a.md_day_number) - Number(b.md_phase_sequence || b.md_day_number)) || String(a.scheduled_date||'').localeCompare(String(b.scheduled_date||'')));
    for (let i=1;i<sorted.length;i++) {
      const prev = sorted[i-1], cur = sorted[i];
      const p = dayVal(prev.scheduled_date), c = dayVal(cur.scheduled_date);
      if (p == null || c == null) continue;
      let msg = '';
      const expected = p + 1 + (Number(cur.md_dependency_lag_days) || 0);
      if (c < expected) msg = 'Phase overlap';
      else if (c > expected) msg = 'Phase gap';
      if (msg) {
        out.set(cur.id + ':' + cur.md_day_number, msg);
        if (c <= p) out.set(prev.id + ':' + prev.md_day_number, msg);
      }
    }
  });
  return out;
}

/**
 * Service type -> colour. The card's FILL.
 *
 * Two channels, two meanings, everywhere:
 *
 *     fill        what kind of work it is   (this map)
 *     left border which crew has it         (--crew-color)
 *     badge       status                    (labelled, never colour alone)
 *
 * The written brief said crew = accent and stopped there. In crew-lane view the
 * ROW already says which crew, so spending the fill on it too says one thing
 * twice and nothing about the work. Tyler's mockup colours by service type, and
 * it is right — but only for the lane view. Week-column and month views have no
 * lanes, so crew has to live somewhere: it stays on the left border, which is
 * present in every view. Neither channel ever changes meaning depending on where
 * you are looking, which was the actual defect this replaces.
 *
 * Keys are matched case-insensitively against work_orders.type, which is free
 * text from a <select> and has drifted over the years — so 'Lawn Care',
 * 'lawn care' and 'Lawn' all land in the same bucket. Anything unrecognised
 * gets the neutral 'other' slate rather than a generated colour: a hash colour
 * would be stable but meaningless, and a legend cannot explain it.
 */
const _GW_TYPE_COLORS = {
  landscaping: '#2D7A55', landscape: '#2D7A55', install: '#2D7A55', planting: '#2D7A55',
  maintenance: '#3978C5', 'lawn care': '#3978C5', lawn: '#3978C5', mowing: '#3978C5', service: '#3978C5',
  hardscape: '#8B5CF6', masonry: '#8B5CF6', paver: '#8B5CF6',
  irrigation: '#D9564B', sprinkler: '#D9564B',
  drainage: '#D99A05', grading: '#D99A05',
  cleanup: '#0E9488', snow: '#64748B',
};
const _GW_TYPE_FALLBACK = '#94a3b8';

function _sbTypeColor(type) {
  const key = String(type || '').trim().toLowerCase();
  if (!key) return _GW_TYPE_FALLBACK;
  if (_GW_TYPE_COLORS[key]) return _GW_TYPE_COLORS[key];
  // Substring match so 'Landscape Construction' finds 'landscape'.
  for (const k in _GW_TYPE_COLORS) if (key.includes(k)) return _GW_TYPE_COLORS[k];
  return _GW_TYPE_FALLBACK;
}

/** The legend. Only types actually present this week, so it stays honest. */
function _sbTypeLegendHtml(visibleWOs) {
  const seen = [];
  for (const w of visibleWOs || []) {
    const t = String(w.type || '').trim();
    if (t && !seen.some(x => x.toLowerCase() === t.toLowerCase())) seen.push(t);
  }
  if (!seen.length) return '';
  const poolCount = (window._sbState.pool || []).length;
  return `<div class="sb-legend">
    ${seen.sort().map(t => `<span class="sb-legend-item"><i style="background:${_sbTypeColor(t)}"></i>${escapeHtml(t)}</span>`).join('')}
    ${poolCount ? `<span class="sb-legend-item sb-legend-item--pool"><i></i>Needs scheduling</span>` : ''}
    <span class="sb-legend-note">Fill is the service type · the left edge is the crew</span>
  </div>`;
}

function _sbJobCard(wo, crews, draggable) {
  const mdCrewId = wo.md_crew_id || wo.crew_id;
  const crew = crews.find(c=>c.id===mdCrewId);
  const crewColor = wo.crew_color || (crew?.color) || '#94a3b8';
  const statusCls = _p6WOStatusClass(wo.status);
  const timeStr = wo.scheduled_time ? wo.scheduled_time.slice(0,5) : '';
  const endStr  = wo.scheduled_end_time ? ' – '+wo.scheduled_end_time.slice(0,5) : '';
  const hrs = wo.duration_hours ? `${wo.duration_hours}h` : '';
  const isMd = !!(wo.is_multiday || wo.md_day_number);
  const mdColor = isMd ? _sbMdColor(wo.id) : crewColor;
  const phaseName = wo.md_phase_name || (wo.md_day_number ? 'Phase ' + wo.md_day_number : 'Multi-day plan');
  const mdWarn = isMd ? (window._sbMdWarnings && window._sbMdWarnings.get(wo.id + ':' + wo.md_day_number)) : '';
  return `
    <div class="sb-job-card ${statusCls}${isMd?' sb-job-card--multiday':''}${(window._sbState?.selectedDayId === `${wo.id}:${isMd ? Number(wo.md_day_number||0) : 0}`) ? ' is-selected' : ''}" data-status="${escapeHtml(wo.status||'scheduled')}" data-wo="${escapeHtml(wo.id||'')}" data-day="${escapeHtml(wo.md_day_id||'')}" style="--crew-color:${crewColor};--type-color:${_sbTypeColor(wo.type)};${isMd ? '--md-color:' + mdColor : ''}"        ${draggable ? `draggable="true" ondragstart="_sbDragStart(event,'${wo.id}',${isMd ? Number(wo.md_day_number||0) : 0})" ondragend="this.style.opacity=''"` : ''}
        onclick="_sbOpenDayRail('${wo.id}',${isMd ? Number(wo.md_day_number||0) : 0})">
      ${(() => {
        // Quick production details, on hover and on keyboard focus.
        //
        // Everything here is already in memory from the week payload — no
        // request, no fetch on hover. Only fields that actually have a value
        // are rendered: an empty row would teach people the panel is broken
        // rather than that the data is missing.
        const a = (window._sbState?.capacity?.assignments || []).find(x => x.day_id === wo.md_day_id);
        const rows = [];
        if (a && a.employees && a.employees.length) {
          const fm = a.employees.find(e => e.crew_role === 'foreman');
          rows.push(['Crew', `${a.employees.length} on site${fm ? ' · ' + escapeHtml(fm.rep_name) : ''}`]);
        }
        if (a && a.planned_minutes > 0) rows.push(['Planned', (a.planned_minutes / 60).toFixed(1) + 'h']);
        if (a && a.budget_minutes != null) rows.push(['Sold', (a.budget_minutes / 60).toFixed(1) + 'h']);
        if (wo.required_completion_date) rows.push(['Due', escapeHtml(gwDateFormat(wo.required_completion_date, { month:'short', day:'numeric' }))]);
        if (wo.access_notes) rows.push(['Access', escapeHtml(String(wo.access_notes).slice(0, 90))]);
        if (mdWarn) rows.push(['Warning', escapeHtml(mdWarn)]);
        if (!rows.length) return '';
        return `<div class="sb-card-hover" role="tooltip">
          <strong>${escapeHtml(wo.client_name || wo.title || 'Job')}</strong>
          ${wo.property_addr ? `<em>${escapeHtml(wo.property_addr)}</em>` : ''}
          <dl>${rows.map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>
        </div>`;
      })()}
      <div class="sb-card-top">
        <span class="sb-card-drag-handle" title="Drag to reschedule">
          <svg width="10" height="14" viewBox="0 0 10 14" fill="currentColor" opacity=".45">
            <circle cx="3" cy="2" r="1.3"/><circle cx="7" cy="2" r="1.3"/>
            <circle cx="3" cy="7" r="1.3"/><circle cx="7" cy="7" r="1.3"/>
            <circle cx="3" cy="12" r="1.3"/><circle cx="7" cy="12" r="1.3"/>
          </svg>
        </span>
        ${_p6WOTrafficDot(wo.status)}
        <span class="sb-card-num">${wo.wo_number||wo.id}</span>
        ${timeStr ? `<span class="sb-card-time">${timeStr}${endStr}</span>` : ''}
        ${isMd ? `<span class="sb-card-md-pill" title="Multi-day plan">Day ${escapeHtml(wo.md_day_number||'?')}/${escapeHtml(wo.total_days||'?')}</span>` : ''}
        ${mdWarn ? `<span class="sb-card-md-warn" title="${escapeHtml(mdWarn)}" aria-label="${escapeHtml(mdWarn)}"></span>` : ''}
        ${(() => {
          // Planned people-hours for THIS day, from the week payload that is
          // already loaded. Not calendar duration — the whole point of the four
          // numbers. Silent when nobody is on the day yet, because "0.0h" on a
          // card reads as a claim rather than an absence.
          const a = (window._sbState?.capacity?.assignments || []).find(x => x.day_id === wo.md_day_id);
          const mins = a ? a.planned_minutes : 0;
          return mins > 0 ? `<span class="sb-card-labor" title="Planned people-hours for this day">${(mins/60).toFixed(mins%60?1:0)}h</span>` : '';
        })()}
      </div>
      ${isMd ? `<div class="sb-card-md-marker"><span style="background:${mdColor}"></span>${escapeHtml(phaseName)}</div>` : ''}
      <div class="sb-card-client">${escapeHtml(wo.client_name||wo.title||'Job')}</div>
      ${crew||wo.crew_name ? `<div class="sb-card-crew" style="color:${crewColor}">${escapeHtml(wo.crew_name||crew?.name||'')}</div>` : ''}
      <div class="sb-card-meta">
        <span class="sb-card-type">${escapeHtml(wo.type||'Service')}</span>
        ${hrs ? `<span class="sb-card-hrs">${hrs}</span>` : ''}
        ${wo.md_dependency_type ? `<span class="sb-card-hrs" title="Dependency">after day ${escapeHtml(wo.md_depends_on_day_number||'')}</span>` : ''}
      </div>
      <span class="sb-card-status ops-ready-badge ${statusCls}">${_p6WOStatusLabel(wo.status)}</span>
    </div>`;
}

async function scheduleBoard() {
  const sb = window._sbState;

  // Show loading skeleton
  view.innerHTML = `<div class="sched-shell gw-workflow-cleanup sb-density-${sb.density}"><div style="padding:40px;text-align:center;color:var(--gw-text-muted)">
    <div class="sb-spinner"></div><p style="margin-top:12px">${(typeof window._t==='function')?window._t('Loading schedule…'):'Loading schedule…'}</p></div></div>`;

  if (!sb.loaded) await _sbLoadData();
  _sbRender();
}

function _sbRender() {
  const sb = window._sbState;
  const today = gwToday();
  const allCrews = sb.crews;
  const allWOs   = sb.workOrders;
  window._sbMdWarnings = _sbMdWarningMap(allWOs);
  window._sbConflicts = _sbConflictMap(allWOs);

  // Crew filter bar (toggle visibility per crew)
  const crewFilterBar = `
    <div class="sb-crew-bar">
      <div class="sb-crew-bar-chips">
        ${allCrews.length ? allCrews.map(cr=>{
          const active = !sb.hiddenCrews.has(cr.id);
          return `<button class="sb-crew-toggle${active?' active':''}" style="--crew-color:${cr.color}"
            onclick="_sbToggleCrew('${cr.id}')" title="${escapeHtml(cr.name)}">
            <span class="sb-crew-dot" style="background:${cr.color}"></span>
            ${escapeHtml(cr.name)}
            ${cr.members?.length ? `<span class="sb-crew-count">${cr.members.length}</span>` : ''}
          </button>`;
        }).join('') : `<span style="font-size:12px;color:var(--gw-text-muted)">No crews yet.</span>`}
      </div>
      <div class="sb-crew-bar-actions">
        ${sb.viewMode==='week' ? `<button class="sb-crew-lane-btn${sb.crewLanes?' active':''}" onclick="_sbToggleCrewLanes()" title="Toggle crew-lane rows">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="1" y="2" width="14" height="3" rx="1"/><rect x="1" y="7" width="14" height="3" rx="1"/><rect x="1" y="12" width="14" height="3" rx="1"/></svg>
          Crew Lanes
        </button>` : ''}
        <button class="sb-crew-manage-btn" onclick="show('userManagement','crews')">
          <svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor"><path d="M8 4a1 1 0 011 1v2h2a1 1 0 010 2H9v2a1 1 0 01-2 0V9H5a1 1 0 010-2h2V5a1 1 0 011-1z"/></svg>
          Manage Crews
        </button>
      </div>
    </div>`;

  // Filter WOs by visible crews
  const visibleWOs = allWOs.filter(wo => {
    const cid = wo.md_crew_id || wo.crew_id;
    if (!cid) return true;
    return !sb.hiddenCrews.has(cid);
  });

  let gridHtml = '';
  let headerLabel = '';

  const _sbT = (typeof window._t === 'function') ? window._t : (x => x);
  if (sb.viewMode === 'timeline') {
    headerLabel = new Date((sb.timelineDate || today) + 'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',year:'numeric'});
    gridHtml = _sbTimelineHtml(sb, visibleWOs, allCrews);
  } else if (sb.viewMode === 'agenda') {
    const days = _sbGetWeekDays(sb.weekOffset);
    headerLabel = `${days[0].toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${days[6].toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;
    gridHtml = _sbAgendaHtml(sb, visibleWOs, allCrews);
  } else if (sb.viewMode === 'week') {
    const days = _sbGetWeekDays(sb.weekOffset);
    const wdNames = [_sbT('Sun'),_sbT('Mon'),_sbT('Tue'),_sbT('Wed'),_sbT('Thu'),_sbT('Fri'),_sbT('Sat')];
    headerLabel = `${days[0].toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${days[6].toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;

    if (sb.crewLanes && allCrews.length) {
      // ── Crew-Lane week view ──────────────────────────────────────────────────
      // ONE unified grid: header row + one row per crew. All cells share column
      // widths and row heights automatically because they are in the same grid.

      // One lane per visible crew. Nothing else.
      //
      // There used to be an "Unassigned" lane pinned above the real crews, and
      // it was two things at once, neither of them a crew. Blue Crew has a lane
      // because Blue Crew occupies production capacity on Tuesday; an
      // unscheduled job does not occupy Tuesday at 7am. Worse, the lane only
      // held jobs that had a DATE but no crew — genuinely unscheduled work never
      // appeared in it at all, and lived only in the timeline view's separate
      // aside. A job created from this view could vanish from this view.
      //
      // Both cases now live in the Job Pool beside the grid (_sbPoolHtml).
      const laneCrews = allCrews.filter(c=>!sb.hiddenCrews.has(c.id));

      // Header cells (corner + 7 day heads)
      const headerCells = `
        <div class="sb-lane-corner"></div>
        ${days.map(d=>{
          const iso = gwDateISO(d);
          const isToday = iso===today;
          return `<div class="sb-lane-day-head${isToday?' today':''}">
            <span class="sb-day-name">${wdNames[d.getDay()]}</span>
            <span class="sb-day-date">${d.getDate()}</span>
          </div>`;
        }).join('')}`;

      // One label + 7 cells per crew row — all flat inside the single grid
      const crewCells = laneCrews.map(cr=>{
        const crewWeekJobs = visibleWOs.filter(w => (w.md_crew_id || w.crew_id) === cr.id);
        const scheduledHours = crewWeekJobs.reduce((sum,w)=>sum+(_sbEventRange(w).duration/60),0);
        // Capacity from /api/scheduling/week: crew members x productive minutes
        // x working days. This used to be a hardcoded 40, which made the
        // percentage meaningless for any crew that was not one person on a
        // 40-hour week — a three-person crew was permanently shown as
        // over-booked. capMeta is null for the Unassigned lane (not a real
        // crew), when the fetch failed, or when nobody is on the crew.
        const capMeta = window._sbState.capacity
          ? (window._sbState.capacity.crews || []).find(c => c.id === cr.id)
          : null;
        const weeklyCapacityHours = capMeta ? (capMeta.week_capacity_minutes / 60) : 0;
        // Utilisation compares LABOR to LABOR. scheduledHours above is calendar
        // time — how long the jobs block the grid — and capacity is people-hours,
        // so dividing one by the other is the same units mix-up this whole engine
        // exists to remove: a two-person crew on an 8-hour job consumes 16
        // people-hours, not 8. The numerator is therefore week_planned_minutes,
        // summed from wo_day_employees.
        //
        // null, never 0 — a crew with nobody on it is not "0% utilised", the
        // number is undefined, and nobody assigned to the work yet is not the
        // same as an empty week.
        const plannedHours = capMeta ? (capMeta.week_planned_minutes / 60) : 0;
        const utilization = (capMeta && capMeta.week_capacity_minutes > 0)
          ? capMeta.week_utilization_pct
          : null;
        // Four genuinely different situations, and they must not share wording:
        //
        //   not a real crew        the Unassigned lane — no capacity to speak of
        //   crew with no members   there is nobody to do the work
        //   nothing booked         the crew is free; show how much room it has,
        //                          which is the most useful thing on an empty week
        //   booked but no labor    jobs are on the grid but wo_day_employees has
        //                          not been populated for them yet
        //
        // The third and fourth used to share "nobody assigned yet", which read as
        // a data problem on a week that was simply empty and — worse — hid the
        // capacity figure entirely.
        const hasJobs = crewWeekJobs.length > 0;
        const utilLabel = !capMeta
          ? '—'
          : capMeta.member_count === 0
            ? 'no crew assigned'
            : capMeta.week_planned_minutes === 0
              ? (hasJobs
                  ? 'booked, labor not assigned yet'
                  : weeklyCapacityHours.toFixed(0) + 'h open')
              : plannedHours.toFixed(1) + 'h of ' + weeklyCapacityHours.toFixed(0) + 'h · ' + utilization + '%';
        const dayCells = days.map(d=>{
          const iso = gwDateISO(d);
          const isToday = iso===today;
          const jobs = visibleWOs.filter(w => (w.md_crew_id || w.crew_id)===cr.id && w.scheduled_date?.slice(0,10)===iso);
          return `<div class="sb-lane-cell${isToday?' today':''}"
              data-date="${iso}" data-crew="${cr.id}"
              ondragover="event.preventDefault();this.classList.add('drag-over')"
              ondragleave="this.classList.remove('drag-over')"
              ondrop="_sbDropOnCell(event,'${iso}','${cr.id}')">
            ${jobs.map(wo=>_sbJobCard(wo,allCrews,true)).join('')}
            <button class="sb-lane-add-btn" onclick="_sbOpenNewVisit('${iso}','${cr.id}')">+</button>
          </div>`;
        }).join('');
        return `
          <div class="sb-lane-label" style="border-left:3px solid ${cr.color}">
            <span class="sb-lane-crew-head">
              <span class="sb-lane-crew-badge" style="background:${cr.color}">${escapeHtml((cr.name||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span>
              <span class="sb-lane-crew-id">
                <b>${escapeHtml(cr.name)}</b>
                <!-- Foreman and headcount: who to call, and how many bodies.
                     Both come from the crew roster the capacity figure is
                     already derived from, so they cost no extra request. -->
                <em>${capMeta && capMeta.members && capMeta.members.length
                  ? escapeHtml((capMeta.members.find(m=>m.crew_role==='foreman')||{}).rep_name || 'No foreman')
                    + ' · ' + capMeta.members.length + (capMeta.members.length===1?' person':' people')
                  : 'No crew members'}</em>
              </span>
            </span>
            <span class="sb-lane-cap" title="Planned people-hours against this crew's productive capacity. Booked is calendar time on the grid — a different number.">
              <span class="sb-lane-cap-nums">${capMeta ? (capMeta.week_planned_minutes/60).toFixed(1) + 'h / ' + (capMeta.week_capacity_minutes/60).toFixed(0) + 'h' : scheduledHours.toFixed(1) + 'h booked'}</span>
              ${utilization !== null ? `<span class="sb-lane-cap-pct${utilization > 100 ? ' is-over' : ''}">${utilization}%</span>` : ''}
            </span>
            <i class="sb-lane-bar"><b style="width:${utilization === null ? 0 : Math.min(100,utilization)}%;${utilization !== null && utilization > 100 ? 'background:#d84b42' : ''}"></b></i>
          </div>
          ${dayCells}`;
      }).join('');

      gridHtml = `<div class="sb-lane-wrap"><div class="sb-lane-grid">${headerCells}${crewCells}</div></div>`;

    } else {
      // ── Standard column week view ────────────────────────────────────────────
      const cols = days.map(d => {
        const iso = gwDateISO(d);
        const isToday = iso === today;
        const jobs = visibleWOs.filter(w => w.scheduled_date && w.scheduled_date.slice(0,10) === iso);
        return `
          <div class="sb-day-col${isToday?' sb-day-col--today':''}"
              data-date="${iso}"
              ondragover="event.preventDefault();this.querySelector('.sb-day-body').classList.add('drag-over')"
              ondragleave="this.querySelector('.sb-day-body').classList.remove('drag-over')"
              ondrop="_sbDropOnCell(event,'${iso}',null)">
            <div class="sb-day-head">
              <span class="sb-day-name">${wdNames[d.getDay()]}</span>
              <span class="sb-day-date">${d.getDate()}</span>
              ${jobs.length ? `<span class="sb-day-count">${jobs.length}</span>` : ''}
            </div>
            <div class="sb-day-body">
              ${jobs.map(wo => _sbJobCard(wo, allCrews, true)).join('') || '<div class="sb-empty-day">No jobs</div>'}
              <button class="sb-add-btn" onclick="_sbOpenNewVisit('${iso}',null)">+</button>
            </div>
          </div>`;
      });
      gridHtml = `<div class="sb-week-grid">${cols.join('')}</div>`;
    }

  } else {
    // ── Month view ─────────────────────────────────────────────────────────────
    const { first, last, month } = _sbGetMonthDays(sb.monthOffset);
    headerLabel = month;
    const startDow = first.getDay();
    const totalDays = last.getDate();
    let cells = '';
    for (let i=0;i<startDow;i++) cells += `<div class="sb-month-cell sb-month-cell--blank"></div>`;
    for (let d=1;d<=totalDays;d++) {
      const iso = `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const isToday = iso === today;
      const jobs = visibleWOs.filter(w => w.scheduled_date && w.scheduled_date.slice(0,10) === iso);
      const dots = jobs.slice(0,5).map(wo => {
        // ONE meaning per channel: the dot is the CREW, exactly as this
        // comment always claimed. It was calling _sbStatusColor, so a month cell
        // showed status in its dots and crew in its chips three lines later,
        // while mobile month used crew for both — three meanings for a dot
        // across three views, with no legend anywhere. Status still shows,
        // through the --hold / --cancelled modifier classes and the title.
        const isMd = !!(wo.is_multiday || wo.md_day_number);
        const dotColor = wo.crew_color || (crews||[]).find(c=>c.id===(wo.md_crew_id||wo.crew_id))?.color || '#94a3b8';
        const mdTitle = isMd ? ` Day ${wo.md_day_number||'?'}${wo.md_phase_name ? ' - ' + wo.md_phase_name : ''}` : '';
        return `<span class="sb-month-dot${wo.status==='hold' ? ' sb-month-dot--hold' : ''}${isMd ? ' sb-month-dot--multiday' : ''}" style="background:${dotColor}" title="${escapeHtml(wo.client_name||wo.wo_number)}${escapeHtml(mdTitle)}${wo.status==='hold' ? ' - HOLD (awaiting acceptance)' : ''}"></span>`;
      }).join('');
      cells += `
        <div class="sb-month-cell${isToday?' sb-month-cell--today':''}"
            data-date="${iso}"
            ondragover="event.preventDefault();this.classList.add('drag-over')"
            ondragleave="this.classList.remove('drag-over')"
            ondrop="_sbDropOnCell(event,'${iso}',null)"
            onclick="_sbOpenDaySummary('${iso}')">
          <div class="sb-month-num">${d}</div>
          ${jobs.length ? `<div class="sb-month-dots">${dots}${jobs.length>5?`<span class="sb-month-more">+${jobs.length-5}</span>`:''}</div>` : ''}
          ${jobs.slice(0,3).map(wo=>{
            const isMd = !!(wo.is_multiday || wo.md_day_number);
            const crewColor = isMd ? _sbMdColor(wo.id) : (wo.crew_color || allCrews.find(c=>c.id===wo.crew_id)?.color || '#94a3b8');            const mdText = isMd ? `D${wo.md_day_number||'?'} ${wo.md_phase_name || ''}`.trim() + ' - ' : '';
            return `<div class="sb-month-chip${wo.status==='hold' ? ' sb-month-chip--hold' : ''}${isMd ? ' sb-month-chip--multiday' : ''}" style="border-left:2px solid ${crewColor};${isMd ? '--md-color:' + crewColor : ''}" onclick="event.stopPropagation();_sbOpenVisitModal('${wo.id}')">
              ${_p6WOTrafficDot(wo.status)} ${escapeHtml((mdText + (wo.client_name||wo.title||'Job')).slice(0,26))}
            </div>`;
          }).join('')}
          ${jobs.length>3 ? `<div class="sb-month-more-link">+${jobs.length-3} more</div>` : ''}
        </div>`;
    }
    const _sbT2 = (typeof window._t === 'function') ? window._t : (x => x);
    const dowHeaders = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(n=>`<div class="sb-month-dow">${_sbT2(n)}</div>`).join('');
    gridHtml = `<div class="sb-month-grid">${dowHeaders}${cells}</div>`;
  }

  // Stats bar
  const totalScheduled  = visibleWOs.filter(w=>w.status==='scheduled').length;
  const totalHolds      = visibleWOs.filter(w=>w.status==='hold').length;
  const totalInProgress = visibleWOs.filter(w=>w.status==='in-progress').length;
  const totalCompleted  = visibleWOs.filter(w=>w.status==='completed').length;
  const totalUniqueJobs = new Set(visibleWOs.map(w=>w.id)).size;
  const totalMultiDayPlans = new Set(visibleWOs.filter(w=>w.is_multiday || w.md_day_number).map(w=>w.id)).size;

  // ── Mobile layout (≤768px): day-list view ────────────────────────────────
  if (window.innerWidth <= 768) {
    _sbRenderMobile(sb, visibleWOs, allCrews, allWOs, totalScheduled, totalInProgress, totalCompleted, headerLabel, gridHtml, crewFilterBar);
    return;
  }

  view.innerHTML = `
  <div class="sched-shell sb-workstation gw-workflow-cleanup sb-density-${sb.density}">

    <!-- Command bar: one compact row. The board is the product, and an
         oversized page title spends the vertical space the week needs. -->
    <div class="sb-cmd">
      <div class="sb-cmd-left">
        <div class="sb-weeknav">
          <button class="sb-nav-btn" onclick="_sbNav(-1)" aria-label="Previous period" title="Previous">&lsaquo;</button>
          <span class="sb-period-label">${headerLabel}</span>
          <button class="sb-nav-btn" onclick="_sbNav(1)" aria-label="Next period" title="Next">&rsaquo;</button>
        </div>
        <button class="sb-today-btn" onclick="_sbGoToday()">Today</button>
      </div>
      <div class="sb-cmd-right">
        <div class="sb-view-toggle" role="tablist" aria-label="Schedule view">
          ${['timeline','week','month','agenda'].map(v => `<button role="tab" aria-selected="${sb.viewMode===v}" class="sb-view-btn${sb.viewMode===v?' active':''}" onclick="_sbSetView('${v}')">${v.charAt(0).toUpperCase()+v.slice(1)}</button>`).join('')}
        </div>
        <select class="sb-density-select" onchange="_sbSetDensity(this.value)" aria-label="Board density" title="Board density">
          ${['compact','comfortable','detailed'].map(d => `<option value="${d}"${sb.density===d?' selected':''}>${d.charAt(0).toUpperCase()+d.slice(1)}</option>`).join('')}
        </select>
        <button class="sb-icon-btn" onclick="_sbToggleMetrics()" title="${sb.showMetrics?'Hide metrics':'Show metrics'}" aria-label="Toggle metrics">&#9707;</button>
        <button class="gwp-btn-primary sb-newjob" onclick="_sbOpenJobBuilder()">+ Job</button>
      </div>
    </div>

    ${sb.showMetrics ? _sbKpiBandHtml(totalScheduled, totalUniqueJobs) : ''}
    ${crewFilterBar}

    <!-- Job Pool | production board | Job Day rail, as ONE grid rather than
         three floated panels — so the board absorbs every pixel the other two
         are not using, and the page never scrolls sideways. -->
    <div class="sb-workspace${sb.poolCollapsed ? ' is-pool-collapsed' : ''}${sb.selectedDayId ? ' has-rail' : ''}">
      ${['week','month'].includes(sb.viewMode) ? _sbPoolHtml() : ''}
      <main class="sb-board" aria-label="Production schedule">
        ${gridHtml}
        ${['week','month','timeline'].includes(sb.viewMode) ? _sbTypeLegendHtml(visibleWOs) : ''}
      </main>
      ${sb.selectedDayId ? _sbDayRailHtml() : ''}
    </div>
  </div>`;
}

window.scheduleBoard = scheduleBoard;
window._sbNav = function(dir) {
  const sb = window._sbState;
  if (sb.viewMode === 'timeline') {
    const d = new Date((sb.timelineDate || gwToday()) + 'T12:00:00');
    d.setDate(d.getDate() + dir);
    sb.timelineDate = gwDateISO(d);
  } else if (sb.viewMode === 'month') sb.monthOffset += dir;
  else sb.weekOffset += dir;
  if (sb.viewMode === 'week' || sb.viewMode === 'agenda') {
    const days = _sbGetWeekDays(sb.weekOffset);
    sb.mobileSelectedDay = gwDateISO(days[0]);
  }
  _sbRefresh();
};
window._sbGoToday = function() {
  const today = gwToday();
  window._sbState.weekOffset = 0;
  window._sbState.monthOffset = 0;
  window._sbState.timelineDate = today;
  window._sbState.mobileSelectedDay = today;
  _sbRefresh();
};
window._sbSetView = function(v) { window._sbState.viewMode = v; _sbSavePreferences(); _sbRefresh(); };
window._sbSetDensity = function(v) { window._sbState.density = ['compact','comfortable','detailed'].includes(v) ? v : 'compact'; _sbSavePreferences(); _sbRender(); };
window._sbToggleMetrics = function() { window._sbState.showMetrics = !window._sbState.showMetrics; _sbSavePreferences(); _sbRender(); };
window._sbSetSnap = function(v) { window._sbState.snapMinutes = Number(v) || 15; _sbSavePreferences(); _sbRender(); };
window._sbTimelineDate = function(v) { if (v) window._sbState.timelineDate = v; _sbRefresh(); };
window._sbToggleCrew = function(id) {
  const sb = window._sbState;
  if (sb.hiddenCrews.has(id)) sb.hiddenCrews.delete(id); else sb.hiddenCrews.add(id);
  _sbRender();
};
window._sbRefresh = async function() {
  window._sbState.loaded = false;
  await _sbLoadData();
  _sbRender();
};
/**
 * Re-read crew capacity for the visible week and repaint.
 *
 * Cheaper than _sbRefresh() — one request instead of five, and it keeps the
 * optimistic move already painted on the grid. Used after a write that moved a
 * job but whose result is already reflected locally: without it the lane metric
 * keeps the capacity figures from before the move and drifts away from the grid
 * it sits next to.
 *
 * Silent on failure: a stale percentage is a much smaller problem than an error
 * toast on top of a drag that actually succeeded.
 */
/**
 * Fill the Hours card in the visit modal: sold vs planned vs actual.
 *
 * Three numbers the CRM used to collapse into one. From
 * GET /api/scheduling/work-orders/:id/hours:
 *
 *   budget   what the estimate sold (null when the job came from no estimate)
 *   planned  what we intend to spend, summed from wo_day_employees
 *   actual   what it took, NET of breaks
 *
 * "No budget" is rendered as such rather than as zero or as on-target — a job
 * with nothing to compare against is a different statement from a job that
 * landed exactly on its number.
 */
window._sbLoadHours = async function(woId) {
  const host = document.getElementById('sbm-hours');
  if (!host) return;
  const h = m => (Number(m || 0) / 60).toFixed(1) + 'h';
  try {
    const r = await fetch(`/api/scheduling/work-orders/${encodeURIComponent(woId)}/hours`, { credentials: 'include' });
    const d = await r.json();
    if (!d || !d.ok) throw new Error(d && d.error);

    const cell = (label, value, hint, tone) =>
      `<div class="sb-hours-cell${tone ? ' sb-hours-cell--' + tone : ''}">
         <span class="sb-hours-label">${escapeHtml(label)}</span>
         <strong class="sb-hours-value">${escapeHtml(value)}</strong>
         ${hint ? `<span class="sb-hours-hint">${escapeHtml(hint)}</span>` : ''}
       </div>`;

    let varianceCell;
    if (d.budget_minutes == null) {
      varianceCell = cell('Vs. sold', 'no budget', 'this job came from no estimate', null);
    } else if (d.actual_minutes === 0) {
      varianceCell = cell('Vs. sold', 'not started', 'no time logged yet', null);
    } else {
      const over = d.variance_minutes > 0;
      varianceCell = cell(
        'Vs. sold',
        (over ? '+' : '') + (d.variance_minutes / 60).toFixed(1) + 'h',
        over ? 'over what we sold' : 'under what we sold',
        over ? 'over' : 'under',
      );
    }

    host.innerHTML =
      cell('Sold', d.budget_minutes == null ? '—' : h(d.budget_minutes), 'from the estimate') +
      cell('Planned', h(d.planned_minutes), 'people-hours booked') +
      cell('Actual', h(d.actual_minutes), d.break_minutes > 0 ? `net of ${h(d.break_minutes)} break` : 'net of breaks') +
      varianceCell;
  } catch (e) {
    host.innerHTML = '<span class="muted" style="font-size:12px">Hours unavailable</span>';
  }
};

window._sbRefreshCapacity = async function() {
  try {
    const range = _sbCurrentDateRange();
    const r = await fetch('/api/scheduling/week?start=' + encodeURIComponent(range.from), { credentials: 'include' });
    const d = await r.json();
    window._sbState.capacity = (d && d.ok) ? d : window._sbState.capacity;
    _sbRender();
  } catch (_) { /* keep the previous figures */ }
};

/**
 * Fold the capacity a scheduling write returned into the lane metrics.
 *
 * The write reports every (crew, date) it touched — the lane the job left as
 * well as the one it joined — so both bars can be corrected without re-reading
 * the whole week. Anything not mentioned is left exactly as it was.
 *
 * Week totals are recomputed from the per-day figures rather than patched, so
 * the header and the columns underneath it cannot drift apart.
 */
window._sbApplyCapacity = function(capacity) {
  const cap = window._sbState.capacity;
  if (!cap || !Array.isArray(capacity) || !capacity.length) {
    // Nothing usable came back — fall back to the old behaviour rather than
    // leaving stale numbers on screen.
    return _sbRefreshCapacity();
  }
  for (const entry of capacity) {
    const crew = (cap.crews || []).find(c => c.id === entry.crew_id);
    if (!crew) continue;
    const day = (crew.days || []).find(d => d.date === entry.date);
    if (!day) continue;
    day.capacity_minutes = entry.capacity_minutes;
    day.planned_minutes  = entry.planned_minutes;
    day.utilization_pct  = entry.utilization_pct;
  }
  for (const crew of (cap.crews || [])) {
    crew.week_capacity_minutes = (crew.days || []).reduce((sum, d) => sum + (d.capacity_minutes || 0), 0);
    crew.week_planned_minutes  = (crew.days || []).reduce((sum, d) => sum + (d.planned_minutes  || 0), 0);
    // null, not 0, when there is no capacity to divide by — the same rule the
    // server applies. See src/scheduling/capacity.ts.
    crew.week_utilization_pct = crew.week_capacity_minutes > 0
      ? Math.round((crew.week_planned_minutes / crew.week_capacity_minutes) * 100)
      : null;
  }
  _sbRender();
};
window._sbSelectDay = function(iso) {
  window._sbState.mobileSelectedDay = iso;
  _sbRender();
};

// ── Mobile schedule render ────────────────────────────────────────────────────
function _sbRenderMobile(sb, visibleWOs, allCrews, allWOs, totalScheduled, totalInProgress, totalCompleted, headerLabel, _gridHtml, _crewFilterBar) {
  const today = gwToday();
  const _mT = (typeof window._t === 'function') ? window._t : (x => x);
  const wdNames = [_mT('Sun'),_mT('Mon'),_mT('Tue'),_mT('Wed'),_mT('Thu'),_mT('Fri'),_mT('Sat')];
  const wdShort = ['S','M','T','W','T','F','S'];

  // Month view on mobile — use a compact grid
  if (sb.viewMode === 'month') {
    const { first, last, month } = _sbGetMonthDays(sb.monthOffset);
    const startDow = first.getDay();
    const totalDays = last.getDate();
    let cells = '';
    for (let i=0;i<startDow;i++) cells += `<div class="sbm-month-blank"></div>`;
    for (let d=1;d<=totalDays;d++) {
      const iso = `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const isToday = iso === today;
      const isSelected = iso === (sb.mobileSelectedDay || today);
      const jobs = visibleWOs.filter(w => w.scheduled_date?.slice(0,10) === iso);
      cells += `<button class="sbm-month-day${isToday?' is-today':''}${isSelected?' is-selected':''}" onclick="_sbSelectDay('${iso}')">
        <span class="sbm-month-num">${d}</span>
        ${jobs.length ? `<span class="sbm-month-dot-row">${jobs.slice(0,3).map(wo=>{
          const c = wo.crew_color || allCrews.find(cr=>cr.id===wo.crew_id)?.color || '#94a3b8';
          return `<span style="width:5px;height:5px;border-radius:50%;background:${c};display:inline-block"></span>`;
        }).join('')}${jobs.length>3?`<span style="font-size:8px;color:var(--gw-text-muted)">+</span>`:''}</span>` : ''}
      </button>`;
    }
    const dowHeaders = wdShort.map(n=>`<div class="sbm-month-dow">${n}</div>`).join('');

    // Day detail panel for selected day
    const selDay = sb.mobileSelectedDay || today;
    const selJobs = visibleWOs.filter(w => w.scheduled_date?.slice(0,10) === selDay);
    const selDate = new Date(selDay + 'T12:00:00');
    const selLabel = selDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});

    view.innerHTML = `
    <div class="sched-shell sbm-shell gw-workflow-cleanup">
      <!-- Compact header -->
      <div class="sbm-header">
        <div class="sbm-header-row1">
          <div class="sbm-title-nav">
            <button class="sbm-nav-btn" onclick="_sbNav(-1)">‹</button>
            <span class="sbm-period">${month}</span>
            <button class="sbm-nav-btn" onclick="_sbNav(1)">›</button>
          </div>
          <div class="sbm-header-actions">
            <button class="sbm-today-btn" onclick="_sbGoToday()">Today</button>
            <button class="sbm-new-btn" onclick="_sbOpenNewVisit(null,null)">+ New</button>
          </div>
        </div>
        <div class="sbm-view-strip">
          <button class="sbm-view-btn" onclick="_sbSetView('week')">Week</button>
          <button class="sbm-view-btn active" onclick="_sbSetView('month')">Month</button>
          <button class="sbm-view-btn" onclick="show('dispatchBoard')">Dispatch</button>
        </div>
      </div>

      <!-- Month grid -->
      <div class="sbm-month-grid">
        ${dowHeaders}
        ${cells}
      </div>

      <!-- Selected day jobs -->
      <div class="sbm-day-panel">
        <div class="sbm-day-panel-head">
          <span class="sbm-day-panel-label">${selLabel}</span>
          <button class="sbm-add-day-btn" onclick="_sbOpenNewVisit('${selDay}',null)">+ Add</button>
        </div>
        ${selJobs.length
          ? selJobs.map(wo => _sbMobileJobCard(wo, allCrews)).join('')
          : `<div class="sbm-empty">No jobs scheduled</div>`
        }
      </div>

      <!-- Crew chips scroll -->
      <div class="sbm-crew-strip">
        ${allCrews.map(cr=>{
          const active = !sb.hiddenCrews.has(cr.id);
          return `<button class="sbm-crew-chip${active?' active':''}" style="--cc:${cr.color}" onclick="_sbToggleCrew('${cr.id}')">
            <span class="sbm-crew-dot" style="background:${cr.color}"></span>${escapeHtml(cr.name)}
          </button>`;
        }).join('')}
      </div>
    </div>`;
    return;
  }

  // ── Week view on mobile: day-strip + single-day list ──────────────────────
  const days = _sbGetWeekDays(sb.weekOffset);
  headerLabel = `${days[0].toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${days[6].toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;

  // Determine selected day
  if (!sb.mobileSelectedDay) {
    // Auto-select today if in current week, else first day
    const todayInWeek = days.find(d=>gwDateISO(d)===today);
    sb.mobileSelectedDay = todayInWeek ? today : gwDateISO(days[0]);
  }
  // Ensure selected day is in current week
  const weekIsos = days.map(d=>gwDateISO(d));
  if (!weekIsos.includes(sb.mobileSelectedDay)) {
    sb.mobileSelectedDay = weekIsos[0];
  }

  // Day strip: 7 tappable day chips
  const dayStrip = days.map(d => {
    const iso = gwDateISO(d);
    const isToday = iso === today;
    const isSelected = iso === sb.mobileSelectedDay;
    const jobCount = visibleWOs.filter(w=>w.scheduled_date?.slice(0,10)===iso).length;
    return `<button class="sbm-day-chip${isToday?' is-today':''}${isSelected?' is-selected':''}" onclick="_sbSelectDay('${iso}')">
      <span class="sbm-chip-wd">${wdShort[d.getDay()]}</span>
      <span class="sbm-chip-date">${d.getDate()}</span>
      ${jobCount ? `<span class="sbm-chip-dot"></span>` : '<span class="sbm-chip-dot sbm-chip-dot--empty"></span>'}
    </button>`;
  }).join('');

  // Jobs for selected day
  const selDay = sb.mobileSelectedDay;
  const selJobs = visibleWOs.filter(w=>w.scheduled_date?.slice(0,10)===selDay);
  const selDate = new Date(selDay + 'T12:00:00');
  const selLabel = selDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});

  // Crew lanes for selected day (if enabled)
  let dayContent = '';
  if (sb.crewLanes && allCrews.length) {
    // Real crews only — the Unassigned pseudo-lane is retired here too. On
    // mobile it was already hidden when empty, which meant work with no crew
    // was sometimes visible and sometimes not, with nothing to tell you which.
    const laneCrews = allCrews.filter(c=>!sb.hiddenCrews.has(c.id));
    dayContent = laneCrews.map(cr => {
      const crewJobs = selJobs.filter(w=>(w.md_crew_id || w.crew_id)===cr.id);
      return `<div class="sbm-crew-lane">
        <div class="sbm-crew-lane-head" style="border-left:3px solid ${cr.color}">
          <span class="sbm-crew-lane-dot" style="background:${cr.color}"></span>
          <span class="sbm-crew-lane-name">${escapeHtml(cr.name)}</span>
          <span class="sbm-crew-lane-count">${crewJobs.length} job${crewJobs.length!==1?'s':''}</span>
          <button class="sbm-add-lane-btn" onclick="_sbOpenNewVisit('${selDay}','${cr.id}')">+</button>
        </div>
        ${crewJobs.map(wo=>_sbMobileJobCard(wo,allCrews)).join('') || `<div class="sbm-lane-empty">No jobs</div>`}
      </div>`;
    }).join('');
  } else {
    dayContent = selJobs.length
      ? selJobs.map(wo=>_sbMobileJobCard(wo,allCrews)).join('')
      : `<div class="sbm-empty">No jobs scheduled for this day</div>`;
  }

  // Stat summary — compact single row
  const statSummary = `<div class="sbm-stat-row">
    <span class="sbm-stat-pill">${totalScheduled} scheduled</span>
    ${totalInProgress ? `<span class="sbm-stat-pill sbm-stat-pill--blue">${totalInProgress} in progress</span>` : ''}
    ${totalCompleted ? `<span class="sbm-stat-pill sbm-stat-pill--green">${totalCompleted} done</span>` : ''}
    <span class="sbm-stat-pill sbm-stat-pill--muted">${allCrews.length} crew${allCrews.length!==1?'s':''}</span>
  </div>`;

  view.innerHTML = `
  <div class="sched-shell sbm-shell gw-workflow-cleanup">
    <!-- Compact mobile header -->
    <div class="sbm-header">
      <div class="sbm-header-row1">
        <div class="sbm-title-nav">
          <h1 class="sbm-title">Schedule</h1>
          <button class="sbm-nav-btn" onclick="_sbNav(-1)">‹</button>
          <span class="sbm-period">${headerLabel}</span>
          <button class="sbm-nav-btn" onclick="_sbNav(1)">›</button>
        </div>
        <div class="sbm-header-actions">
          <button class="sbm-today-btn" onclick="_sbGoToday()">Today</button>
          <button class="sbm-new-btn" onclick="_sbOpenNewVisit(null,null)">+ New</button>
        </div>
      </div>

      <!-- View mode strip -->
      <div class="sbm-view-strip">
        <button class="sbm-view-btn active" onclick="_sbSetView('week')">Week</button>
        <button class="sbm-view-btn" onclick="_sbSetView('month')">Month</button>
        <button class="sbm-view-btn" onclick="_sbToggleCrewLanes()" style="${sb.crewLanes?'background:var(--gw-pine-500,#2D7A55);color:#fff;':''}">
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2"><rect x="1" y="2" width="14" height="3" rx="1"/><rect x="1" y="7" width="14" height="3" rx="1"/><rect x="1" y="12" width="14" height="3" rx="1"/></svg>
          Lanes
        </button>
        <button class="sbm-view-btn" onclick="show('dispatchBoard')">Dispatch</button>
      </div>
    </div>

    <!-- Stat summary strip -->
    ${statSummary}

    <!-- Crew filter chips (horizontal scroll) -->
    <div class="sbm-crew-strip">
      ${allCrews.map(cr=>{
        const active = !sb.hiddenCrews.has(cr.id);
        return `<button class="sbm-crew-chip${active?' active':''}" style="--cc:${cr.color}" onclick="_sbToggleCrew('${cr.id}')">
          <span class="sbm-crew-dot" style="background:${cr.color}"></span>${escapeHtml(cr.name)}
          ${cr.members?.length ? `<span class="sbm-crew-cnt">${cr.members.length}</span>` : ''}
        </button>`;
      }).join('')}
      <button class="sbm-crew-chip sbm-crew-chip--manage" onclick="show('userManagement','crews')">+ Manage</button>
    </div>

    <!-- Day selector strip -->
    <div class="sbm-day-strip">
      ${dayStrip}
    </div>

    <!-- Selected day label + add button -->
    <div class="sbm-day-header">
      <span class="sbm-day-label">${selLabel}</span>
      <button class="sbm-add-day-btn" onclick="_sbOpenNewVisit('${selDay}',null)">+ Job</button>
    </div>

    <!-- Day content: job cards / crew lanes -->
    <div class="sbm-day-content">
      ${dayContent || `<div class="sbm-empty">No jobs scheduled for this day</div>`}
    </div>

    <!-- Bottom padding for nav bar -->
    <div style="height:80px"></div>
  </div>`;
}

// Mobile job card — more touch-friendly than the desktop card
function _sbMobileJobCard(wo, crews) {
  const mdCrewId = wo.md_crew_id || wo.crew_id;
  const crew = crews.find(c=>c.id===mdCrewId);
  const crewColor = wo.crew_color || (crew?.color) || '#94a3b8';
  const statusCls = _p6WOStatusClass(wo.status);
  const timeStr = wo.scheduled_time ? wo.scheduled_time.slice(0,5) : '';
  const endStr  = wo.scheduled_end_time ? ' - '+wo.scheduled_end_time.slice(0,5) : '';
  const isMd = !!(wo.is_multiday || wo.md_day_number);
  const mdColor = isMd ? _sbMdColor(wo.id) : crewColor;
  const phaseName = wo.md_phase_name || (wo.md_day_number ? 'Phase ' + wo.md_day_number : 'Multi-day plan');
  const mdWarn = isMd ? (window._sbMdWarnings && window._sbMdWarnings.get(wo.id + ':' + wo.md_day_number)) : '';
  return `
  <div class="sbm-job-card ${statusCls}${isMd?' sbm-job-card--multiday':''}" style="border-left:4px solid ${crewColor};${isMd ? '--md-color:' + mdColor : ''}" onclick="_sbOpenVisitModal('${wo.id}')">
    <div class="sbm-job-top">
      ${_p6WOTrafficDot(wo.status)}
      <span class="sbm-job-num">${wo.wo_number||wo.id}</span>
      ${timeStr ? `<span class="sbm-job-time">${timeStr}${endStr}</span>` : ''}
      ${isMd ? `<span class="sb-card-md-pill">Day ${escapeHtml(wo.md_day_number||'?')}/${escapeHtml(wo.total_days||'?')}</span>` : ''}
      ${mdWarn ? `<span class="sb-card-md-warn">${escapeHtml(mdWarn)}</span>` : ''}
      <span class="sbm-job-status ops-ready-badge ${statusCls}">${_p6WOStatusLabel(wo.status)}</span>
    </div>
    ${isMd ? `<div class="sb-card-md-marker"><span style="background:${mdColor}"></span>${escapeHtml(phaseName)}</div>` : ''}
    <div class="sbm-job-client">${escapeHtml(wo.client_name||wo.title||'Job')}</div>
    <div class="sbm-job-meta">
      ${crew||wo.crew_name ? `<span style="color:${crewColor};font-weight:600;font-size:12px">${escapeHtml(wo.crew_name||crew?.name||'')}</span>` : ''}
      <span class="sbm-job-type">${escapeHtml(wo.type||'Service')}</span>
      ${wo.duration_hours ? `<span class="sbm-job-dur">${wo.duration_hours}h</span>` : ''}
    </div>
  </div>`;
}

window._sbToggleCrewLanes = function() {
  window._sbState.crewLanes = !window._sbState.crewLanes;
  _sbSavePreferences();
  _sbRender();
};


window._sbOpenDaySummary = function(iso) {
  const jobs = (window._sbState.workOrders || []).filter(w => w.scheduled_date && w.scheduled_date.slice(0,10) === iso);
  if (!jobs.length) { _sbOpenNewVisit(iso, null); return; }
  document.getElementById('sb-day-summary-modal')?.remove();
  const crews = window._sbState.crews || [];
  const dayLabel = new Date(iso + 'T12:00:00').toLocaleDateString('en-US', { weekday:'long', month:'long', day:'numeric', year:'numeric' });
  const mdWarnings = window._sbMdWarnings || _sbMdWarningMap(window._sbState.workOrders || []);
  const warnRows = jobs.filter(j => mdWarnings.get(j.id + ':' + j.md_day_number));
  const modal = document.createElement('div');
  modal.id = 'sb-day-summary-modal';
  modal.className = 'sb-modal-backdrop';
  modal.innerHTML = `
    <div class="sb-visit-modal" style="max-width:760px">
      <div class="sb-modal-header">
        <div><h2>${escapeHtml(dayLabel)}</h2><p>${jobs.length} scheduled visit${jobs.length === 1 ? '' : 's'}${warnRows.length ? ' - ' + warnRows.length + ' schedule warning' + (warnRows.length === 1 ? '' : 's') : ''}</p></div>
        <button class="sb-modal-close" onclick="document.getElementById('sb-day-summary-modal')?.remove()">×</button>
      </div>
      <div class="sb-modal-body" style="display:block;max-height:70vh;overflow:auto">
        ${warnRows.length ? `<div class="gw-md-warn"><strong>Warnings in this day</strong><br>${warnRows.map(w => escapeHtml((w.wo_number || w.id) + ': ' + mdWarnings.get(w.id + ':' + w.md_day_number))).join('<br>')}</div>` : ''}
        <div style="display:flex;flex-direction:column;gap:8px">
          ${jobs.map(wo => _sbJobCard(wo, crews, false)).join('')}
        </div>
      </div>
      <div class="sb-modal-actions">
        <button class="rp-btn" onclick="_sbOpenNewVisit('${iso}',null);document.getElementById('sb-day-summary-modal')?.remove()">Add Work Order</button>
        <button class="rp-btn rp-btn--primary" onclick="document.getElementById('sb-day-summary-modal')?.remove()">Close</button>
      </div>
    </div>`;
  modal.addEventListener('click', function(e) { if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
};

// ── Drag & Drop ───────────────────────────────────────────────────────────────
// Handle mousedown on drag handle — only starts a real HTML5 drag if the user
// actually moves the mouse (>4px), otherwise it's a click and falls through to
// the card's onclick handler normally.
window._sbDragStart = function(e, woId, dayNumber) {
  e.dataTransfer.setData('text/plain', woId);
  e.dataTransfer.setData('application/gw-day-number', String(dayNumber || 0));
  e.dataTransfer.effectAllowed = 'move';
  e.currentTarget.style.opacity = '0.45';
};

/**
 * "Move which dates?" — asked, not assumed.
 *
 * Returns 'day' | 'following' | 'job', or null when the user backs out. A drag
 * that moves four days when the user meant one is not recoverable by dragging
 * back: the other three have already lost their original dates.
 */
window._sbAskMoveScope = function(dayNumber, totalDays) {
  return new Promise(resolve => {
    document.getElementById('gw-move-scope')?.remove();
    const modal = document.createElement('div');
    modal.id = 'gw-move-scope';
    modal.className = 'sb-modal-overlay';
    const pick = (v) => { modal.remove(); resolve(v); };
    modal.innerHTML = `
      <div class="sb-modal-panel gw-scope-panel">
        <div class="sb-modal-header">
          <div class="sb-modal-title-block">
            <span class="sb-modal-wo-num">Move which dates?</span>
            <span class="jb-subtitle">Day ${dayNumber} of ${totalDays}</span>
          </div>
        </div>
        <div class="gw-scope-options">
          <button class="gw-scope-opt" data-v="day">
            <strong>This day only</strong>
            <small>The other days stay exactly where they are.</small>
          </button>
          <button class="gw-scope-opt" data-v="following">
            <strong>This day and the ones after it</strong>
            <small>Days ${dayNumber}\u2013${totalDays} shift by the same amount. Earlier days are untouched.</small>
          </button>
          <button class="gw-scope-opt" data-v="job">
            <strong>The entire job</strong>
            <small>All ${totalDays} days move together, keeping their spacing.</small>
          </button>
        </div>
        <div class="sb-modal-actions">
          <button class="rp-btn" data-v="">Cancel</button>
        </div>
      </div>`;
    modal.addEventListener('click', (ev) => {
      const btn = ev.target.closest('[data-v]');
      if (!btn) return;
      pick(btn.dataset.v || null);
    });
    document.body.appendChild(modal);
  });
};

window._sbDropOnCell = async function(e, iso, crewId) {
  e.preventDefault();
  document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));
  const woId = e.dataTransfer.getData('text/plain');
  const dragDayNumber = parseInt(e.dataTransfer.getData('application/gw-day-number') || '0') || 0;
  if (!woId) return;
  // Cards on the grid first, then the Job Pool. A pool job is not in
  // workOrders at all — it has no date, so the week query never returned it —
  // and the old lookup gave up with a bare `return`, which is why dragging a
  // backlog card onto a week or month cell silently did nothing at all.
  const wo = window._sbState.workOrders.find(w=>w.id===woId && (!dragDayNumber || Number(w.md_day_number) === dragDayNumber))
    || window._sbState.workOrders.find(w=>w.id===woId)
    || (window._sbState.pool || []).find(w=>w.id===woId);
  if (!wo) return;
  const fromPool = !window._sbState.workOrders.some(w=>w.id===woId);
  const oldDate = wo.scheduled_date;
  const oldCrew = wo.md_crew_id || wo.crew_id;
  const isMdDay = !!(wo.md_day_number || dragDayNumber);
  const dayNumber = Number(wo.md_day_number || dragDayNumber);
  const nextCrew = crewId && crewId !== '__unassigned__' ? crewId : (crewId === '__unassigned__' ? '' : oldCrew);
  // Moving one day of a multi-day job is ambiguous, so ask instead of guessing.
  //
  // This used to be an undocumented Shift-drag: hold Shift and the drag silently
  // became "move this phase and every day after it". Nothing in the UI said so,
  // which meant the destructive option was the invisible one. A four-day job
  // could shift by a week because someone happened to be holding a modifier.
  const isRealMultiDay = isMdDay && Number(wo.total_days || 0) > 1;
  let moveMode = 'day';
  if (isRealMultiDay && !fromPool) {
    moveMode = await _sbAskMoveScope(dayNumber, Number(wo.total_days || 0));
    if (!moveMode) return; // cancelled — put the card back where it was
  }
  const shiftMode = moveMode === 'following' || moveMode === 'job';
  wo.scheduled_date = iso;
  if (isMdDay) wo.md_crew_id = nextCrew || '';
  else if (crewId && crewId !== '__unassigned__') wo.crew_id = crewId;
  else if (crewId === '__unassigned__') wo.crew_id = null;
  _sbRender();
  try {
    if (shiftMode) {
      const fromDay = moveMode === 'job' ? 1 : dayNumber;
      const r = await fetch(`/api/work-orders/${woId}/days/${fromDay}/shift-downstream`, {
        method:'POST', credentials:'include', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ day_date: iso, crew_id: nextCrew || null })
      });
      const d = await r.json().catch(()=>({}));
      if (!r.ok || d.ok === false) throw new Error(d.error || 'Reschedule failed');
      showToast(moveMode === 'job' ? 'Whole job moved' : 'This day and the ones after it moved','success');
      await _sbRefresh();
      return;
    }
    // Every drop goes through the Job Day, whatever its day number.
    //
    // This used to fork on `isMdDay`, which is true whenever the card carries a
    // day number — and the primary day of an ordinary single-day job is day 1.
    // So almost every drag took the "multi-day" branch to PATCH /days/:n, which
    // updates wo_days but mirrors only scheduled_date back to the work order,
    // never crew_id. After dragging a job to another crew, one API response
    // carried both answers at once:
    //
    //     crew_id:   crew-blue      <- what the drawer's crew picker selects
    //     crew_name: "Green Crew"   <- resolved through the day row
    //
    // Capacity was right, because that reads wo_days. Open the job and it still
    // said Blue. That is the "the card moves but the crew doesn't follow it"
    // report, and it is a mirror gap rather than the two-request race.
    //
    // /api/scheduling/days/:id/schedule writes the day, mirrors the whole row —
    // crew included — onto the work order in the SAME batch when the day is
    // primary, re-derives the people when the crew changes, and returns the
    // recomputed capacity. One endpoint, one transaction, for every day.
    const dayId = wo.md_day_id;
    const nextCrewId = crewId === '__unassigned__' ? '' : (crewId === null ? undefined : crewId);
    let d;
    if (dayId) {
      const payload = { date: iso };
      if (nextCrewId !== undefined) payload.crew_id = nextCrewId;
      const r = await fetch(`/api/scheduling/days/${encodeURIComponent(dayId)}/schedule`, {
        method:'POST', credentials:'include', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload)
      });
      d = await r.json().catch(()=>({}));
      if (!r.ok || d.ok === false) throw new Error(d.error || 'Reschedule failed');
    } else {
      // No day row yet — a job coming off the backlog. This endpoint creates one
      // and then applies the same schedule, so the two cases converge.
      const r = await fetch(`/api/scheduling/work-orders/${encodeURIComponent(woId)}/schedule`, {
        method:'POST', credentials:'include', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ date: iso, crew_id: nextCrewId === undefined ? '' : nextCrewId })
      });
      d = await r.json().catch(()=>({}));
      if (!r.ok || d.ok === false) throw new Error(d.error || 'Reschedule failed');
      wo.md_day_id = d.day_id;
    }
    if (fromPool) {
      // The job was not on the grid a moment ago, so there is no card to patch
      // and no pool row that should still be there. Reload rather than trying to
      // move an object between two lists by hand.
      showToast('Scheduled','success');
      await _sbRefresh();
      return;
    }
    showToast('Job rescheduled','success');
    // Capacity came back with the write, for the lane it left as well as the one
    // it joined. No follow-up round trip to /week, and therefore no window in
    // which the grid and the number beside it can disagree.
    _sbApplyCapacity(d.capacity);
  } catch(err) {
    wo.scheduled_date = oldDate;
    if (isMdDay) wo.md_crew_id = oldCrew || '';
    else wo.crew_id = oldCrew;
    _sbRender();
    showToast((err && err.message) || 'Reschedule failed','error');
  }
};

window._sbDropOnTimeline = async function(e, track) {
  e.preventDefault();
  const woId = e.dataTransfer.getData('text/plain');
  const dayN = Number(e.dataTransfer.getData('application/gw-day-number') || 0);
  const wo = [...window._sbState.workOrders, ...(window._sbState.backlog || [])].find(w=>w.id===woId && (!dayN || Number(w.md_day_number)===dayN));
  if (!wo || wo.schedule_locked) return showToast('Unlock this visit before moving it','error');
  const sb = window._sbState, rect = track.getBoundingClientRect();
  const raw = Number(sb.workdayStart||6)*60 + ((e.clientY-rect.top)/1.15);
  const snap = Number(sb.snapMinutes)||15, start = Math.round(raw/snap)*snap;
  const range = _sbEventRange(wo), end = Math.min(1439,start+range.duration);
  const crew = track.dataset.crew === '__unassigned__' ? '' : track.dataset.crew;
  await _sbApplySchedule(wo, { day_date:track.dataset.date, scheduled_date:track.dataset.date, start_time:_sbClock(start), end_time:_sbClock(end), scheduled_time:_sbClock(start), scheduled_end_time:_sbClock(end), crew_id:crew, scheduled_duration_minutes:end-start }, 'Visit moved');
};
window._sbApplySchedule = async function(wo, changes, message) {
  const dayN = Number(wo.md_day_number||0), before = { scheduled_date:wo.scheduled_date, scheduled_time:wo.scheduled_time, scheduled_end_time:wo.scheduled_end_time, crew_id:wo.md_crew_id||wo.crew_id, scheduled_duration_minutes:wo.scheduled_duration_minutes };
  window._sbState.undoStack.push({ woId:wo.id, dayN, before });
  if (window._sbState.undoStack.length>20) window._sbState.undoStack.shift();
  try {
    const url = dayN ? `/api/work-orders/${wo.id}/days/${dayN}` : `/api/work-orders/${wo.id}/reschedule`;
    const body = dayN ? changes : { scheduled_date:changes.scheduled_date, scheduled_time:changes.scheduled_time, scheduled_end_time:changes.scheduled_end_time, scheduled_duration_minutes:changes.scheduled_duration_minutes };
    const r = await fetch(url,{method:'PATCH',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    const d=await r.json().catch(()=>({})); if(!r.ok||d.ok===false) throw new Error(d.error||'Schedule update failed');
    if (!dayN && changes.crew_id !== undefined && changes.crew_id !== before.crew_id) await fetch(`/api/work-orders/${wo.id}`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({crew_id:changes.crew_id||null})});
    showToast(`${message}. Undo is available in the timeline toolbar.`,'success'); await _sbRefresh();
  } catch(err) { window._sbState.undoStack.pop(); showToast(err.message||'Schedule update failed','error'); }
};
window._sbUndo = async function() {
  const item=window._sbState.undoStack.pop(); if(!item) return showToast('Nothing to undo','error');
  const wo=window._sbState.workOrders.find(w=>w.id===item.woId&&(!item.dayN||Number(w.md_day_number)===item.dayN));
  if(!wo) return;
  const b=item.before;
  await _sbApplySchedule(wo,{day_date:b.scheduled_date,scheduled_date:b.scheduled_date,start_time:b.scheduled_time,end_time:b.scheduled_end_time,scheduled_time:b.scheduled_time,scheduled_end_time:b.scheduled_end_time,crew_id:b.crew_id,scheduled_duration_minutes:b.scheduled_duration_minutes},'Schedule restored');
  window._sbState.undoStack.pop();
};
window._sbResizeStart = function(e, woId, dayN) {
  e.preventDefault();
  const wo=window._sbState.workOrders.find(w=>w.id===woId&&(!dayN||Number(w.md_day_number)===Number(dayN))); if(!wo)return;
  const startY=e.clientY, range=_sbEventRange(wo), el=e.currentTarget.closest('.sb-time-event'), startHeight=el.getBoundingClientRect().height;
  const move=ev=>{const snap=Number(window._sbState.snapMinutes)||15, delta=Math.round(((ev.clientY-startY)/1.15)/snap)*snap, mins=Math.max(snap,range.duration+delta);el.style.height=Math.max(32,mins*1.15)+'px';el.querySelector('.sb-time-event-time').textContent=`${_sbDisplayTime(_sbClock(range.start))} - ${_sbDisplayTime(_sbClock(range.start+mins))}`;};
  const up=async ev=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);const snap=Number(window._sbState.snapMinutes)||15, delta=Math.round(((ev.clientY-startY)/1.15)/snap)*snap, mins=Math.max(snap,range.duration+delta);if(Math.abs(el.getBoundingClientRect().height-startHeight)<2)return _sbRender();await _sbApplySchedule(wo,{day_date:wo.scheduled_date,scheduled_date:wo.scheduled_date,start_time:_sbClock(range.start),end_time:_sbClock(range.start+mins),scheduled_time:_sbClock(range.start),scheduled_end_time:_sbClock(range.start+mins),crew_id:wo.md_crew_id||wo.crew_id,scheduled_duration_minutes:mins},'End time updated');};
  window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});
};

// ── Duplicate Job ─────────────────────────────────────────────────────────────
window._sbDuplicateJob = async function(woId) {
  const wo = window._sbState.workOrders.find(w=>w.id===woId);
  if (!wo) return;
  // Default: next day
  let nextDate = null;
  if (wo.scheduled_date) {
    const d = new Date(wo.scheduled_date + 'T12:00:00');
    d.setDate(d.getDate() + 1);
    nextDate = gwDateISO(d);
  }
  const userDate = prompt('Duplicate to date (YYYY-MM-DD):', nextDate || '');
  if (!userDate) return;
  try {
    const r = await fetch(`/api/work-orders/${woId}/duplicate`, {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ scheduled_date: userDate })
    });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error);
    showToast(`Duplicated → ${d.wo_number}`,'success');
    await _sbRefresh();
  } catch(err) { showToast('Duplicate failed: '+err.message,'error'); }
};

// ── Visit / Work Order Modal ──────────────────────────────────────────────────
/**
 * "Day 2 of 4", with a way to get to days 1, 3 and 4.
 *
 * A multi-day job opens on whichever card you clicked and then dead-ends: the
 * drawer shows one day, and the only route to another was to close it, find the
 * right card on the grid, and click that. On a four-day job spanning two weeks
 * that means navigating the calendar to read your own job.
 *
 * Renders nothing for a single-day job, where there is no "of" to speak of.
 */
function _sbDayNavHtml(wo) {
  const total = Number(wo.total_days || 0);
  const n = Number(wo.md_day_number || 0);
  if (!(total > 1 && n > 0)) return '';
  const sib = (target) => (window._sbState.workOrders || [])
    .find(w => w.id === wo.id && Number(w.md_day_number) === target);
  const prev = sib(n - 1), next = sib(n + 1);
  const btn = (day, label, arrow) => day
    ? `<button class="sb-daynav-btn" title="${label}" aria-label="${label}" onclick="_sbOpenVisitModal('${wo.id}',${Number(day.md_day_number)})">${arrow}</button>`
    // Disabled rather than hidden, so the control does not move as you page
    // through the days.
    : `<button class="sb-daynav-btn" disabled aria-hidden="true">${arrow}</button>`;
  return `<span class="sb-daynav">
    ${btn(prev, 'Previous day', '\u2039')}
    <span class="sb-daynav-label">Day ${n} of ${total}</span>
    ${btn(next, 'Next day', '\u203a')}
  </span>`;
}

window._sbOpenVisitModal = async function(woId, dayNumber) {
  // Remove any stale modal first
  const _existing = document.getElementById('sb-visit-modal');
  if (_existing) _existing.remove();

  // Ensure crews + employees are loaded — the modal can be opened from views
  // (client detail, estimates, My Day) before the schedule board has run.
  if (!(window._gwAllReps||[]).length || !(window._sbState?.crews||[]).length) {
    try {
      const [cr, rr] = await Promise.all([
        fetch('/api/crews', {credentials:'include'}).then(r=>r.json()).catch(()=>null),
        fetch('/api/reps',  {credentials:'include'}).then(r=>r.json()).catch(()=>null),
      ]);
      window._sbState = window._sbState || {};
      if (cr && cr.ok && !(window._sbState.crews||[]).length) window._sbState.crews = cr.data || [];
      if (rr && rr.ok && !(window._gwAllReps||[]).length) window._gwAllReps = rr.data || rr.reps || [];
    } catch(e) {}
  }

  let wo = null;
  try {
    const r = await fetch(`/api/work-orders/${woId}`, { credentials: 'include' });
    if (r.ok) {
      const d = await r.json();
      if (d.ok) wo = d.data;
    }
  } catch(e) { console.warn('[_sbOpenVisitModal] fetch error:', e); }
  // Fallback to localStorage
  if (!wo) wo = (state.workOrders||[]).find(w=>w.id===woId);

  // Opening a SPECIFIC day of a multi-day job.
  //
  // GET /api/work-orders/:id joins the day whose date matches the work order's
  // own scheduled_date, which is day 1 — so without this, paging to day 3 would
  // fetch the job and render day 1 again. The board already holds one row per
  // day (expand=days), so the day-level fields come from there.
  if (wo && dayNumber) {
    const dayRow = (window._sbState?.workOrders || [])
      .find(w => w.id === woId && Number(w.md_day_number) === Number(dayNumber));
    if (dayRow) {
      wo = { ...wo,
        md_day_id: dayRow.md_day_id, md_day_number: dayRow.md_day_number, md_day_date: dayRow.md_day_date,
        md_scope: dayRow.md_scope, md_phase_name: dayRow.md_phase_name, md_crew_id: dayRow.md_crew_id,
        md_status: dayRow.md_status, scheduled_date: dayRow.scheduled_date,
        scheduled_time: dayRow.scheduled_time, scheduled_end_time: dayRow.scheduled_end_time,
        schedule_locked: dayRow.schedule_locked,
      };
    }
  }
  if (!wo) {
    // Also check _sbState.workOrders
    wo = (window._sbState?.workOrders||[]).find(w=>w.id===woId);
  }
  if (!wo) { showToast('Work order not found','error'); return; }

  // Normalize JSON columns that may arrive as strings from localStorage fallback
  if (typeof wo.checklist  === 'string') try { wo.checklist  = JSON.parse(wo.checklist);  } catch(e) { wo.checklist  = []; }
  if (typeof wo.materials  === 'string') try { wo.materials  = JSON.parse(wo.materials);  } catch(e) { wo.materials  = []; }
  if (typeof wo.timeline   === 'string') try { wo.timeline   = JSON.parse(wo.timeline);   } catch(e) { wo.timeline   = []; }
  if (typeof wo.before_photos==='string')try{wo.before_photos=JSON.parse(wo.before_photos);}catch(e){wo.before_photos=[];}
  if (typeof wo.after_photos==='string') try{wo.after_photos =JSON.parse(wo.after_photos); }catch(e){wo.after_photos =[];}
  if (typeof wo.attachments==='string')  try{wo.attachments  =JSON.parse(wo.attachments);  }catch(e){wo.attachments  =[];}
  if (typeof wo.equipment  === 'string') try { wo.equipment  = JSON.parse(wo.equipment);  } catch(e) { wo.equipment  = []; }
  if (!Array.isArray(wo.checklist))   wo.checklist   = [];
  if (!Array.isArray(wo.materials))   wo.materials   = [];
  if (!Array.isArray(wo.equipment))   wo.equipment   = [];
  if (!Array.isArray(wo.before_photos))wo.before_photos=[];
  if (!Array.isArray(wo.after_photos)) wo.after_photos =[];
  if (!Array.isArray(wo.attachments))  wo.attachments  =[];
  if (!Array.isArray(wo.employees))    wo.employees    =[];

  const crews   = window._sbState.crews || [];
  const allReps = window._gwAllReps || [];

  const crewOptions = crews.map(c=>`<option value="${c.id}"${wo.crew_id===c.id?' selected':''}>${escapeHtml(c.name)}</option>`).join('');
  const assignedEmpIds = new Set((wo.employees||[]).map(e=>e.rep_id||e));
  const empChips = (wo.employees||[]).map(e=>`
    <span class="sb-emp-chip" data-rep-id="${e.rep_id||e}">
      <span class="sb-emp-dot" style="background:${allReps.find(r=>r.id===(e.rep_id||e))?.color||'#6366f1'}"></span>
      ${escapeHtml(e.name||e.rep_id||e)}
      <button onclick="_sbRemoveEmployee('${e.rep_id||e}')" title="Remove">×</button>
    </span>`).join('');

  const checklistHtml = (wo.checklist||[]).map((item,i)=>`
    <div class="sb-check-item">
      <button class="sb-check-box${item.done?' done':''}" onclick="_sbToggleCheck(${i})">
        ${item.done?'<svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M2 6l3 3 5-5"/></svg>':''}
      </button>
      <span class="sb-check-label${item.done?' done':''}">${escapeHtml(item.text||'')}</span>
      <button class="sb-check-del" onclick="_sbRemoveCheck(${i})">×</button>
    </div>`).join('');

  const beforePhotos = (wo.before_photos||[]);
  const afterPhotos  = (wo.after_photos||[]);

  const photosHtml = (label, photos, field) => `
    <div class="sb-photo-group">
      <div class="sb-photo-label">${label}</div>
      <div class="sb-photo-row" id="sb-photos-${field}">
        ${photos.map((url,pi)=>`<div class="sb-photo-thumb" data-pi="${pi}" data-field="${field}"><img src="${escapeHtml(url)}" alt="photo"><button onclick="_sbRemovePhoto(this.closest('.sb-photo-thumb').dataset.field,this.closest('.sb-photo-thumb').dataset.pi)">×</button></div>`).join('')}
        <label class="sb-photo-add" title="Add photo">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>
          <input type="file" accept="image/*" style="display:none" onchange="_sbUploadPhoto(event,'${field}')">
        </label>
      </div>
    </div>`;

  // Work tracking
  // Calendar duration, not budgeted labor — work_orders.duration_hours drives
  // how long the job blocks the grid. What was sold lives in budget_minutes and
  // is surfaced by the Hours card.
  const budgetedHrs = wo.duration_hours || 0;

  const modal = document.createElement('div');
  modal.id = 'sb-visit-modal';
  modal.className = 'sb-modal-overlay';
  try { modal.innerHTML = `
    <div class="sb-modal-panel">
      <div class="sb-modal-header">
        <div class="sb-modal-title-block">
          <span class="sb-modal-wo-num">${wo.wo_number||wo.id}</span>
          <span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}" id="sb-status-badge">${_p6WOStatusLabel(wo.status)}</span>
          ${_sbDayNavHtml(wo)}
        </div>
        <div class="sb-modal-header-meta">
          <span>${wo.scheduled_date ? _p5FmtDate(wo.scheduled_date) : 'No date'}</span>
          ${wo.scheduled_time ? `<span> · ${wo.scheduled_time}</span>` : ''}
        </div>
        <button class="sb-modal-close" onclick="_sbCloseModal()">×</button>
      </div>

      <div class="sb-modal-body">
        <!-- Left Col -->
        <div class="sb-modal-left">
          <!-- Visit Info -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Visit Details</h3>
            <div class="sb-modal-date-row">
              <label class="sb-modal-field">
                <span>Date</span>
                <input class="rp-input" id="sbm-date" type="date" value="${wo.scheduled_date||''}">
              </label>
              <label class="sb-modal-field">
                <span>Time</span>
                <input class="rp-input" id="sbm-time" type="time" value="${wo.scheduled_time||''}">
              </label>
              <label class="sb-modal-field">
                <span>Status</span>
                <select class="rp-input" id="sbm-status">
                  ${['hold','scheduled','in-progress','completed','on-hold','cancelled'].map(s=>
                    `<option value="${s}"${wo.status===s?' selected':''}>${_p6WOStatusLabel(s)}</option>`).join('')}
                </select>
              </label>
              <label class="sb-modal-field">
                <span>Schedule Lock</span>
                <label style="display:flex;align-items:center;gap:7px;height:38px"><input id="sbm-schedule-locked" type="checkbox"${wo.schedule_locked ? ' checked' : ''}> Prevent drag and resize</label>
              </label>
            </div>

            <div class="sb-modal-field" style="margin-top:8px">
              <span>Visit Notes (visible to crew)</span>
              <textarea class="rp-input" id="sbm-notes" rows="3" placeholder="Scope, special instructions…">${escapeHtml(wo.notes||'')}</textarea>
            </div>
          </section>

          <!-- Hours: sold vs planned vs actual. Filled in by _sbLoadHours()
               after the modal paints, so opening a job never waits on it. -->
          <section class="sb-modal-section" id="sbm-hours-section">
            <h3 class="sb-modal-section-title">Hours</h3>
            <div id="sbm-hours" class="sb-hours-grid"><span class="muted" style="font-size:12px">Loading…</span></div>
          </section>

          <!-- Completion Details -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Completion Details</h3>
            <div class="sb-line-items" id="sbm-line-items">
              ${(wo.materials||[]).length ? wo.materials.map((m,i)=>`
                <div class="sb-line-row">
                  <input class="rp-input" value="${escapeHtml(m.name||'')}" placeholder="Item / Service" style="flex:2">
                  <input class="rp-input" value="${m.qty||1}" type="number" min="0" style="width:60px" placeholder="Qty">
                  <input class="rp-input" value="${m.unit||''}" placeholder="Unit" style="width:70px">
                  <input class="rp-input" value="${m.cost||0}" type="number" min="0" placeholder="Rate" style="width:80px">
                  <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbRemoveLine(${i})">×</button>
                </div>`).join('') : ''}
            </div>
            <div style="display:flex;gap:8px;margin-top:8px">
              <button class="rp-btn-sm" onclick="_sbAddLine()">+ Add Line</button>
              <button class="rp-btn-sm" onclick="_sbAddPackage()">Add Package</button>
            </div>
            <div class="sb-total-row">
              <span>Total</span>
              <span id="sbm-total">$${((wo.amount_est||0)).toFixed(2)}</span>
            </div>
            <div class="sb-modal-field" style="margin-top:8px">
              <span>Completion Notes</span>
              <textarea class="rp-input" id="sbm-completion-notes" rows="2" placeholder="What was done, any issues…">${escapeHtml(wo.completion_notes||'')}</textarea>
            </div>
          </section>

          <!-- Checklist -->
          <section class="sb-modal-section">
            <div class="sb-modal-section-head">
              <h3 class="sb-modal-section-title">Checklist</h3>
              <button class="rp-btn-sm" onclick="_sbAddCheck()">+ Item</button>
            </div>
            <div id="sbm-checklist">${checklistHtml||'<p class="sb-empty-note">No items. Add checklist items above.</p>'}</div>
          </section>

          <!-- Multi-Day Job -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Multi-Day Job</h3>
            <div id="gw-wo-multiday-panel"><p class="sb-empty-note">Loading…</p></div>
          </section>

          <!-- Client Portal Updates -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Client Portal Updates</h3>
            <div id="gw-wo-portal-panel"><p class="sb-empty-note">Loading updates…</p></div>
          </section>
        </div>

        <!-- Right Col -->
        <div class="sb-modal-right">
          <!-- Crew Assignment -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75"/></svg>
              Crew
            </h3>
            <label class="sb-modal-field">
              <span>Assigned Crew</span>
              <select class="rp-input" id="sbm-crew" onchange="_sbCrewChanged()">
                <option value="">— Unassigned —</option>
                ${crewOptions}
              </select>
            </label>
            <div class="sb-modal-field" style="margin-top:8px">
              <span>Employees on this visit</span>
              <div class="sb-emp-chips" id="sbm-emp-chips">${empChips||'<span class="sb-empty-note">None assigned.</span>'}</div>
              <div class="sb-emp-add-row">
                <select class="rp-input" id="sbm-add-emp-select" style="flex:1">
                  <option value="">+ Add employee…</option>
                  ${allReps.filter(r=>r.active!==false&&r.active!==0).map(r=>
                    `<option value="${r.id}"${assignedEmpIds.has(r.id)?' disabled':''}>
                      ${escapeHtml(r.name)} (${r.role||'rep'})
                    </option>`).join('')}
                </select>
                <button class="rp-btn-sm" onclick="_sbAddEmployee()">Add</button>
              </div>
            </div>
          </section>

          <!-- Materials & Equipment (crew-visible) -->
          <section class="sb-modal-section">
            <div class="sb-modal-section-head">
              <h3 class="sb-modal-section-title">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 7H4a2 2 0 00-2 2v10a2 2 0 002 2h16a2 2 0 002-2V9a2 2 0 00-2-2z"/><path d="M16 21V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v16"/></svg>
                Materials &amp; Equipment
              </h3>
              <button class="rp-btn-sm" onclick="_sbAddCrewItem()">+ Item</button>
            </div>
            <div id="sbm-equip-list" style="display:flex;flex-direction:column;gap:6px;margin-bottom:8px">
              ${(wo.equipment||[]).length ? wo.equipment.map((eq,i)=>`
                <div class="sb-equip-row" data-idx="${i}" style="display:flex;align-items:center;gap:6px;padding:6px 8px;background:var(--gw-surface-3);border-radius:6px">
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/></svg>
                  <span style="flex:1;font-size:13px">${escapeHtml(typeof eq==='string'?eq:eq.name||'')}</span>
                  <button class="sb-check-del" onclick="_sbRemoveEquipItem(${i})">×</button>
                </div>`).join('') : '<p class="sb-empty-note">No equipment assigned.</p>'}
            </div>
            <div style="display:flex;gap:6px">
              <input class="rp-input" id="sbm-equip-input" placeholder="Truck, skid steer, mower…" style="flex:1">
              <button class="rp-btn-sm" onclick="_sbAddCrewItem()">Add</button>
            </div>
          </section>

          <!-- Photos -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Before &amp; After Photos</h3>
            ${photosHtml('Before', beforePhotos, 'before_photos')}
            ${photosHtml('After',  afterPhotos,  'after_photos')}
          </section>

          <!-- Time on the calendar.
               This section used to be "Work Tracking" and showed a Budgeted and
               an Actual stat. Both were misleading:

                 "Budgeted" read work_orders.duration_hours, which is ALSO what
                 the grid uses to decide how long a job blocks — so the field
                 labelled "total man-hrs" silently resized the job on the board.
                 It is calendar time, and is now labelled as such.

                 "Actual" read work_orders.actual_hours, a denormalised column
                 nothing keeps current — it showed 0h on jobs with real logged
                 time. The Hours card above computes actual from time_entries,
                 net of breaks, so a second contradictory figure is worse than
                 none. Removed rather than left to disagree. -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Time on the calendar</h3>
            <p class="sb-modal-hint">How long this blocks the schedule. Sold, planned and actual hours are in the Hours card above.</p>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
              <label class="sb-modal-field">
                <span>Duration <em style="font-size:10px;font-weight:400;opacity:.6">(hours on the grid)</em></span>
                <input class="rp-input" id="sbm-duration" type="number" min="0" step="0.5" value="${budgetedHrs||''}">
              </label>
              <label class="sb-modal-field">
                <span>Scheduled End</span>
                <input class="rp-input" id="sbm-end-time" type="time" value="${wo.scheduled_end_time||''}">
              </label>
            </div>
          </section>

          <!-- Customer / Property -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Customer</h3>
            ${wo.client_id || wo.client_name ? `
              <div>
                <button class="sb-client-link" data-cid="${escapeHtml(wo.client_id||'')}" data-cname="${escapeHtml(wo.client_name||'').replace(/"/g,'&quot;')}" onclick="_sbGoToCustomer(this.dataset.cid,this.dataset.cname);_sbCloseModal()" title="Open customer details">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                  <strong>${escapeHtml(wo.client_name||'—')}</strong>
                </button>
              </div>` : `<div><strong>—</strong></div>`}
            ${wo.property_addr ? `
              <div style="margin-top:6px">
                <a class="sb-addr-link" href="https://maps.google.com/?q=${encodeURIComponent(wo.property_addr)}" target="_blank" rel="noopener" title="Open in Google Maps">
                  <svg width="11" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg>
                  ${escapeHtml(wo.property_addr)}
                </a>
              </div>` : ''}
            ${wo.amount_est ? `<div style="font-size:12px;margin-top:6px">Estimate: <strong>$${Number(wo.amount_est).toFixed(2)}</strong></div>` : ''}
          </section>

          <!-- Attachments (photos + PDFs) -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Attachments</h3>
            <div id="sbm-attachments-list" style="display:flex;flex-direction:column;gap:6px;margin-bottom:10px">
              ${(wo.attachments||[]).map((a,i)=>`
                <div class="sb-attach-row" data-idx="${i}">
                  <span class="sb-attach-icon">${a.type==='pdf'?gwIcon('document',14):gwIcon('image',14)}</span>
                  <span class="sb-attach-name" style="flex:1;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(a.name||'File')}</span>
                  <a href="${escapeHtml(a.url||'#')}" target="_blank" class="rp-btn-sm" style="padding:2px 8px;font-size:11px">View</a>
                  <button class="sb-check-del" onclick="_sbRemoveAttachment(${i})">×</button>
                </div>`).join('') || '<p class="sb-empty-note">No attachments yet.</p>'}
            </div>
            <label class="sb-attach-upload-btn">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
              Upload Photo or PDF
              <input type="file" accept="image/*,.pdf" multiple style="display:none" onchange="_sbUploadAttachment(event)">
            </label>
          </section>
        </div>
      </div>

      <!-- Action Bar -->
      <div class="sb-modal-actions">
        <div class="sb-modal-actions-left">
          <button class="sb-action-btn" style="gap:5px" onclick="_sbDuplicateJob('${wo.id}')">
            <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="5" width="9" height="9" rx="1.5"/><path d="M3 11V3a1 1 0 011-1h8"/></svg>
            Duplicate
          </button>
          <button class="sb-action-btn sb-action-wo" onclick="show('workOrderDetail','${wo.id}');_sbCloseModal()">
            Work Order
          </button>
          ${wo.opp_id ? `<button class="sb-action-btn sb-action-upsell" onclick="_sbUpsell('${wo.opp_id}')">Up-sell</button>` : ''}
        </div>
        <div class="sb-modal-actions-right">
          <!-- Delete Job used to sit here, immediately beside Save, with only a
               flex gap between "keep my edits" and "destroy the job and every
               day, photo and time entry hanging off it". It now lives behind
               the overflow below, and this drawer offers the two reversible
               things a scheduler actually wants instead: take the day off the
               calendar, or call the day off. -->
          <div class="sb-overflow">
            <button class="sb-action-btn" aria-haspopup="menu" aria-expanded="false" onclick="_sbToggleOverflow(this)" title="More actions">···</button>
            <div class="sb-overflow-menu" hidden>
              <button onclick="_sbUnscheduleDay('${wo.id}')">Unschedule day<small>Back to the Job Pool. Keeps the crew.</small></button>
              <button onclick="_sbSkipVisit('${wo.id}')">Cancel day<small>Marks it cancelled. The job stays.</small></button>
              <button class="sb-overflow-danger" onclick="_sbDeleteVisit('${wo.id}')">Delete job<small>Permanent. Takes its days, photos and time entries.</small></button>
            </div>
          </div>
          <button class="rp-btn" onclick="_sbSaveVisit('${wo.id}',false)">Save changes</button>
          <button class="rp-btn rp-btn--primary" id="sb-complete-btn" onclick="_sbCompleteVisit('${wo.id}','${wo.type||'Service'}')">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>
            Mark day complete
          </button>
        </div>
      </div>
    </div>`; } catch(renderErr) {
    console.error('[_sbOpenVisitModal] render error:', renderErr, wo);
    showToast('Error opening job — see console for details','error');
    return;
  }

  // Close on backdrop click
  modal.addEventListener('click', function(e) { if (e.target === modal) _sbCloseModal(); });

  document.body.appendChild(modal);

  // Store current WO for handlers
  window._sbCurrentWO = JSON.parse(JSON.stringify(wo));
  window._sbCurrentWOId = wo.id;

  // Fill the Hours card after the modal is on screen — opening a job must not
  // wait on this request.
  _sbLoadHours(wo.id);

  // Mount Client Portal Updates panel (daily updates + photo publish)
  if (typeof window._gwPortalUpdatesPanel === 'function') {
    window._gwPortalUpdatesPanel(wo.id, document.getElementById('gw-wo-portal-panel'));
  } else {
    const _pp = document.getElementById('gw-wo-portal-panel');
    if (_pp) _pp.innerHTML = '<p class="sb-empty-note">Portal module not loaded.</p>';
  }

  // Mount Multi-Day Job panel (daily AI checklist + auto-publish)
  if (typeof window._gwMultidayPanel === 'function') {
    window._gwMultidayPanel(wo.id, document.getElementById('gw-wo-multiday-panel'));
  } else {
    const _mp = document.getElementById('gw-wo-multiday-panel');
    if (_mp) _mp.innerHTML = '<p class="sb-empty-note">Multi-day module not loaded.</p>';
  }
};

window._sbCloseModal = function() {
  const m = document.getElementById('sb-visit-modal');
  if (m) m.remove();
  window._sbCurrentWO = null;
};

window._sbSaveVisit = async function(woId, andComplete) {
  // Collect equipment list
  const equipItems = [...document.querySelectorAll('#sbm-equip-list .sb-equip-row')].map(row => {
    return row.querySelector('span')?.textContent?.trim() || '';
  }).filter(Boolean);
  // Collect materials line items — the DOM is the source of truth (see
  // _sbAddLine/_sbAddPackage, which don't keep wo.materials perfectly in
  // sync after removals), same pattern as equipment above.
  const materialItems = [...document.querySelectorAll('#sbm-line-items .sb-line-row')].map(row => {
    const inputs = row.querySelectorAll('input');
    return {
      name: inputs[0]?.value.trim() || '',
      qty:  parseFloat(inputs[1]?.value) || 0,
      unit: inputs[2]?.value.trim() || '',
      cost: parseFloat(inputs[3]?.value) || 0,
    };
  }).filter(m => m.name);
  const wo = window._sbCurrentWO || {};
  const body = {
    scheduled_date: document.getElementById('sbm-date')?.value || null,
    scheduled_time: document.getElementById('sbm-time')?.value || null,
    scheduled_end_time: document.getElementById('sbm-end-time')?.value || null,
    schedule_locked: !!document.getElementById('sbm-schedule-locked')?.checked,
    status:         document.getElementById('sbm-status')?.value || 'scheduled',
    notes:          document.getElementById('sbm-notes')?.value  || '',
    completion_notes: document.getElementById('sbm-completion-notes')?.value || '',
    crew_id:        document.getElementById('sbm-crew')?.value   || null,
    duration_hours: parseFloat(document.getElementById('sbm-duration')?.value||'0') || null,
    equipment:      equipItems,
    materials:      materialItems,
    checklist:      wo.checklist || [],
    employee_ids:   [...document.querySelectorAll('#sbm-emp-chips .sb-emp-chip')].map(el=>el.dataset.repId).filter(Boolean),
    before_photos:  wo.before_photos || [],
    after_photos:   wo.after_photos  || [],
    attachments:    wo.attachments   || [],
  };
  if (andComplete) body.status = 'completed';
  try {
    const r = await fetch(`/api/work-orders/${woId}`, {
      method:'PUT', credentials:'include', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)
    });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error);
    showToast(andComplete ? 'Visit completed! Invoice flow next.' : 'Visit saved', 'success');
    _sbCloseModal();
    await _sbRefresh();
    if (andComplete) {
      // Could trigger invoice creation flow here
      setTimeout(()=>showToast('Ready to invoice — use Work Orders > Create Invoice','info'),1500);
    }
  } catch(e) {
    showToast('Save failed: '+e.message,'error');
  }
};

window._sbToggleOverflow = function(btn) {
  const menu = btn.parentElement.querySelector('.sb-overflow-menu');
  const open = menu.hidden;
  document.querySelectorAll('.sb-overflow-menu').forEach(m => { m.hidden = true; });
  menu.hidden = !open;
  btn.setAttribute('aria-expanded', String(open));
  if (open) {
    // One-shot outside-click close. Registered on the next frame so the click
    // that opened the menu does not immediately close it again.
    setTimeout(() => document.addEventListener('click', function away(ev) {
      if (menu.parentElement.contains(ev.target)) return;
      menu.hidden = true; btn.setAttribute('aria-expanded', 'false');
      document.removeEventListener('click', away);
    }), 0);
  }
};

/**
 * Take this day off the calendar, keeping the job and its crew.
 *
 * The reversible counterpart to Delete. DELETE /days/:id/schedule clears the
 * date and keeps the day row and its people, so the job returns to the Job Pool
 * with its staffing intact and re-scheduling does not start from an empty crew.
 */
window._sbUnscheduleDay = async function(woId) {
  const wo = (window._sbState.workOrders || []).find(w => w.id === woId);
  const dayId = wo?.md_day_id;
  if (!dayId) return showToast('This job is not on the calendar', 'error');
  if (wo.schedule_locked) return showToast('Unlock this visit before unscheduling it', 'error');
  try {
    const r = await fetch(`/api/scheduling/days/${encodeURIComponent(dayId)}/schedule`, { method: 'DELETE', credentials: 'include' });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || d.ok === false) throw new Error(d.error || 'Could not unschedule');
    showToast('Moved to the Job Pool', 'success');
    _sbCloseModal();
    await _sbRefresh();
  } catch (e) {
    showToast((e && e.message) || 'Could not unschedule', 'error');
  }
};

window._sbDeleteVisit = async function(woId) {
  if (!confirm('Delete this work order? This cannot be undone.')) return;
  try {
    await fetch(`/api/work-orders/${woId}`,{method:'DELETE', credentials:'include'});
    showToast('Work order deleted','success');
    _sbCloseModal();
    await _sbRefresh();
  } catch(e) { showToast('Delete failed','error'); }
};

window._sbSkipVisit = function(woId) {
  // Prompt for skip reason via inline modal
  const existing = document.getElementById('sb-skip-reason-modal');
  if (existing) existing.remove();
  const dlg = document.createElement('div');
  dlg.id = 'sb-skip-reason-modal';
  dlg.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:center;justify-content:center';
  dlg.innerHTML = `
    <div style="background:var(--gw-surface-1,#fff);border-radius:12px;padding:28px;width:min(420px,90vw);box-shadow:0 8px 40px rgba(0,0,0,.25)">
      <h3 style="margin:0 0 6px;font-size:16px;font-weight:700">Skip this visit?</h3>
      <p style="font-size:13px;color:var(--gw-text-muted);margin-bottom:16px">Please enter a reason for skipping (required).</p>
      <textarea id="sb-skip-reason-input" class="rp-input" rows="3" placeholder="e.g. Customer requested reschedule, weather, gate locked…" style="width:100%;resize:vertical"></textarea>
      <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:16px">
        <button class="rp-btn" onclick="document.getElementById('sb-skip-reason-modal').remove()">Cancel</button>
        <button class="rp-btn" style="background:#f97316;color:#fff;border-color:#f97316" onclick="_sbConfirmSkip('${woId}')">Skip Visit</button>
      </div>
    </div>`;
  document.body.appendChild(dlg);
};

window._sbConfirmSkip = async function(woId) {
  const reason = document.getElementById('sb-skip-reason-input')?.value?.trim();
  if (!reason) { showToast('Please enter a skip reason','error'); return; }
  document.getElementById('sb-skip-reason-modal')?.remove();
  try {
    await fetch(`/api/work-orders/${woId}`,{
      method:'PUT',credentials:'include',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({status:'cancelled', completion_notes: 'SKIPPED: ' + reason})
    });
    showToast('Visit skipped','success');
    _sbCloseModal();
    await _sbRefresh();
  } catch(e) { showToast('Failed to skip visit','error'); }
};

window._sbCompleteVisit = async function(woId, woType) {
  // For non-recurring single-service jobs, require after photos
  const isRecurring = (woType||'').toLowerCase().includes('recurring') || (woType||'').toLowerCase().includes('maintenance');
  const afterPhotos = window._sbCurrentWO?.after_photos || [];
  if (!isRecurring && afterPhotos.length === 0) {
    showToast('Please add at least one after photo before marking complete','error');
    // Scroll to photos section
    const photoSection = document.querySelector('#sb-photos-after_photos');
    if (photoSection) photoSection.scrollIntoView({behavior:'smooth',block:'center'});
    // Highlight the section
    const section = photoSection?.closest('.sb-modal-section');
    if (section) {
      section.style.outline = '2px solid var(--gw-danger,#dc2626)';
      section.style.borderRadius = '8px';
      setTimeout(()=>{ section.style.outline=''; }, 2500);
    }
    return;
  }
  await _sbSaveVisit(woId, true);
};

window._sbCrewChanged = function() {
  const crewId = document.getElementById('sbm-crew')?.value;
  const crews = window._sbState.crews||[];
  const crew = crews.find(c=>c.id===crewId);
  if (!crew?.members?.length) return;
  // Auto-suggest crew members
  const chipsEl = document.getElementById('sbm-emp-chips');
  const selectEl = document.getElementById('sbm-add-emp-select');
  crew.members.forEach(m=>{
    const existing = chipsEl?.querySelector(`[data-rep-id="${m.repId}"]`);
    if (!existing) {
      const allReps = window._gwAllReps||[];
      const rep = allReps.find(r=>r.id===m.repId)||{id:m.repId,name:m.name||m.repId};
      const chip = document.createElement('span');
      chip.className='sb-emp-chip'; chip.dataset.repId=m.repId;
      chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>
        ${escapeHtml(rep.name||m.repId)}
        <button onclick="_sbRemoveEmployee('${m.repId}')">×</button>`;
      const placeholder = chipsEl?.querySelector('.sb-empty-note');
      if (placeholder) placeholder.remove();
      chipsEl?.appendChild(chip);
    }
  });
};

window._sbAddEmployee = function() {
  const sel = document.getElementById('sbm-add-emp-select');
  if (!sel || !sel.value) return;
  const repId = sel.value;
  const allReps = window._gwAllReps||[];
  const rep = allReps.find(r=>r.id===repId)||{id:repId,name:repId};
  const chipsEl = document.getElementById('sbm-emp-chips');
  const existing = chipsEl?.querySelector(`[data-rep-id="${repId}"]`);
  if (existing) { showToast('Already added','info'); return; }
  const placeholder = chipsEl?.querySelector('.sb-empty-note');
  if (placeholder) placeholder.remove();
  const chip = document.createElement('span');
  chip.className='sb-emp-chip'; chip.dataset.repId=repId;
  chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>
    ${escapeHtml(rep.name||repId)}
    <button onclick="_sbRemoveEmployee('${repId}')">×</button>`;
  chipsEl?.appendChild(chip);
  // Disable in select
  const opt = sel.querySelector(`option[value="${repId}"]`);
  if (opt) opt.disabled=true;
  sel.value='';
};

window._sbRemoveEmployee = function(repId) {
  const chip = document.querySelector(`#sbm-emp-chips [data-rep-id="${repId}"]`);
  if (chip) chip.remove();
  const opt = document.querySelector(`#sbm-add-emp-select option[value="${repId}"]`);
  if (opt) opt.disabled=false;
};

// Equipment item helpers for the edit modal
window._sbAddCrewItem = function() {
  const inp = document.getElementById('sbm-equip-input');
  if (!inp?.value?.trim()) return;
  const val = inp.value.trim();
  const list = document.getElementById('sbm-equip-list');
  const empty = list?.querySelector('.sb-empty-note');
  if (empty) empty.remove();
  const idx = list?.querySelectorAll('.sb-equip-row').length || 0;
  const row = document.createElement('div');
  row.className = 'sb-equip-row';
  row.dataset.idx = idx;
  row.style.cssText = 'display:flex;align-items:center;gap:6px;padding:6px 8px;background:var(--gw-surface-3);border-radius:6px';
  row.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/></svg>
    <span style="flex:1;font-size:13px">${escapeHtml(val)}</span>
    <button class="sb-check-del" onclick="this.closest('.sb-equip-row').remove()">×</button>`;
  list?.appendChild(row);
  inp.value = '';
};
window._sbRemoveEquipItem = function(idx) {
  const rows = document.querySelectorAll('#sbm-equip-list .sb-equip-row');
  if (rows[idx]) rows[idx].remove();
};

window._sbToggleCheck = function(idx) {
  const wo = window._sbCurrentWO;
  if (!wo) return;
  if (wo.checklist[idx]) wo.checklist[idx].done = !wo.checklist[idx].done;
  const box = document.querySelectorAll('#sbm-checklist .sb-check-box')[idx];
  const lbl = document.querySelectorAll('#sbm-checklist .sb-check-label')[idx];
  if (box) { box.classList.toggle('done',wo.checklist[idx].done); box.innerHTML=wo.checklist[idx].done?'<svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M2 6l3 3 5-5"/></svg>':''; }
  if (lbl) lbl.classList.toggle('done',wo.checklist[idx].done);
};
window._sbRemoveCheck = function(idx) {
  const wo = window._sbCurrentWO; if (!wo) return;
  wo.checklist.splice(idx,1);
  const el = document.querySelectorAll('#sbm-checklist .sb-check-item')[idx];
  if (el) el.remove();
};
window._sbAddCheck = function() {
  const text = prompt('Checklist item:'); if (!text) return;
  const wo = window._sbCurrentWO; if (!wo) return;
  wo.checklist.push({text,done:false});
  const container = document.getElementById('sbm-checklist');
  const placeholder = container?.querySelector('.sb-empty-note');
  if (placeholder) placeholder.remove();
  const idx = wo.checklist.length-1;
  const div=document.createElement('div'); div.className='sb-check-item';
  div.innerHTML=`<button class="sb-check-box" onclick="_sbToggleCheck(${idx})"></button>
    <span class="sb-check-label">${escapeHtml(text)}</span>
    <button class="sb-check-del" onclick="_sbRemoveCheck(${idx})">×</button>`;
  container?.appendChild(div);
};

window._sbAddLine = function() {
  const container = document.getElementById('sbm-line-items');
  if (!container) return;
  const wo = window._sbCurrentWO;
  if (!wo.materials) wo.materials=[];
  const idx = wo.materials.length;
  wo.materials.push({name:'',qty:1,unit:'ea',cost:0});
  const div=document.createElement('div'); div.className='sb-line-row';
  div.innerHTML=`<input class="rp-input" placeholder="Item / Service" style="flex:2">
    <input class="rp-input" value="1" type="number" min="0" style="width:60px" placeholder="Qty">
    <input class="rp-input" placeholder="Unit" style="width:70px">
    <input class="rp-input" value="0" type="number" min="0" placeholder="Rate" style="width:80px">
    <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbRemoveLine(${idx})">×</button>`;
  container.appendChild(div);
};
// Package picker: a small panel toggled open under the "+ Add Line / Add
// Package" button row (not a second stacked modal — the visit modal is
// already a fixed two-column overlay). Mirrors proposals.js's "My Templates"
// dropdown-with-optgroups + save/apply/delete trio (_prSendTemplates /
// _prSaveCurrentAsTpl / _prSendApplyTemplate), the closest existing
// "saved bundle, applied with one click" pattern in this codebase.
window._sbAddPackage = async function() {
  const existing = document.getElementById('sbm-package-panel');
  if (existing) { existing.remove(); return; }
  if (_sbPackages === null) await _sbLoadPackages();
  const btnRow = document.getElementById('sbm-line-items')?.nextElementSibling;
  if (!btnRow) return;
  const panel = document.createElement('div');
  panel.id = 'sbm-package-panel';
  panel.style.cssText = 'margin-top:8px;padding:10px;border:1px solid var(--gw-border,#e2e8f0);border-radius:8px;background:var(--gw-surface-2,#f8fafc)';
  panel.innerHTML = _sbPackagePanelHtml();
  btnRow.after(panel);
};

function _sbPackagePanelHtml() {
  const byCategory = {};
  (_sbPackages || []).forEach(p => {
    const cat = p.category || 'My Packages';
    (byCategory[cat] = byCategory[cat] || []).push(p);
  });
  const options = Object.keys(byCategory).length
    ? Object.entries(byCategory).map(([cat, pkgs]) => `<optgroup label="${escapeHtml(cat)}">${
        pkgs.map(p => `<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}</option>`).join('')
      }</optgroup>`).join('')
    : '<option value="">No saved packages yet</option>';
  return `
    <div style="display:flex;gap:8px;align-items:center">
      <select class="rp-input" id="sbm-package-select" style="flex:1">${options}</select>
      <button class="rp-btn-sm" onclick="_sbApplyPackage()">Apply</button>
      <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbDeleteSelectedPackage()">Delete</button>
    </div>
    <div style="margin-top:8px">
      <button class="rp-btn-sm" onclick="_sbSaveCurrentAsPackage()">Save current items as package…</button>
    </div>`;
}

// Appends (never replaces) the chosen package's materials/equipment/checklist
// onto the visit's existing ones, reusing each field's own established
// insertion shape (_sbAddLine's row markup, _sbAddCrewItem's chip markup,
// _sbAddCheck's live wo.checklist sync) so a package-inserted row behaves
// identically to one added by hand.
window._sbApplyPackage = function() {
  const sel = document.getElementById('sbm-package-select');
  const pkg = (_sbPackages || []).find(p => p.id === sel?.value);
  if (!pkg) return;
  const wo = window._sbCurrentWO || {};

  const materials = _sbParseJsonField(pkg.materials);
  const lineContainer = document.getElementById('sbm-line-items');
  materials.forEach(m => {
    if (!wo.materials) wo.materials = [];
    const idx = wo.materials.length;
    wo.materials.push({ name: m.name || '', qty: m.qty || 1, unit: m.unit || 'ea', cost: m.cost || 0 });
    const div = document.createElement('div'); div.className = 'sb-line-row';
    div.innerHTML = `<input class="rp-input" value="${escapeHtml(m.name || '')}" placeholder="Item / Service" style="flex:2">
      <input class="rp-input" value="${m.qty || 1}" type="number" min="0" style="width:60px" placeholder="Qty">
      <input class="rp-input" value="${escapeHtml(m.unit || '')}" placeholder="Unit" style="width:70px">
      <input class="rp-input" value="${m.cost || 0}" type="number" min="0" placeholder="Rate" style="width:80px">
      <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbRemoveLine(${idx})">×</button>`;
    lineContainer?.appendChild(div);
  });

  const equipment = _sbParseJsonField(pkg.equipment);
  const equipList = document.getElementById('sbm-equip-list');
  equipList?.querySelector('.sb-empty-note')?.remove();
  equipment.forEach(val => {
    if (!val) return;
    const idx = equipList?.querySelectorAll('.sb-equip-row').length || 0;
    const row = document.createElement('div');
    row.className = 'sb-equip-row'; row.dataset.idx = idx;
    row.style.cssText = 'display:flex;align-items:center;gap:6px;padding:6px 8px;background:var(--gw-surface-3);border-radius:6px';
    row.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/></svg>
      <span style="flex:1;font-size:13px">${escapeHtml(val)}</span>
      <button class="sb-check-del" onclick="this.closest('.sb-equip-row').remove()">×</button>`;
    equipList?.appendChild(row);
  });

  const checklist = _sbParseJsonField(pkg.checklist);
  const checklistContainer = document.getElementById('sbm-checklist');
  checklistContainer?.querySelector('.sb-empty-note')?.remove();
  checklist.forEach(item => {
    if (!wo.checklist) wo.checklist = [];
    wo.checklist.push({ text: item.text || '', done: false });
    const idx = wo.checklist.length - 1;
    const div = document.createElement('div'); div.className = 'sb-check-item';
    div.innerHTML = `<button class="sb-check-box" onclick="_sbToggleCheck(${idx})"></button>
      <span class="sb-check-label">${escapeHtml(item.text || '')}</span>
      <button class="sb-check-del" onclick="_sbRemoveCheck(${idx})">×</button>`;
    checklistContainer?.appendChild(div);
  });

  showToast(`Applied "${pkg.name}"`, 'success');
  document.getElementById('sbm-package-panel')?.remove();
};

// Collects the visit's *current* materials/equipment/checklist the same way
// _sbSaveVisit does (DOM is the source of truth for materials/equipment;
// wo.checklist is already kept live-synced) and saves them as a new package.
window._sbSaveCurrentAsPackage = async function() {
  const name = prompt('Package name:');
  if (!name || !name.trim()) return;
  const materials = [...document.querySelectorAll('#sbm-line-items .sb-line-row')].map(row => {
    const inputs = row.querySelectorAll('input');
    return {
      name: inputs[0]?.value.trim() || '',
      qty:  parseFloat(inputs[1]?.value) || 0,
      unit: inputs[2]?.value.trim() || '',
      cost: parseFloat(inputs[3]?.value) || 0,
    };
  }).filter(m => m.name);
  const equipment = [...document.querySelectorAll('#sbm-equip-list .sb-equip-row')]
    .map(row => row.querySelector('span')?.textContent?.trim() || '').filter(Boolean);
  const checklist = (window._sbCurrentWO?.checklist || []).map(item => ({ text: item.text || '', done: false }));
  if (!materials.length && !equipment.length && !checklist.length) {
    showToast('Nothing to save — add some lines, equipment, or checklist items first', 'info');
    return;
  }
  try {
    const r = await fetch('/api/service-packages', {
      method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: name.trim(), materials, equipment, checklist }),
    });
    const j = await r.json();
    if (!j.ok) throw new Error(j.error || 'save failed');
    showToast(`Saved package "${name.trim()}"`, 'success');
    await _sbLoadPackages();
    const panel = document.getElementById('sbm-package-panel');
    if (panel) panel.innerHTML = _sbPackagePanelHtml();
  } catch (e) {
    showToast('Could not save package: ' + e.message, 'error');
  }
};

window._sbDeleteSelectedPackage = async function() {
  const sel = document.getElementById('sbm-package-select');
  const pkg = (_sbPackages || []).find(p => p.id === sel?.value);
  if (!pkg) return;
  if (!confirm(`Delete package "${pkg.name}"?`)) return;
  try {
    await fetch(`/api/service-packages/${pkg.id}`, { method: 'DELETE', credentials: 'include' });
    showToast('Package deleted', 'success');
    await _sbLoadPackages();
    const panel = document.getElementById('sbm-package-panel');
    if (panel) panel.innerHTML = _sbPackagePanelHtml();
  } catch (e) { showToast('Delete failed', 'error'); }
};
window._sbRemoveLine = function(idx) {
  const rows=document.querySelectorAll('#sbm-line-items .sb-line-row');
  if (rows[idx]) rows[idx].remove();
};
window._sbUploadPhoto = function(evt, field) {
  const file = evt.target?.files?.[0]; if (!file) return;
  const reader=new FileReader();
  reader.onload=e=>{
    const url=e.target.result;
    const wo=window._sbCurrentWO; if (!wo) return;
    if (!wo[field]) wo[field]=[];
    wo[field].push(url);
    const container=document.getElementById(`sb-photos-${field}`);
    const addBtn=container?.querySelector('.sb-photo-add');
    const thumb=document.createElement('div'); thumb.className='sb-photo-thumb';
    thumb.innerHTML=`<img src="${url}" alt="photo"><button onclick="_sbRemovePhoto('${field}','${url}')">×</button>`;
    if(addBtn) container.insertBefore(thumb,addBtn); else container?.appendChild(thumb);
  };
  reader.readAsDataURL(file);
};
window._sbRemovePhoto = function(field, idxOrUrl) {
  const wo=window._sbCurrentWO; if(!wo) return;
  const idx = parseInt(idxOrUrl, 10);
  if (!isNaN(idx)) {
    // index-based removal (new path)
    (wo[field]||[]).splice(idx, 1);
    const container=document.getElementById(`sb-photos-${field}`);
    if (container) {
      const thumbs = container.querySelectorAll('.sb-photo-thumb');
      if (thumbs[idx]) thumbs[idx].remove();
      // Re-index remaining thumbs
      container.querySelectorAll('.sb-photo-thumb').forEach((el,i) => el.dataset.pi = i);
    }
  } else {
    // legacy url-based removal
    wo[field]=(wo[field]||[]).filter(u=>u!==idxOrUrl);
    const container=document.getElementById(`sb-photos-${field}`);
    container?.querySelectorAll('.sb-photo-thumb').forEach(el=>{
      if(el.querySelector('img')?.src===idxOrUrl) el.remove();
    });
  }
};

// ── Attachment helpers (photos + PDFs) ────────────────────────────────────────
window._sbUploadAttachment = function(evt) {
  const files = Array.from(evt.target?.files || []);
  if (!files.length) return;
  const wo = window._sbCurrentWO; if (!wo) return;
  if (!wo.attachments) wo.attachments = [];
  const list = document.getElementById('sbm-attachments-list');
  const emptyNote = list?.querySelector('.sb-empty-note');
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = e => {
      const url = e.target.result;
      const isPdf = file.type === 'application/pdf';
      const attach = { name: file.name, url, type: isPdf ? 'pdf' : 'image' };
      wo.attachments.push(attach);
      const idx = wo.attachments.length - 1;
      if (emptyNote) emptyNote.remove();
      const row = document.createElement('div');
      row.className = 'sb-attach-row';
      row.dataset.idx = idx;
      row.innerHTML = `
        <span class="sb-attach-icon">${isPdf ? gwIcon('document',14) : gwIcon('image',14)}</span>
        <span class="sb-attach-name" style="flex:1;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(file.name)}</span>
        <a href="${url}" target="_blank" class="rp-btn-sm" style="padding:2px 8px;font-size:11px">View</a>
        <button class="sb-check-del" onclick="_sbRemoveAttachment(${idx})">×</button>`;
      list?.appendChild(row);
    };
    reader.readAsDataURL(file);
  });
};

window._sbRemoveAttachment = function(idx) {
  const wo = window._sbCurrentWO; if (!wo) return;
  wo.attachments = (wo.attachments || []).filter((_,i) => i !== idx);
  const row = document.querySelector(`#sbm-attachments-list [data-idx="${idx}"]`);
  if (row) row.remove();
  if (!wo.attachments.length) {
    const list = document.getElementById('sbm-attachments-list');
    if (list && !list.querySelector('.sb-attach-row')) {
      list.innerHTML = '<p class="sb-empty-note">No attachments yet.</p>';
    }
  }
};

// ── Go to customer detail page ────────────────────────────────────────────────
window._sbGoToCustomer = function(clientId, clientName) {
  if (clientId) {
    show('customerDetail', clientId);
  } else if (clientName) {
    // Try to find by name
    show('customerDetail', '__byname__' + clientName);
  }
};

window._sbUpsell = function(oppId) { show('oppDetail',oppId); _sbCloseModal(); };

// ── New Visit Modal ──────────────────────────────────────────────────────────
window._sbOpenNewVisit = async function(prefilledDate, prefilledCrewId, prefilledClientId, prefilledClientName) {
  const crews   = window._sbState.crews||[];
  const allReps = window._gwAllReps||[];

  const modal = document.createElement('div');
  modal.id='sb-new-visit-modal';
  modal.className='sb-modal-overlay';

  const crewOptions = crews.map(c=>`<option value="${c.id}"${c.id===prefilledCrewId?' selected':''}>${escapeHtml(c.name)}</option>`).join('');
  const repOptions  = allReps.filter(r=>r.active!==false&&r.active!==0)
    .map(r=>`<option value="${r.id}">${escapeHtml(r.name)} (${r.role||'rep'})</option>`).join('');

  modal.innerHTML=`
    <div class="sb-modal-panel sb-modal-panel--new">
      <div class="sb-modal-header">
        <div class="sb-modal-title-block"><span class="sb-modal-wo-num">Quick Add</span><span class="jb-subtitle">Just the essentials. Need scope, labor and materials? <button class="jb-linkbtn" onclick="document.getElementById('sb-new-visit-modal')?.remove();_sbOpenJobBuilder()">Open the full Job Builder</button></span></div>
        <button class="sb-modal-close" onclick="document.getElementById('sb-new-visit-modal')?.remove()">×</button>
      </div>
      <div class="sb-modal-body" style="display:block;max-height:80vh;overflow-y:auto">
        ${prefilledClientId ? `<input type="hidden" id="snv-client-id" value="${escapeHtml(prefilledClientId)}">` : ''}

        <!-- ── Row 1: Client + Type ── -->
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
          <label class="sb-modal-field">
            <span>Client / Job Name</span>
            <input class="rp-input" id="snv-client" placeholder="Client name" value="${escapeHtml(prefilledClientName||'')}">
          </label>
          <label class="sb-modal-field">
            <span>Service Type</span>
            <select class="rp-input" id="snv-type">
              <option>Landscaping</option><option>Lawn Care</option><option>Install</option>
              <option>Maintenance</option><option>Cleanup</option><option>Snow</option><option>Other</option>
            </select>
          </label>
        </div>

        <!-- ── Row 2: Date + Start Time ── -->
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
          <label class="sb-modal-field">
            <span>Date</span>
            <input class="rp-input" id="snv-date" type="date" value="${prefilledDate||''}">
          </label>
          <label class="sb-modal-field">
            <span>Start Time</span>
            <input class="rp-input" id="snv-time" type="time" value="07:00" oninput="_snvCalcEndTime()">
          </label>
        </div>

        <!-- ── Row 3: Crew + Budgeted Hours ── -->
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
          <label class="sb-modal-field">
            <span>Crew</span>
            <select class="rp-input" id="snv-crew" onchange="_snvCrewChanged()">
              <option value="">— Unassigned —</option>
              ${crewOptions}
            </select>
          </label>
          <label class="sb-modal-field">
            <span>Budgeted Hours <em style="font-size:11px;font-weight:400;opacity:.6">(total man-hours)</em></span>
            <input class="rp-input" id="snv-duration" type="number" min="0" step="0.5" placeholder="e.g. 30" oninput="_snvCalcEndTime()">
          </label>
        </div>

        <!-- ── End-time preview ── -->
        <div id="snv-endtime-preview" style="display:none;background:var(--gw-surface-2);border:1px solid var(--gw-border);border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:13px">
          <strong>Estimated finish:</strong> <span id="snv-endtime-val" style="color:var(--gw-teal,#4D8A86);font-weight:700"></span>
          <span id="snv-endtime-note" style="color:var(--gw-text-muted);margin-left:8px"></span>
        </div>

        <!-- ── Address ── -->
        <div style="margin-bottom:12px">
          <label class="sb-modal-field">
            <span>Property Address</span>
            <input class="rp-input" id="snv-addr" placeholder="123 Main St, City, State">
          </label>
        </div>

        <!-- ── Scope / Notes ── -->
        <div style="margin-bottom:12px">
          <label class="sb-modal-field">
            <span>Scope / Instructions for crew</span>
            <textarea class="rp-input" id="snv-notes" rows="3" placeholder="Describe the work, special instructions…"></textarea>
          </label>
        </div>

        <!-- ── Materials & Equipment section ── -->
        <div style="background:var(--gw-surface-2);border:1px solid var(--gw-border);border-radius:10px;padding:14px;margin-bottom:12px">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
            <h3 style="font-size:13px;font-weight:700;margin:0;display:flex;align-items:center;gap:6px">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 7H4a2 2 0 00-2 2v10a2 2 0 002 2h16a2 2 0 002-2V9a2 2 0 00-2-2z"/><path d="M16 21V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v16"/></svg>
              Materials &amp; Equipment
              <span style="font-size:11px;font-weight:400;color:var(--gw-text-muted)">(visible to crew)</span>
            </h3>
            <button class="rp-btn-sm" onclick="_snvAddMaterial()">+ Add Item</button>
          </div>
          <div id="snv-materials-list" style="display:flex;flex-direction:column;gap:6px">
            <p style="font-size:12px;color:var(--gw-text-muted);margin:0" id="snv-materials-empty">No items yet. Add materials, tools, or equipment the crew needs.</p>
          </div>
          <!-- Equipment / Vehicles row -->
          <div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--gw-border)">
            <span style="font-size:12px;font-weight:600;color:var(--gw-text-muted);display:block;margin-bottom:6px">Vehicles / Equipment</span>
            <div id="snv-equip-list" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:6px"></div>
            <div style="display:flex;gap:6px">
              <input class="rp-input" id="snv-equip-input" placeholder="e.g. Truck #2, Skid Steer" style="flex:1">
              <button class="rp-btn-sm" onclick="_snvAddEquip()">Add</button>
            </div>
          </div>
        </div>

        <!-- ── Employees ── -->
        <div>
          <span style="font-size:12px;font-weight:600;color:var(--gw-text-muted);display:block;margin-bottom:6px">Employees on this visit</span>
          <div class="sb-emp-chips" id="snv-emp-chips"><span class="sb-empty-note">None — select crew to auto-fill, or add individually.</span></div>
          <div class="sb-emp-add-row" style="margin-top:6px">
            <select class="rp-input" id="snv-add-emp" style="flex:1">${repOptions}</select>
            <button class="rp-btn-sm" onclick="_snvAddEmployee()">+ Add</button>
          </div>
        </div>
      </div>

      <div class="sb-modal-actions">
        <button class="rp-btn" onclick="document.getElementById('sb-new-visit-modal')?.remove()">Cancel</button>
        <button class="rp-btn rp-btn--primary" onclick="_snvCreate()">Create Work Order</button>
      </div>
    </div>`;

  document.body.appendChild(modal);

  // Auto-populate crew if prefilled
  if (prefilledCrewId && prefilledCrewId !== '__unassigned__') {
    setTimeout(() => _snvCrewChanged(), 50);
  }
  // Init material tracking
  window._snvMaterials = [];
  window._snvEquipment = [];
};

window._snvCrewChanged = function() {
  const crewId = document.getElementById('snv-crew')?.value;
  const crews = window._sbState.crews||[];
  const crew = crews.find(c=>c.id===crewId);
  const chipsEl = document.getElementById('snv-emp-chips');
  if (!crew?.members?.length) { _snvCalcEndTime(); return; }
  const allReps = window._gwAllReps||[];
  const placeholder = chipsEl?.querySelector('.sb-empty-note');
  if(placeholder) placeholder.remove();
  crew.members.forEach(m=>{
    if(chipsEl?.querySelector(`[data-rep-id="${m.repId}"]`)) return;
    const rep=allReps.find(r=>r.id===m.repId)||{id:m.repId,name:m.name||m.repId};
    const chip=document.createElement('span');
    chip.className='sb-emp-chip'; chip.dataset.repId=m.repId;
    chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>${escapeHtml(rep.name||m.repId)}<button onclick="this.parentElement.remove();_snvCalcEndTime()">×</button>`;
    chipsEl?.appendChild(chip);
  });
  _snvCalcEndTime();
};

window._snvAddEmployee = function() {
  const sel=document.getElementById('snv-add-emp'); if(!sel||!sel.value) return;
  const repId=sel.value;
  const allReps=window._gwAllReps||[];
  const rep=allReps.find(r=>r.id===repId)||{id:repId,name:repId};
  const chipsEl=document.getElementById('snv-emp-chips');
  if(chipsEl?.querySelector(`[data-rep-id="${repId}"]`)) return;
  const placeholder=chipsEl?.querySelector('.sb-empty-note'); if(placeholder) placeholder.remove();
  const chip=document.createElement('span');
  chip.className='sb-emp-chip'; chip.dataset.repId=repId;
  chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>${escapeHtml(rep.name||repId)}<button onclick="this.parentElement.remove();_snvCalcEndTime()">×</button>`;
  chipsEl?.appendChild(chip);
  _snvCalcEndTime();
};

// ── End-time calculator ───────────────────────────────────────────────────────
// Logic: budgetedHours / numEmployees = work hours per person
// Add 30-min lunch break if shift > 5h. Start from snv-time.
window._snvCalcEndTime = function() {
  const totalHours = parseFloat(document.getElementById('snv-duration')?.value||'0');
  const startTime  = document.getElementById('snv-time')?.value||'07:00';
  const numEmps    = Math.max(1, document.querySelectorAll('#snv-emp-chips .sb-emp-chip').length);
  const preview    = document.getElementById('snv-endtime-preview');
  const valEl      = document.getElementById('snv-endtime-val');
  const noteEl     = document.getElementById('snv-endtime-note');
  if (!totalHours || totalHours <= 0) { if(preview) preview.style.display='none'; return; }
  const hoursPerWorker = totalHours / numEmps;
  const lunchBreak = hoursPerWorker > 5 ? 0.5 : 0;
  const shiftHours = hoursPerWorker + lunchBreak;
  // Parse start
  const [sh, sm] = startTime.split(':').map(Number);
  const startMin = sh*60 + sm;
  const endMin   = startMin + Math.round(shiftHours * 60);
  const endH = Math.floor(endMin/60) % 24;
  const endM = endMin % 60;
  const endStr = `${String(endH).padStart(2,'0')}:${String(endM).padStart(2,'0')}`;
  // Human readable
  const fmt = t => { const [h,m]=t.split(':').map(Number); const ampm=h>=12?'PM':'AM'; return `${h%12||12}:${String(m).padStart(2,'0')} ${ampm}`; };
  if(preview) preview.style.display='';
  if(valEl)   valEl.textContent = fmt(endStr);
  if(noteEl)  noteEl.textContent = `(${totalHours}h total ÷ ${numEmps} worker${numEmps>1?'s':''} = ${hoursPerWorker.toFixed(1)}h/person${lunchBreak?', +30min lunch':''})`; 
  // Store computed end time
  window._snvComputedEndTime = endStr;
};

// ── Materials helpers ─────────────────────────────────────────────────────────
window._snvAddMaterial = function() {
  window._snvMaterials = window._snvMaterials||[];
  const idx = window._snvMaterials.length;
  window._snvMaterials.push({ name:'', qty:1, unit:'', cost:0 });
  const empty = document.getElementById('snv-materials-empty');
  if(empty) empty.style.display='none';
  const list = document.getElementById('snv-materials-list');
  if(!list) return;
  const row = document.createElement('div');
  row.className='sb-line-row'; row.dataset.idx=idx;
  row.innerHTML=`
    <input class="rp-input" placeholder="Material / item name" style="flex:2" oninput="window._snvMaterials[${idx}].name=this.value">
    <input class="rp-input" type="number" min="0" value="1" style="width:60px" placeholder="Qty" oninput="window._snvMaterials[${idx}].qty=parseFloat(this.value)||1">
    <input class="rp-input" placeholder="Unit" style="width:70px" oninput="window._snvMaterials[${idx}].unit=this.value">
    <button class="rp-btn-sm rp-btn-sm--danger" onclick="this.closest('.sb-line-row').remove();window._snvMaterials.splice(${idx},1)">×</button>`;
  list.appendChild(row);
};

window._snvAddEquip = function() {
  const inp = document.getElementById('snv-equip-input');
  if(!inp?.value?.trim()) return;
  const val = inp.value.trim();
  window._snvEquipment = window._snvEquipment||[];
  window._snvEquipment.push(val);
  const list = document.getElementById('snv-equip-list');
  if(list) {
    const chip = document.createElement('span');
    chip.className='sb-emp-chip';
    chip.style.cssText='background:var(--gw-surface-3);border:1px solid var(--gw-border)';
    chip.innerHTML=`${escapeHtml(val)}<button onclick="this.parentElement.remove();window._snvEquipment=window._snvEquipment.filter(e=>e!=='${val.replace(/'/g,"\\'")}')">×</button>`;
    list.appendChild(chip);
  }
  inp.value='';
};

window._snvCreate = async function() {
  const clientName = document.getElementById('snv-client')?.value?.trim();
  if(!clientName) { showToast('Client name required','error'); return; }
  const durationVal = parseFloat(document.getElementById('snv-duration')?.value||'0')||null;
  const prefilledClientId = document.getElementById('snv-client-id')?.value||null;
  const body={
    client_name:    clientName,
    client_id:      prefilledClientId||null,
    type:           document.getElementById('snv-type')?.value||'Service',
    scheduled_date: document.getElementById('snv-date')?.value||null,
    scheduled_time: document.getElementById('snv-time')?.value||null,
    scheduled_end_time: window._snvComputedEndTime||null,
    crew_id:        document.getElementById('snv-crew')?.value||null,
    duration_hours: durationVal,
    property_addr:  document.getElementById('snv-addr')?.value||'',
    notes:          document.getElementById('snv-notes')?.value||'',
    materials:      (window._snvMaterials||[]).filter(m=>m.name),
    equipment:      window._snvEquipment||[],
    employee_ids:   [...document.querySelectorAll('#snv-emp-chips .sb-emp-chip')].map(el=>el.dataset.repId).filter(Boolean),
  };
  try {
    const r=await fetch('/api/work-orders',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    const d=await r.json();
    if(!d.ok) throw new Error(d.error);
    showToast(`Work Order ${d.wo_number} created`,'success');
    document.getElementById('sb-new-visit-modal')?.remove();
    window._snvMaterials=[]; window._snvEquipment=[]; window._snvComputedEndTime=null;
    await _sbRefresh();
  } catch(e) { showToast('Create failed: '+e.message,'error'); }
};

// ── Job Builder ──────────────────────────────────────────────────────────────
//
// The full creation path. _sbOpenNewVisit above stays as the quick add: client,
// type, and optionally a date and crew, for dropping a known job onto a day. The
// brief asked to delete it; keeping a fast path is a deliberate call, because
// removing every quick route is how people end up scheduling on paper and typing
// it in later.
//
// The two differences that matter:
//
//   1. A job does not need a schedule. "Save to Job Pool" is a first-class
//      action, not an accident of leaving the date blank. The API always allowed
//      a dateless job; before the pool existed, one simply vanished.
//
//   2. Sold labor and calendar time are collected SEPARATELY. The old modal had
//      one "Budgeted Hours" box that went to duration_hours, which the grid
//      reads as the length of the block — so 24 sold hours became a 24-hour
//      block. They are different numbers and this asks for them as such.
//
// Every field here maps to a real column. Fields the brief asked for that have
// no column and no consumer — division, project manager, salesperson — are
// deliberately absent rather than collected and dropped. See migration 0070.

window._gwJobDraft = null;

window._sbOpenJobBuilder = async function(prefill) {
  prefill = prefill || {};
  const crews = window._sbState?.crews || [];
  const allReps = (window._gwAllReps || []).filter(r => r.active !== false && r.active !== 0);

  window._gwJobDraft = {
    materials: [], equipment: [], employee_ids: [],
    ...prefill,
  };

  document.getElementById('gw-job-builder')?.remove();
  const modal = document.createElement('div');
  modal.id = 'gw-job-builder';
  modal.className = 'sb-modal-overlay';

  const section = (id, title, hint, body) => `
    <section class="jb-section">
      <header class="jb-section-head">
        <h3>${title}</h3>
        ${hint ? `<p>${hint}</p>` : ''}
      </header>
      <div class="jb-section-body" id="${id}">${body}</div>
    </section>`;

  const field = (label, control, hint) => `
    <label class="jb-field">
      <span>${label}</span>
      ${control}
      ${hint ? `<small>${hint}</small>` : ''}
    </label>`;

  modal.innerHTML = `
    <div class="sb-modal-panel jb-panel">
      <div class="sb-modal-header">
        <div class="sb-modal-title-block">
          <span class="sb-modal-wo-num">New Job</span>
          <span class="jb-subtitle">A job can exist before it has a date.</span>
        </div>
        <button class="sb-modal-close" onclick="document.getElementById('gw-job-builder')?.remove()">×</button>
      </div>

      <div class="sb-modal-body jb-body">
        ${section('jb-info', 'Job Information', '', `
          <div class="jb-grid">
            ${field('Client', `<input class="rp-input" id="jb-client" placeholder="Client name" value="${escapeHtml(prefill.client_name || '')}">`)}
            ${field('Job name', `<input class="rp-input" id="jb-title" placeholder="e.g. Backyard renovation">`)}
            ${field('Service type', `<select class="rp-input" id="jb-type">
              ${['Landscaping','Lawn Care','Install','Maintenance','Cleanup','Hardscape','Drainage','Irrigation','Snow','Other']
                .map(t => `<option${t === prefill.type ? ' selected' : ''}>${t}</option>`).join('')}
            </select>`)}
            ${field('Priority', `<select class="rp-input" id="jb-priority">
              <option value="">Not set</option>
              <option value="low">Low</option>
              <option value="normal">Normal</option>
              <option value="high">High</option>
              <option value="urgent">Urgent</option>
            </select>`, 'Sorts the Job Pool.')}
            ${field('Property address', `<input class="rp-input" id="jb-addr" placeholder="Street, city">`)}
            ${field('Must be finished by', `<input class="rp-input" type="date" id="jb-deadline">`, 'Optional. Drives deadline warnings.')}
          </div>`)}

        ${section('jb-scope', 'Scope & Production Plan', 'What the crew is actually doing.', `
          ${field('Scope of work', `<textarea class="rp-input" id="jb-scope-text" rows="4" placeholder="What gets built, in the order it gets built"></textarea>`)}
          ${field('Site access', `<textarea class="rp-input" id="jb-access" rows="2" placeholder="Gate code, dogs, where to park, who to call on arrival"></textarea>`, 'Shown to the crew on the day.')}
        `)}

        ${section('jb-labor', 'Labor Plan', 'Sold labor and calendar time are different numbers. This asks for both.', `
          <div class="jb-grid">
            ${field('Sold labor (hours)', `<input class="rp-input" type="number" min="0" step="0.5" id="jb-budget-hours" oninput="_jbRecalc()" placeholder="e.g. 72">`, 'What was estimated. Never changes because the schedule changed.')}
            ${field('Target crew size', `<input class="rp-input" type="number" min="1" max="50" step="1" id="jb-crew-size" oninput="_jbRecalc()" placeholder="e.g. 3">`)}
            ${field('Hours on site per day', `<input class="rp-input" type="number" min="0" step="0.5" id="jb-day-hours" oninput="_jbRecalc()" placeholder="blank = one day">`, 'How long the job blocks the grid each day.')}
          </div>
          <output class="jb-derived" id="jb-derived">Enter sold labor and a crew size to see how many days this is.</output>
        `)}

        ${section('jb-crew', 'Crew', '', `
          <div class="jb-grid">
            ${field('Crew', `<select class="rp-input" id="jb-crew-select">
              <option value="">— None yet —</option>
              ${crews.map(c => `<option value="${c.id}"${c.id === prefill.crew_id ? ' selected' : ''}>${escapeHtml(c.name)}</option>`).join('')}
            </select>`, 'Its roster is planned onto every day of the job.')}
            ${field('Also include', `<select class="rp-input" id="jb-extra-rep" onchange="_jbAddRep(this.value); this.value=''">
              <option value="">Add a person…</option>
              ${allReps.map(r => `<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}
            </select>`, 'People beyond the crew roster.')}
          </div>
          <div class="jb-chips" id="jb-rep-chips"></div>
        `)}

        ${section('jb-materials', 'Materials & Equipment', '', `
          ${field('Materials', `<textarea class="rp-input" id="jb-materials" rows="3" placeholder="One per line — 4 yd topsoil&#10;120 lf paver edging"></textarea>`)}
          ${field('Equipment', `<textarea class="rp-input" id="jb-equipment" rows="2" placeholder="One per line — Skid steer&#10;F-350 + dump trailer"></textarea>`,
            'Recorded on the job. Reserving a specific machine against a date needs the asset link table that Phase 7 adds — until then this is a note, not a booking.')}
        `)}

        ${section('jb-schedule', 'Schedule', 'Optional. Leave blank and the job waits in the Job Pool.', `
          <div class="jb-radios" role="radiogroup" aria-label="Schedule type">
            <label><input type="radio" name="jb-sched-type" value="single" checked onchange="_jbScheduleType()"> Single day</label>
            <label><input type="radio" name="jb-sched-type" value="multi" onchange="_jbScheduleType()"> Multiple days</label>
            <label><input type="radio" name="jb-sched-type" value="tbd" onchange="_jbScheduleType()"> Flexible / TBD</label>
          </div>
          <div class="jb-grid" id="jb-sched-fields">
            ${field('Start date', `<input class="rp-input" type="date" id="jb-date" value="${escapeHtml(prefill.scheduled_date || '')}" onchange="_jbRecalc()">`)}
            ${field('Start time', `<input class="rp-input" type="time" id="jb-time" value="${escapeHtml(prefill.scheduled_time || '07:00')}">`)}
            <div id="jb-days-field" hidden>${field('How many days', `<input class="rp-input" type="number" min="2" max="30" step="1" id="jb-days" value="3" oninput="_jbRecalc()">`, 'Consecutive working days, skipping weekends.')}</div>
          </div>
          <div id="jb-preview"></div>
        `)}
      </div>

      <div class="sb-modal-actions jb-actions">
        <button class="rp-btn" onclick="document.getElementById('gw-job-builder')?.remove()">Cancel</button>
        <div class="jb-actions-right">
          <button class="rp-btn" onclick="_jbSave(false)">Save to Job Pool</button>
          <button class="rp-btn rp-btn--primary" onclick="_jbSave(true)">Save &amp; Schedule</button>
        </div>
      </div>
    </div>`;

  document.body.appendChild(modal);
  _jbRecalc();
};

/**
 * Expected production days, derived rather than typed.
 *
 * "If a value can be derived, never add an input for it" — CLAUDE.md. Sold
 * labor divided by the crew divided by a productive day is exactly derivable,
 * so it is shown, not asked for.
 *
 * Productive minutes come from the week payload, which carries the company's
 * own setting, not a hardcoded 8 hours. A shift is not all productive time.
 */
window._jbRecalc = function() {
  const out = document.getElementById('jb-derived');
  if (!out) return;
  const soldHours = parseFloat(document.getElementById('jb-budget-hours')?.value || '') || 0;
  const crewSize  = parseInt(document.getElementById('jb-crew-size')?.value || '', 10) || 0;
  const productiveMinutes = window._sbState?.capacity?.working_hours?.productive_minutes_per_day || 450;
  const productiveHours = productiveMinutes / 60;

  if (!soldHours || !crewSize) {
    out.textContent = 'Enter sold labor and a crew size to see how many days this is.';
    out.classList.remove('jb-derived--set');
    return;
  }
  const days = soldHours / crewSize / productiveHours;
  const rounded = Math.max(1, Math.ceil(days - 0.05)); // 3.02 days is 3, 3.4 is 4
  out.innerHTML = `<strong>${rounded} production day${rounded === 1 ? '' : 's'}</strong> `
    + `— ${soldHours}h ÷ ${crewSize} ${crewSize === 1 ? 'person' : 'people'} ÷ ${productiveHours.toFixed(1)}h productive`
    + (rounded > 1 ? ' · schedule the first day here, then split it into phases from the job screen.' : '');
  out.classList.add('jb-derived--set');
  _jbRenderPreview();
};

window._jbScheduleType = function() {
  const type = document.querySelector('input[name="jb-sched-type"]:checked')?.value || 'single';
  const fields = document.getElementById('jb-sched-fields');
  const daysField = document.getElementById('jb-days-field');
  if (fields) fields.hidden = type === 'tbd';
  if (daysField) daysField.hidden = type !== 'multi';
  _jbRecalc();
};

/**
 * The days this job would occupy, shown before anything is written.
 *
 * The brief asks for a preview table, and it earns its place: the old flow
 * created the job, then made you open a panel, type a day count, and press
 * "Set Up Multi-Day Job" — by which point rows already existed and undoing
 * meant deleting them. Nothing here has been written yet.
 *
 * Working days come from the company's own setting, so a four-day-week crew
 * does not get handed a Friday.
 */
function _jbPreviewDays() {
  const type = document.querySelector('input[name="jb-sched-type"]:checked')?.value || 'single';
  const start = document.getElementById('jb-date')?.value || '';
  if (type === 'tbd' || !start) return [];
  const count = type === 'multi' ? Math.max(2, Math.min(30, parseInt(document.getElementById('jb-days')?.value || '2', 10) || 2)) : 1;
  const working = window._sbState?.capacity?.working_hours?.working_days || [1, 2, 3, 4, 5];
  const out = [];
  let cursor = start;
  let guard = 0;
  while (out.length < count && guard++ < 400) {
    const dow = gwDateParse(cursor)?.getDay();
    if (working.includes(dow)) out.push(cursor);
    cursor = gwDateAddDays(cursor, 1);
  }
  return out;
}

function _jbRenderPreview() {
  const host = document.getElementById('jb-preview');
  if (!host) return;
  const days = _jbPreviewDays();
  const type = document.querySelector('input[name="jb-sched-type"]:checked')?.value || 'single';
  if (type !== 'multi' || days.length < 2) { host.innerHTML = ''; return; }

  const crewName = document.getElementById('jb-crew-select')?.selectedOptions?.[0]?.textContent?.trim() || '—';
  const soldHours = parseFloat(document.getElementById('jb-budget-hours')?.value || '') || 0;
  const crewSize = parseInt(document.getElementById('jb-crew-size')?.value || '', 10) || 0;
  // Sold labor spread evenly across the days, which is a plan, not a promise —
  // the real per-day figure comes from who is actually rostered on each day.
  const perDay = soldHours && days.length ? (soldHours / days.length) : 0;

  host.innerHTML = `
    <table class="jb-preview">
      <thead><tr><th>Day</th><th>Date</th><th>Crew</th><th class="jb-num">Planned labor</th></tr></thead>
      <tbody>
        ${days.map((d, i) => `<tr>
          <td>${i + 1}/${days.length}</td>
          <td>${escapeHtml(gwDateFormat(d, { weekday:'short', month:'short', day:'numeric' }))}</td>
          <td>${escapeHtml(crewName)}</td>
          <td class="jb-num">${perDay ? perDay.toFixed(1) + 'h' : '—'}</td>
        </tr>`).join('')}
      </tbody>
    </table>
    <p class="jb-preview-note">One job, ${days.length} scheduled days — never ${days.length} separate work orders.
    ${crewSize ? '' : 'Set a target crew size to see how many days this really needs.'}</p>`;
}

window._jbAddRep = function(repId) {
  if (!repId) return;
  const draft = window._gwJobDraft;
  if (!draft || draft.employee_ids.includes(repId)) return;
  draft.employee_ids.push(repId);
  _jbRenderChips();
};
window._jbRemoveRep = function(repId) {
  const draft = window._gwJobDraft;
  if (!draft) return;
  draft.employee_ids = draft.employee_ids.filter(id => id !== repId);
  _jbRenderChips();
};
function _jbRenderChips() {
  const host = document.getElementById('jb-rep-chips');
  if (!host) return;
  const reps = window._gwAllReps || [];
  host.innerHTML = (window._gwJobDraft?.employee_ids || []).map(id => {
    const r = reps.find(x => x.id === id);
    return `<span class="jb-chip">${escapeHtml(r?.name || id)}<button onclick="_jbRemoveRep('${escapeHtml(id)}')" aria-label="Remove">×</button></span>`;
  }).join('');
}

const _jbLines = (id) => (document.getElementById(id)?.value || '')
  .split('\n').map(s => s.trim()).filter(Boolean);

window._jbSave = async function(withSchedule) {
  const clientName = document.getElementById('jb-client')?.value?.trim();
  if (!clientName) return showToast('Client name required', 'error');

  const schedType = document.querySelector('input[name="jb-sched-type"]:checked')?.value || 'single';
  const date = schedType === 'tbd' ? null : (document.getElementById('jb-date')?.value || null);
  if (withSchedule && !date) {
    return showToast(schedType === 'tbd'
      ? 'Flexible jobs go to the Job Pool — pick a date to schedule one'
      : 'Pick a start date, or save to the Job Pool instead', 'error');
  }
  const previewDays = withSchedule ? _jbPreviewDays() : [];

  const dayHours = parseFloat(document.getElementById('jb-day-hours')?.value || '') || 0;
  const soldHours = parseFloat(document.getElementById('jb-budget-hours')?.value || '') || 0;

  const body = {
    client_name: clientName,
    title: document.getElementById('jb-title')?.value?.trim() || '',
    type: document.getElementById('jb-type')?.value || 'Service',
    property_addr: document.getElementById('jb-addr')?.value?.trim() || '',
    notes: document.getElementById('jb-scope-text')?.value || '',
    access_notes: document.getElementById('jb-access')?.value || '',
    priority: document.getElementById('jb-priority')?.value || null,
    required_completion_date: document.getElementById('jb-deadline')?.value || null,
    target_crew_size: parseInt(document.getElementById('jb-crew-size')?.value || '', 10) || null,
    // Sold labor and calendar span, kept apart all the way to the column.
    budget_hours: soldHours || null,
    scheduled_duration_minutes: dayHours ? Math.round(dayHours * 60) : null,
    crew_id: document.getElementById('jb-crew-select')?.value || null,
    employee_ids: window._gwJobDraft?.employee_ids || [],
    materials: _jbLines('jb-materials').map(name => ({ name })),
    equipment: _jbLines('jb-equipment'),
    // Only when scheduling. A pool job with a stray time on it would show up
    // in the wrong place the moment anything read scheduled_time.
    scheduled_date: withSchedule ? date : null,
    scheduled_time: withSchedule ? (document.getElementById('jb-time')?.value || null) : null,
  };

  try {
    const r = await fetch('/api/work-orders', {
      method: 'POST', credentials: 'include',
      headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error || 'Create failed');
    // One job, N scheduled days. Never N work orders — that is the distinction
    // the whole Job / Job Day split exists to make, and the reason this posts
    // once and then splits, rather than looping over create.
    if (withSchedule && previewDays.length > 1) {
      const r2 = await fetch(`/api/work-orders/${d.id}/multiday`, {
        method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          total_days: previewDays.length,
          start_date: previewDays[0],
          day_scopes: previewDays.map((_, i) => `Day ${i + 1} of ${previewDays.length}`),
        }),
      });
      if (!r2.ok) showToast('Job created, but splitting it into days failed — open it to retry', 'error');
    }
    showToast(
      !withSchedule ? `${d.wo_number} saved to the Job Pool`
        : previewDays.length > 1 ? `${d.wo_number} scheduled across ${previewDays.length} days`
        : `${d.wo_number} scheduled`,
      'success');
    document.getElementById('gw-job-builder')?.remove();
    window._gwJobDraft = null;
    await _sbRefresh();
  } catch (e) {
    showToast('Create failed: ' + (e && e.message ? e.message : e), 'error');
  }
};

// ── Crew Manager Modal ────────────────────────────────────────────────────────
window._sbOpenCrewManager = async function() {
  // Ensure fresh data
  try {
    const [cr,rr] = await Promise.all([
      fetch('/api/crews',{credentials:'include'}).then(r=>r.json()),
      fetch('/api/reps',{credentials:'include'}).then(r=>r.json()),
    ]);
    if(cr.ok) window._sbState.crews = cr.data||[];
    if(rr.ok) window._gwAllReps = rr.data||rr.reps||[];
  } catch(e){}

  _sbRenderCrewManager();
};

function _sbRenderCrewManager() {
  const existing = document.getElementById('sb-crew-manager-modal');
  if(existing) existing.remove();

  const crews   = window._sbState.crews||[];
  const allReps = window._gwAllReps||[];

  const PALETTE = ['#22c55e','#3b82f6','#f59e0b','#ef4444','#8b5cf6','#ec4899','#14b8a6','#f97316','#6366f1','#84cc16'];

  const crewRows = crews.map(cr=>{
    const memberNames = (cr.members||[]).map(m=>{
      const r=allReps.find(x=>x.id===m.repId); return `${r?.name||m.repId} (${m.crewRole})`;
    }).join(', ');
    return `
      <div class="sb-cm-crew-row" id="cm-crew-${cr.id}">
        <span class="sb-crew-dot-lg" style="background:${cr.color}"></span>
        <div class="sb-cm-crew-info">
          <strong>${escapeHtml(cr.name)}</strong>
          <span class="sb-cm-members">${memberNames||'No members'}</span>
        </div>
        <div class="sb-cm-crew-actions">
          <button class="rp-btn-sm" onclick="_sbEditCrew('${cr.id}')">Edit</button>
          <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbDeleteCrew('${cr.id}')">Delete</button>
        </div>
      </div>`;
  }).join('');

  const repOptions = allReps.filter(r=>r.active!==false&&r.active!==0)
    .map(r=>`<option value="${r.id}">${escapeHtml(r.name)} (${r.role||'rep'})</option>`).join('');

  const colorSwatches = PALETTE.map(c=>`
    <button class="sb-color-swatch" style="background:${c}" data-color="${c}" onclick="_sbPickColor('${c}',this)"></button>`).join('');

  const modal=document.createElement('div');
  modal.id='sb-crew-manager-modal';
  modal.className='sb-modal-overlay';
  modal.innerHTML=`
    <div class="sb-modal-panel sb-modal-panel--crew-mgr">
      <div class="sb-modal-header">
        <div class="sb-modal-title-block"><span class="sb-modal-wo-num">Crew Manager</span></div>
        <button class="sb-modal-close" onclick="document.getElementById('sb-crew-manager-modal')?.remove()">×</button>
      </div>
      <div class="sb-modal-body" style="display:block;max-height:70vh;overflow-y:auto">
        <!-- Existing Crews -->
        <section class="sb-modal-section">
          <h3 class="sb-modal-section-title">Your Crews</h3>
          <div id="sb-cm-crew-list">
            ${crewRows||'<p class="sb-empty-note">No crews yet. Create your first crew below.</p>'}
          </div>
        </section>

        <!-- Create New Crew -->
        <section class="sb-modal-section" style="border-top:1px solid var(--gw-border);padding-top:20px;margin-top:8px">
          <h3 class="sb-modal-section-title">Create New Crew</h3>
          <div style="display:grid;gap:12px">
            <label class="sb-modal-field">
              <span>Crew Name</span>
              <input class="rp-input" id="cm-crew-name" placeholder="e.g. Landscape Crew, Snow Team A">
            </label>
            <div class="sb-modal-field">
              <span>Crew Color</span>
              <div class="sb-color-palette" id="cm-color-palette">${colorSwatches}</div>
              <input type="hidden" id="cm-crew-color" value="${PALETTE[0]}">
            </div>
            <div class="sb-modal-field">
              <span>Members</span>
              <div class="sb-emp-chips" id="cm-emp-chips"><span class="sb-empty-note">Add employees below.</span></div>
              <div class="sb-emp-add-row" style="margin-top:6px">
                <select class="rp-input" id="cm-emp-role">
                  <option value="laborer">Laborer</option>
                  <option value="foreman">Foreman</option>
                </select>
                <select class="rp-input" id="cm-emp-select">${repOptions}</select>
                <button class="rp-btn-sm" onclick="_sbCmAddMember()">+ Add</button>
              </div>
            </div>
          </div>
        </section>
      </div>
      <div class="sb-modal-actions">
        <button class="rp-btn" onclick="document.getElementById('sb-crew-manager-modal')?.remove()">Close</button>
        <button class="rp-btn rp-btn--primary" onclick="_sbCreateCrew()">Create Crew</button>
      </div>
    </div>`;

  document.body.appendChild(modal);
  // Pre-select first color
  const firstSwatch = modal.querySelector('.sb-color-swatch');
  if(firstSwatch) firstSwatch.classList.add('selected');
}

window._sbPickColor = function(color, btn) {
  document.querySelectorAll('#cm-color-palette .sb-color-swatch').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  const inp = document.getElementById('cm-crew-color');
  if(inp) inp.value = color;
};
window._sbCmAddMember = function() {
  const sel=document.getElementById('cm-emp-select');
  const roleEl=document.getElementById('cm-emp-role');
  if(!sel||!sel.value) return;
  const repId=sel.value; const crewRole=roleEl?.value||'laborer';
  const allReps=window._gwAllReps||[];
  const rep=allReps.find(r=>r.id===repId)||{id:repId,name:repId};
  const chipsEl=document.getElementById('cm-emp-chips');
  if(chipsEl?.querySelector(`[data-rep-id="${repId}"]`)) { showToast('Already added','info'); return; }
  const placeholder=chipsEl?.querySelector('.sb-empty-note'); if(placeholder) placeholder.remove();
  const chip=document.createElement('span');
  chip.className='sb-emp-chip'; chip.dataset.repId=repId; chip.dataset.crewRole=crewRole;
  chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>
    <strong style="font-size:11px;color:var(--gw-text-muted);text-transform:uppercase">${crewRole}</strong>
    &nbsp;${escapeHtml(rep.name||repId)}<button onclick="this.parentElement.remove()">×</button>`;
  chipsEl?.appendChild(chip);
};
window._sbCreateCrew = async function() {
  const name=document.getElementById('cm-crew-name')?.value?.trim();
  if(!name) { showToast('Crew name required','error'); return; }
  const color=document.getElementById('cm-crew-color')?.value||'#22c55e';
  const chips=[...document.querySelectorAll('#cm-emp-chips .sb-emp-chip')];
  const members=chips.map(c=>({repId:c.dataset.repId, crewRole:c.dataset.crewRole||'laborer'}));
  try {
    const r=await fetch('/api/crews',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,color,members})});
    const d=await r.json();
    if(!d.ok) throw new Error(d.error);
    showToast(`Crew "${name}" created`,'success');
    document.getElementById('sb-crew-manager-modal')?.remove();
    window._sbState.loaded=false;
    await _sbLoadData();
    _sbRenderCrewManager();
    _sbRender();
  } catch(e) { showToast('Create failed: '+e.message,'error'); }
};

window._sbEditCrew = async function(crewId) {
  const crew = (window._sbState.crews||[]).find(c=>c.id===crewId);
  if(!crew) return;
  const newName = prompt('Crew name:', crew.name);
  if(newName===null) return;
  try {
    await fetch(`/api/crews/${crewId}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:newName,color:crew.color})});
    showToast('Crew updated','success');
    window._sbState.loaded=false; await _sbLoadData();
    document.getElementById('sb-crew-manager-modal')?.remove();
    _sbRenderCrewManager(); _sbRender();
  } catch(e) { showToast('Update failed','error'); }
};
window._sbDeleteCrew = async function(crewId) {
  const crew=(window._sbState.crews||[]).find(c=>c.id===crewId);
  if(!confirm(`Delete crew "${crew?.name}"? Work orders will become unassigned.`)) return;
  try {
    await fetch(`/api/crews/${crewId}`,{method:'DELETE'});
    showToast('Crew deleted','success');
    window._sbState.loaded=false; await _sbLoadData();
    document.getElementById('sb-crew-manager-modal')?.remove();
    _sbRenderCrewManager(); _sbRender();
  } catch(e) { showToast('Delete failed','error'); }
};

// ── 3. Dispatch Board ─────────────────────────────────────────────────────────
function dispatchBoard() {
  const R   = window.GW && window.GW.record;
  const wos = state.workOrders || [];

  // Group by crew
  const crews = {};
  wos.filter(w => w.status === 'scheduled' || w.status === 'in-progress').forEach(w => {
    const c = w.crew || 'Unassigned';
    if (!crews[c]) crews[c] = [];
    crews[c].push(w);
  });
  const crewNames = Object.keys(crews).sort();

  const crewPanels = crewNames.map(crew => {
    const jobs = crews[crew];
    const jobRows = jobs.map(wo => `
      <div class="disp-job-row" onclick="show('workOrderDetail','${wo.id}')" style="cursor:pointer">
        <span class="disp-job-num">${_p6WONum(wo)}</span>
        <span class="disp-job-client">${escapeHtml(wo.clientName||wo.oppId||'—')}</span>
        <span>${R ? R.ReadinessBadge(wo.readiness||'ready') : ''}</span>
        <span class="disp-job-time">${wo.time||'—'}</span>
      </div>`).join('') || '<p class="disp-empty">No jobs dispatched</p>';

    return `
      <div class="disp-crew-card">
        <div class="disp-crew-head">
          <span class="disp-crew-name">${escapeHtml(crew)}</span>
          <span class="disp-crew-count">${jobs.length} job${jobs.length!==1?'s':''}</span>
        </div>
        <div class="disp-crew-jobs">${jobRows}</div>
      </div>`;
  }).join('') || `
    <div class="gwp-empty" style="margin-bottom:0;padding:36px 20px">
      <div class="gwp-empty-title">No active dispatches today</div>
      <div class="gwp-empty-sub">Schedule a work order to see it on the board.</div>
      <div class="gwp-empty-actions">
        <button class="gwp-btn-primary" onclick="show('workOrderList')">+ Schedule Work Order</button>
      </div>
    </div>`;

  // Activity feed
  const feedEvents = wos.slice(-8).reverse().map(wo => ({
    title: _p6WONum(wo) + ' — ' + (wo.clientName||wo.oppId||'Job'),
    desc:  _p6WOStatusLabel(wo.status) + (wo.crew ? ' · ' + wo.crew : ''),
    time:  wo.updatedAt ? _p5FmtDate(wo.updatedAt) : (wo.date ? _p5FmtDate(wo.date) : '—'),
    variant: wo.status === 'completed' ? 'positive' : wo.status === 'in-progress' ? 'info' : 'neutral'
  }));
  const feedHtml = R ? R.OpsTL(feedEvents) : feedEvents.map(e => `<div style="padding:8px 0;border-bottom:1px solid var(--gw-border)"><strong>${escapeHtml(e.title)}</strong><br><small>${escapeHtml(e.desc)}</small></div>`).join('');

  const _dInProg = wos.filter(w=>w.status==='in-progress').length;
  const _dSched  = wos.filter(w=>w.status==='scheduled').length;
  const _dHolds  = wos.filter(w=>w.status==='hold').length;
  const _dDone   = wos.filter(w=>w.status==='completed').length;

  view.innerHTML = `
  <div class="gwp-shell">
    <header class="gwp-header">
      <div class="gwp-header-left">
        <h1 class="gwp-title">Dispatch Board</h1>
        <span class="gwp-subtitle">${crewNames.length} crew${crewNames.length!==1?'s':''} · ${_dInProg} in progress</span>
      </div>
      <div class="gwp-header-actions">
        <button class="gwp-btn-ghost" onclick="show('scheduleBoard')">Schedule View</button>
        <button class="gwp-btn-primary" onclick="show('workOrderList')">+ Job</button>
      </div>
    </header>

    <div class="gwp-kpi-row">
      <div class="gwp-kpi-card gwp-kpi-card--blue">
        <div class="gwp-kpi-icon gwp-kpi-icon--blue"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="2" y="3" width="12" height="11" rx="1.5"/><path d="M2 6.5h12M5.5 1.5v3M10.5 1.5v3"/></svg></div>
        <div class="gwp-kpi-body"><div class="gwp-kpi-value">${_dSched}</div><div class="gwp-kpi-label">Scheduled</div></div>
      </div>
      <div class="gwp-kpi-card${_dInProg?' gwp-kpi-card--green':''}">
        <div class="gwp-kpi-icon gwp-kpi-icon--purple"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="8" cy="8" r="7"/><path d="M8 4v4l3 2"/></svg></div>
        <div class="gwp-kpi-body"><div class="gwp-kpi-value">${_dInProg}</div><div class="gwp-kpi-label">In Progress</div></div>
      </div>
      ${_dHolds ? `<div class="gwp-kpi-card gwp-kpi-card--yellow" title="Jobs held — waiting for the client to accept the estimate">
        <div class="gwp-kpi-icon gwp-kpi-icon--yellow"><span style="width:10px;height:10px;border-radius:50%;background:#EAB308;display:inline-block"></span></div>
        <div class="gwp-kpi-body"><div class="gwp-kpi-value">${_dHolds}</div><div class="gwp-kpi-label">Holds</div></div>
      </div>` : `<div class="gwp-kpi-card gwp-kpi-card--green">
        <div class="gwp-kpi-icon gwp-kpi-icon--green"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 8l4 4 8-8"/></svg></div>
        <div class="gwp-kpi-body"><div class="gwp-kpi-value">${_dDone}</div><div class="gwp-kpi-label">Completed</div></div>
      </div>`}
      <div class="gwp-kpi-card gwp-kpi-card--muted">
        <div class="gwp-kpi-icon gwp-kpi-icon--muted"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="5.5" cy="5" r="2.5"/><circle cx="11" cy="6" r="2"/><path d="M1.5 13.5c0-2.2 1.8-4 4-4s4 1.8 4 4M9.5 13.5c0-1.9 1.3-3.2 3-3.2 1.2 0 2.2.6 2.7 1.6"/></svg></div>
        <div class="gwp-kpi-body"><div class="gwp-kpi-value">${crewNames.length}</div><div class="gwp-kpi-label">Active Crews</div></div>
      </div>
    </div>

    <div class="disp-layout" style="grid-template-columns:minmax(300px,380px) 1fr">
      <div class="gwp-card" id="disp-crew-panel" style="margin-bottom:0">
        <div class="gwp-card-head">
          <div class="gwp-card-icon"><svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="5.5" cy="5" r="2.5"/><circle cx="11" cy="6" r="2"/><path d="M1.5 13.5c0-2.2 1.8-4 4-4s4 1.8 4 4M9.5 13.5c0-1.9 1.3-3.2 3-3.2 1.2 0 2.2.6 2.7 1.6"/></svg></div>
          <div class="gwp-card-head-text"><div class="gwp-card-title">Crews</div><div class="gwp-card-desc">Today's dispatched jobs by crew</div></div>
        </div>
        <div class="gwp-card-body">${crewPanels}</div>
      </div>
      <div class="gwp-card" id="disp-feed-panel" style="margin-bottom:0">
        <div class="gwp-card-head">
          <div class="gwp-card-icon gwp-card-icon--blue"><svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 8h3l2-5 3 10 2-5h2"/></svg></div>
          <div class="gwp-card-head-text"><div class="gwp-card-title">Activity Feed</div><div class="gwp-card-desc">Latest work order updates</div></div>
        </div>
        <div class="gwp-card-body">${feedHtml || '<p style="color:var(--gw-text-muted);font-style:italic;margin:0">No recent activity.</p>'}</div>
      </div>
    </div>
  </div>`;
}
window.dispatchBoard = dispatchBoard;

// ── 4. Recurring Services — delegates to full v2 implementation in recurring_plans.js ──
function recurringServices() {
  // Full-featured v2 UI lives in recurring_plans.js → window.gwRecurringPlans
  if (typeof window.gwRecurringPlans === 'function') {
    window.gwRecurringPlans();
    return;
  }
  // Fallback stub if script hasn't loaded yet
  const plans = state.recurringPlans || [];
  const today = new Date().toISOString().slice(0,10);

  const dueSoon = plans.filter(p => p.status==='active' && p.nextVisit && p.nextVisit <= new Date(Date.now()+7*864e5).toISOString().slice(0,10));
  const active  = plans.filter(p => p.status==='active');
  const paused  = plans.filter(p => p.status==='paused');

  function planRow(p) {
    const overdue = p.nextVisit && p.nextVisit < today;
    return `
    <div class="recur-row" onclick="show('workOrderList')" style="cursor:pointer">
      <span class="recur-client">${escapeHtml(p.clientName||p.clientId||'—')}</span>
      <span class="recur-freq">${_p6FreqLabel(p.freq)}</span>
      <span class="recur-next${overdue?' recur-next--overdue':''}">${p.nextVisit ? _p5FmtDate(p.nextVisit) : '—'}</span>
      <span class="recur-crew">${escapeHtml(p.crew||'Unassigned')}</span>
      <span><span class="ops-ready-badge ${p.status==='active'?'wo-status--completed':p.status==='paused'?'wo-status--onhold':'wo-status--cancelled'}">${p.status||'active'}</span></span>
      <span class="recur-actions">
        <button class="rp-btn-sm" onclick="event.stopPropagation();show('workOrderList')">Create WO</button>
      </span>
    </div>`;
  }

  const dueShelf = dueSoon.length ? `
    <div class="recur-due-shelf">
      <div class="recur-shelf-head">Due Within 7 Days (${dueSoon.length})</div>
      ${dueSoon.map(planRow).join('')}
    </div>` : '';

  const allRows = plans.length
    ? plans.map(planRow).join('')
    : `<div class="rp-empty-state"><p>No recurring service plans yet.</p><button class="rp-btn rp-btn--primary" onclick="show('clients')">Link Client Plan</button></div>`;

  view.innerHTML = `
  <div class="recur-shell">
    <header class="rp-header">
      <div class="rp-header-left">
        <h1 class="rp-title">Recurring Services</h1>
        <p class="rp-subtitle">${active.length} active · ${paused.length} paused · ${dueSoon.length} due soon</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('opsHub')">← Ops Hub</button>
      </div>
    </header>
    <div style="max-width:1100px;margin:0 auto;padding:0 24px 32px">
      ${dueShelf}
      <div class="recur-list">
        <div class="recur-list-head" style="display:grid;grid-template-columns:1fr auto auto auto auto auto;gap:10px;padding:6px 12px;border-bottom:2px solid var(--gw-border)">
          <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Client</span>
          <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Frequency</span>
          <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Next Visit</span>
          <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Crew</span>
          <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Status</span>
          <span></span>
        </div>
        ${allRows}
      </div>
    </div>
  </div>`;
}
window.recurringServices = recurringServices;

// ── 5. Work Order List ────────────────────────────────────────────────────────
async function workOrderList() {
  // Show skeleton
  const _wlT = (typeof window._t === 'function') ? window._t : (s => s);
  view.innerHTML = `<div style="padding:40px;text-align:center;color:var(--gw-text-muted)"><div class="sb-spinner"></div><p style="margin-top:12px">${_wlT('Loading work orders…')}</p></div>`;

  // Load from D1 + localStorage fallback
  let wos = [];
  try {
    // Field roles only see their own assigned work orders
    const _wlRep = window._d1SessionRep || (window.getCurrentRep ? window.getCurrentRep() : null);
    const _wlFieldRoles = window._GW_FIELD_ROLES || ['foreman','laborer','field_supervisor'];
    const _wlIsField = _wlRep && _wlFieldRoles.includes(_wlRep.role);
    const _wlUrl = _wlIsField
      ? `/api/work-orders?rep_id=${encodeURIComponent(_wlRep.id)}`
      : '/api/work-orders';
    const r = await fetch(_wlUrl, {credentials:'include'});
    const d = await r.json();
    if (d.ok) wos = d.data||[];
  } catch(e) {
    wos = (state.workOrders||[]).map(w=>({
      id:w.id, wo_number:w.woNumber||w.id, client_name:w.clientName||'',
      type:w.type||'Service', status:w.status||'scheduled',
      scheduled_date:w.date||null, crew_name:w.crew||'', crew_color:'#94a3b8',
    }));
  }

  const counts = { hold:0, scheduled:0, 'in-progress':0, completed:0, cancelled:0, 'on-hold':0 };
  wos.forEach(w => { if (counts[w.status]!==undefined) counts[w.status]++; });

  const rows = wos.length ? wos.map(wo => {
    const crewColor = wo.crew_color || '#94a3b8';
    return `
    <div class="wo-row" onclick="_sbOpenVisitModal('${wo.id}')" style="cursor:pointer">
      <span class="wo-number">${escapeHtml(wo.wo_number||wo.id)}</span>
      <span class="wo-client">${escapeHtml(wo.client_name||wo.title||'—')}</span>
      <span class="wo-type">${escapeHtml(wo.type||'Service')}</span>
      <span class="wo-date">${wo.scheduled_date ? _p5FmtDate(wo.scheduled_date) : '—'}</span>
      <span style="display:flex;align-items:center;gap:6px">
        ${wo.crew_name?`<span style="width:8px;height:8px;border-radius:50%;background:${crewColor};display:inline-block"></span>`:''}
        ${escapeHtml(wo.crew_name||_wlT('Unassigned'))}
      </span>
      <span><span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}">${_p6WOStatusLabel(wo.status)}</span></span>
      <span class="wo-actions">
        <button class="rp-btn-sm" onclick="event.stopPropagation();_sbOpenVisitModal('${wo.id}')">Open</button>
        <button class="rp-btn-sm rp-btn-sm--danger" onclick="event.stopPropagation();_wlDeleteWO('${wo.id}')">✕</button>
      </span>
    </div>`;
  }).join('')
  : `<div class="rp-empty-state" style="padding:48px 24px;text-align:center"><p style="color:var(--gw-text-muted);margin-bottom:16px">${_wlT('No work orders yet.')}</p><button class="rp-btn rp-btn--primary" onclick="_sbOpenNewVisit(null)">${_wlT('+ Create First Work Order')}</button></div>`;

  view.innerHTML = `
  <div class="wo-list-shell gw-list-shell">
    <header class="rp-header gw-list-header">
      <div class="rp-header-left">
        <h1 class="rp-title">${_wlT('Work Orders')}</h1>
        <p class="rp-subtitle">${wos.length} ${_wlT('total')} · ${counts['in-progress']} ${_wlT('in progress')} · ${counts.scheduled} ${_wlT('scheduled')}</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('scheduleBoard')">${_wlT('Schedule Board')}</button>
        <button class="rp-btn rp-btn--primary" onclick="_sbOpenNewVisit(null)">${_wlT('+ New Work Order')}</button>
      </div>
    </header>

    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;padding-top:4px">
      ${Object.entries(counts).map(([s,n]) => `
        <span class="ops-ready-badge ${_p6WOStatusClass(s)}" style="cursor:default">${_p6WOStatusLabel(s)}: ${n}</span>`).join('')}
    </div>

    <div style="border:1px solid var(--gw-border);border-radius:var(--gw-r-md);overflow:hidden;background:var(--gw-bg-surface-2)">
      <div class="wo-row" style="background:var(--gw-bg-surface-3);cursor:default;font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">
        <span>${_wlT('WO #')}</span><span>${_wlT('Client')}</span><span>${_wlT('Type')}</span><span>${_wlT('Date')}</span><span>${_wlT('Crew')}</span><span>${_wlT('Status')}</span><span></span>
      </div>
      ${rows}
    </div>
  </div>`;

  // Preload sbState so modal works from work order list
  if (!window._sbState.loaded) {
    _sbLoadData().catch(()=>{});
  }
}
window.workOrderList = workOrderList;
window._wlDeleteWO = async function(id) {
  if (!confirm('Delete this work order?')) return;
  try {
    await fetch(`/api/work-orders/${id}`,{method:'DELETE'});
    showToast('Work order deleted','success');
    workOrderList();
  } catch(e) { showToast('Delete failed','error'); }
};

window._p6DeleteWO = function(id) {
  if (!confirm('Delete this work order?')) return;
  state.workOrders = (state.workOrders||[]).filter(w => w.id !== id);
  saveState();
  workOrderList();
};

// ── 6. Work Order Detail ──────────────────────────────────────────────────────
function workOrderDetail(id) {
  // The legacy work-order detail page is retired. Every job click routes to
  // the schedule board and opens the full visit modal (D1-backed), which is
  // the single source of truth for job details, crew, checklist, multiday,
  // portal updates and photos.
  if (!id) {
    // "New work order" flow — open the schedule board's new-visit modal
    show('scheduleBoard');
    setTimeout(() => { if (typeof window._sbOpenNewVisit === 'function') window._sbOpenNewVisit(); }, 150);
    return;
  }
  show('scheduleBoard');
  setTimeout(() => {
    if (typeof window._sbOpenVisitModal === 'function') window._sbOpenVisitModal(id);
  }, 150);
}
window.workOrderDetail = workOrderDetail;

window._p6ToggleCheck = function(woId, idx) {
  const wo = (state.workOrders||[]).find(w => w.id===woId);
  if (!wo) return;
  if (!wo.checklist) wo.checklist = [];
  if (wo.checklist[idx]) wo.checklist[idx].done = !wo.checklist[idx].done;
  state.workOrders = (state.workOrders||[]).map(w => w.id===woId ? wo : w);
  saveState();
  workOrderDetail(woId);
};
window._p6RemoveCheck = function(woId, idx) {
  const wo = (state.workOrders||[]).find(w => w.id===woId);
  if (!wo || !wo.checklist) return;
  wo.checklist.splice(idx, 1);
  state.workOrders = (state.workOrders||[]).map(w => w.id===woId ? wo : w);
  saveState();
  workOrderDetail(woId);
};
window._p6AddCheck = function(woId) {
  const text = prompt('Checklist item:');
  if (!text) return;
  const wo = (state.workOrders||[]).find(w => w.id===woId);
  if (!wo) return;
  if (!wo.checklist) wo.checklist = [];
  wo.checklist.push({ text, done:false });
  state.workOrders = (state.workOrders||[]).map(w => w.id===woId ? wo : w);
  saveState();
  workOrderDetail(woId);
};
window._p6RemoveMat = function(woId, idx) {
  const wo = (state.workOrders||[]).find(w => w.id===woId);
  if (!wo || !wo.materials) return;
  wo.materials.splice(idx, 1);
  state.workOrders = (state.workOrders||[]).map(w => w.id===woId ? wo : w);
  saveState();
  workOrderDetail(woId);
};

// ── 7. Asset List ─────────────────────────────────────────────────────────────
function assetList() {
  const R      = window.GW && window.GW.record;
  const assets = state.assets || [];

  const counts = { active:0, idle:0, maintenance:0, retired:0, rented:0 };
  assets.forEach(a => { if (counts[a.status]!==undefined) counts[a.status]++; });

  const statsHtml = R ? R.OpsStatusBar([
    { val: counts.active,      label: 'Active',          accent: 'emerald' },
    { val: counts.idle,        label: 'Idle',            accent: 'text-muted' },
    { val: counts.maintenance, label: 'In Maintenance',  accent: 'amber' },
    { val: counts.retired,     label: 'Retired',         accent: 'red' },
    { val: counts.rented,      label: 'Rented Out',      accent: 'action' },
  ]) : '';

  function newAsset() {
    const id = 'ast-' + Date.now();
    const asset = { id, name:'New Asset', category:'equipment', status:'active',
      assignedTo:'', make:'', model:'', serial:'', nextMaint:'', notes:'',
      createdAt: new Date().toISOString() };
    state.assets = [...(state.assets||[]), asset];
    saveState();
    show('assetDetail', id);
  }

  const rows = assets.length ? [...assets].reverse().map(a => `
    <div class="wo-row" onclick="show('assetDetail','${a.id}')" style="cursor:pointer">
      <span class="wo-client">${escapeHtml(a.name||'—')}</span>
      <span class="wo-type">${_p6AssetCat(a.category)}</span>
      <span class="wo-type">${escapeHtml(a.make||'')} ${escapeHtml(a.model||'')}</span>
      <span class="wo-date">${escapeHtml(a.assignedTo||'—')}</span>
      <span class="wo-date">${a.nextMaint ? _p5FmtDate(a.nextMaint) : '—'}</span>
      <span>${R ? R.AssetStatusBadge(a.status) : `<span class="ops-asset-badge">${_p6AssetLabel(a.status)}</span>`}</span>
      <span class="wo-actions">
        <button class="rp-btn-sm" onclick="event.stopPropagation();show('assetDetail','${a.id}')">Open</button>
        <button class="rp-btn-sm rp-btn-sm--danger" onclick="event.stopPropagation();_p6DeleteAsset('${a.id}')">✕</button>
      </span>
    </div>`) .join('')
    : `<div class="rp-empty-state" style="padding:48px 24px;text-align:center"><p style="color:var(--gw-text-muted);margin-bottom:12px">No assets tracked yet.</p></div>`;

  view.innerHTML = `
  <div class="wo-list-shell">
    <header class="rp-header">
      <div class="rp-header-left">
        <h1 class="rp-title">Assets</h1>
        <p class="rp-subtitle">${assets.length} tracked · ${counts.active} active · ${counts.maintenance} in maintenance</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('maintenanceQueue')">Maintenance Queue</button>
        <button class="rp-btn rp-btn--primary" onclick="_p6NewAsset()">+ Add Asset</button>
      </div>
    </header>
    ${statsHtml}
    <div style="border:1px solid var(--gw-border);border-radius:var(--gw-r-md);overflow:hidden;background:var(--gw-bg-surface-2);margin-top:16px">
      <div class="wo-row" style="background:var(--gw-bg-surface-3);cursor:default;font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">
        <span>Name</span><span>Category</span><span>Make/Model</span><span>Assigned To</span><span>Next Maint.</span><span>Status</span><span></span>
      </div>
      ${rows}
    </div>
  </div>`;
  window._p6NewAsset = newAsset;
}
window.assetList = assetList;

window._p6DeleteAsset = function(id) {
  if (!confirm('Remove this asset?')) return;
  state.assets = (state.assets||[]).filter(a => a.id !== id);
  saveState();
  assetList();
};

// ── 8. Asset Detail ───────────────────────────────────────────────────────────
function assetDetail(id) {
  const R = window.GW && window.GW.record;
  const assets = state.assets || [];
  let asset = assets.find(a => a.id === id);
  if (!asset) {
    asset = { id: id||('ast-'+Date.now()), name:'New Asset', category:'equipment',
      status:'active', assignedTo:'', make:'', model:'', serial:'',
      nextMaint:'', notes:'', createdAt: new Date().toISOString() };
    state.assets = [...(state.assets||[]), asset];
    saveState();
  }

  function save() {
    asset.name       = document.getElementById('ast-name')?.value       || asset.name;
    asset.category   = document.getElementById('ast-category')?.value   || asset.category;
    asset.status     = document.getElementById('ast-status')?.value     || asset.status;
    asset.assignedTo = document.getElementById('ast-assigned')?.value   || asset.assignedTo;
    asset.make       = document.getElementById('ast-make')?.value       || asset.make;
    asset.model      = document.getElementById('ast-model')?.value      || asset.model;
    asset.serial     = document.getElementById('ast-serial')?.value     || asset.serial;
    asset.nextMaint  = document.getElementById('ast-nextmaint')?.value  || asset.nextMaint;
    asset.notes      = document.getElementById('ast-notes')?.value      || asset.notes;
    asset.updatedAt  = new Date().toISOString();
    state.assets = (state.assets||[]).map(a => a.id===id ? asset : a);
    saveState();
    assetDetail(id);
  }

  const maintHistory = (state.maintenance||[]).filter(m => m.assetId === id);
  const maintRows = maintHistory.map(m => `
    <div class="maint-row">
      <span class="maint-type">${escapeHtml(m.type||'Service')}</span>
      <span class="maint-due">${m.dueDate ? _p5FmtDate(m.dueDate) : '—'}</span>
      <span class="maint-done">${m.completedDate ? _p5FmtDate(m.completedDate) : '<em style="color:var(--gw-text-muted)">Pending</em>'}</span>
      <span class="maint-by">${escapeHtml(m.performedBy||'—')}</span>
    </div>`).join('') || '<p style="color:var(--gw-text-muted);font-style:italic;font-size:12px">No maintenance records.</p>';

  const leftRail = `
    <section class="rp-section">
      <div class="rp-section-head"><span class="rp-section-title">Asset Details</span></div>
      <div class="rp-field-grid">
        <label class="rp-field">
          <span class="rp-field-label">Asset Name</span>
          <input class="rp-input" id="ast-name" value="${escapeHtml(asset.name||'')}" placeholder="e.g. Mower #1">
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Category</span>
          <select class="rp-input" id="ast-category">
            ${['vehicle','trailer','equipment','tool','tech','other'].map(c=>`<option value="${c}"${asset.category===c?' selected':''}>${_p6AssetCat(c)}</option>`).join('')}
          </select>
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Status</span>
          <select class="rp-input" id="ast-status">
            ${['active','idle','maintenance','retired','rented','pending','out-of-service'].map(s=>`<option value="${s}"${asset.status===s?' selected':''}>${_p6AssetLabel(s)}</option>`).join('')}
          </select>
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Assigned To</span>
          <input class="rp-input" id="ast-assigned" value="${escapeHtml(asset.assignedTo||'')}" placeholder="Crew or employee">
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Make</span>
          <input class="rp-input" id="ast-make" value="${escapeHtml(asset.make||'')}" placeholder="e.g. John Deere">
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Model</span>
          <input class="rp-input" id="ast-model" value="${escapeHtml(asset.model||'')}" placeholder="e.g. Z930M">
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Serial Number</span>
          <input class="rp-input" id="ast-serial" value="${escapeHtml(asset.serial||'')}" placeholder="Serial / VIN">
        </label>
        <label class="rp-field">
          <span class="rp-field-label">Next Maintenance</span>
          <input class="rp-input" id="ast-nextmaint" type="date" value="${asset.nextMaint||''}">
        </label>
      </div>
      <label class="rp-field" style="margin-top:8px">
        <span class="rp-field-label">Notes</span>
        <textarea class="rp-input" id="ast-notes" rows="3" placeholder="Condition notes, purchase info…">${escapeHtml(asset.notes||'')}</textarea>
      </label>
      <div style="margin-top:12px;display:flex;gap:8px">
        <button class="rp-btn rp-btn--primary" onclick="_p6AssetSave()">Save Changes</button>
        <button class="rp-btn" onclick="show('assetList')">← Back to Assets</button>
      </div>
    </section>
    <section class="rp-section">
      <div class="rp-section-head">
        <span class="rp-section-title">Maintenance History</span>
        <button class="rp-btn-sm" onclick="show('maintenanceQueue')">View Queue</button>
      </div>
      ${maintRows}
    </section>`;

  const rightRail = `
    <section class="rp-section">
      <div class="rp-section-head"><span class="rp-section-title">Status</span></div>
      <div style="display:flex;flex-direction:column;gap:10px">
        <div>${R ? R.AssetStatusBadge(asset.status) : `<span>${_p6AssetLabel(asset.status)}</span>`}</div>
        <div><span style="font-size:11px;color:var(--gw-text-muted)">Category</span><br><strong>${_p6AssetCat(asset.category)}</strong></div>
        <div><span style="font-size:11px;color:var(--gw-text-muted)">Assigned To</span><br><strong>${escapeHtml(asset.assignedTo||'Unassigned')}</strong></div>
        <div><span style="font-size:11px;color:var(--gw-text-muted)">Next Maintenance</span><br><strong>${asset.nextMaint ? _p5FmtDate(asset.nextMaint) : '—'}</strong></div>
        <div><span style="font-size:11px;color:var(--gw-text-muted)">Make / Model</span><br><strong>${escapeHtml(asset.make||'—')} ${escapeHtml(asset.model||'')}</strong></div>
      </div>
    </section>`;

  view.innerHTML = `
  <div class="rp-shell">
    <div class="rp-breadcrumb">
      <button class="rp-crumb" onclick="show('assetList')">Assets</button>
      <span class="rp-crumb-sep">›</span>
      <span class="rp-crumb-current">${escapeHtml(asset.name||'Asset')}</span>
    </div>
    <div class="rp-columns">
      <div class="rp-col-main">${leftRail}</div>
      <div class="rp-col-side">${rightRail}</div>
    </div>
  </div>`;

  window._p6AssetSave = save;
}
window.assetDetail = assetDetail;

// ── 9. Maintenance Queue ──────────────────────────────────────────────────────
function maintenanceQueue() {
  const maint  = state.maintenance || [];
  const assets = state.assets || [];
  const today  = new Date().toISOString().slice(0,10);

  const overdue  = maint.filter(m => !m.completedDate && m.dueDate && m.dueDate < today);
  const dueSoon  = maint.filter(m => !m.completedDate && m.dueDate && m.dueDate >= today && m.dueDate <= new Date(Date.now()+14*864e5).toISOString().slice(0,10));
  const upcoming = maint.filter(m => !m.completedDate && m.dueDate && m.dueDate > new Date(Date.now()+14*864e5).toISOString().slice(0,10));
  const done     = maint.filter(m => m.completedDate);

  function assetName(id) {
    const a = assets.find(a => a.id===id);
    return a ? a.name : id||'—';
  }

  function maintRow(m) {
    const isOverdue = !m.completedDate && m.dueDate && m.dueDate < today;
    return `
    <div class="maint-row${isOverdue?' maint-row--overdue':''}" onclick="show('assetDetail','${m.assetId}')" style="cursor:pointer">
      <span class="maint-asset">${escapeHtml(assetName(m.assetId))}</span>
      <span class="maint-type">${escapeHtml(m.type||'Service')}</span>
      <span class="maint-due${isOverdue?' maint-overdue-text':''}">${m.dueDate ? _p5FmtDate(m.dueDate) : '—'}</span>
      <span class="maint-done">${m.completedDate ? _p5FmtDate(m.completedDate) : '<em style="color:var(--gw-text-muted)">Pending</em>'}</span>
      <span class="maint-by">${escapeHtml(m.performedBy||'—')}</span>
      <span class="wo-actions">
        ${!m.completedDate ? `<button class="rp-btn-sm" onclick="event.stopPropagation();_p6CompleteMaint('${m.id}')">Mark Done</button>` : ''}
      </span>
    </div>`;
  }

  function section(title, items, accent) {
    if (!items.length) return '';
    return `
      <div style="margin-bottom:24px">
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--gw-${accent});margin-bottom:8px">${title} (${items.length})</div>
        <div style="border:1px solid var(--gw-border);border-radius:var(--gw-r-md);overflow:hidden;background:var(--gw-bg-surface-2)">
          ${items.map(maintRow).join('')}
        </div>
      </div>`;
  }

  function newMaintRecord() {
    if (!assets.length) { alert('Add an asset first.'); return; }
    const assetId = prompt('Asset ID or name:');
    if (!assetId) return;
    const type    = prompt('Maintenance type (e.g. Oil Change, Blade Sharpen):','Service');
    if (!type) return;
    const dueDate = prompt('Due date (YYYY-MM-DD):', new Date().toISOString().slice(0,10));
    const id = 'maint-' + Date.now();
    state.maintenance = [...(state.maintenance||[]), { id, assetId, type, dueDate, performedBy:'', completedDate:null, notes:'' }];
    saveState();
    maintenanceQueue();
  }

  const emptyState = !maint.length ? `<div class="rp-empty-state" style="padding:48px 24px;text-align:center"><p style="color:var(--gw-text-muted);margin-bottom:12px">No maintenance records. Add assets and schedule their maintenance.</p></div>` : '';

  view.innerHTML = `
  <div class="wo-list-shell">
    <header class="rp-header">
      <div class="rp-header-left">
        <h1 class="rp-title">Maintenance Queue</h1>
        <p class="rp-subtitle">${overdue.length} overdue · ${dueSoon.length} due soon · ${done.length} completed</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('assetList')">Assets</button>
        <button class="rp-btn rp-btn--primary" onclick="_p6NewMaint()">+ Schedule Maintenance</button>
      </div>
    </header>
    ${emptyState}
    ${section('Overdue', overdue, 'red')}
    ${section('Due Within 14 Days', dueSoon, 'amber')}
    ${section('Upcoming', upcoming, 'text-secondary')}
    ${section('Completed', done.slice(-10).reverse(), 'emerald')}
  </div>`;
  window._p6NewMaint = newMaintRecord;
}
window.maintenanceQueue = maintenanceQueue;

window._p6CompleteMaint = function(id) {
  const date = prompt('Completion date:', new Date().toISOString().slice(0,10));
  if (!date) return;
  const by = prompt('Performed by:','');
  state.maintenance = (state.maintenance||[]).map(m => m.id===id ? {...m, completedDate:date, performedBy:by||m.performedBy} : m);
  saveState();
  maintenanceQueue();
};

// ── 10. Inventory List ────────────────────────────────────────────────────────
function inventoryList() {
  const R   = window.GW && window.GW.record;
  const inv = state.inventory || [];
  const today = new Date().toISOString().slice(0,10);

  const needReorder = inv.filter(i => Number(i.onHand||0) <= Number(i.reorderAt||0));
  const outOfStock  = inv.filter(i => Number(i.onHand||0) === 0);
  const ok          = inv.filter(i => Number(i.onHand||0) > Number(i.reorderAt||0));

  const statsHtml = R ? R.OpsStatusBar([
    { val: inv.length,           label: 'Total Items',   accent: 'action' },
    { val: ok.length,            label: 'In Stock',      accent: 'emerald' },
    { val: needReorder.length,   label: 'Low / Reorder', accent: 'amber', delta: needReorder.length>0?'!':'' },
    { val: outOfStock.length,    label: 'Out of Stock',  accent: 'red',   delta: outOfStock.length>0?'!':'' },
  ]) : '';

  function newItem() {
    const id   = 'inv-' + Date.now();
    const item = { id, name:'New Item', category:'supply', onHand:0, reserved:0,
      reorderAt:5, vendor:'', unit:'ea', notes:'',
      createdAt: new Date().toISOString() };
    state.inventory = [...(state.inventory||[]), item];
    saveState();
    inventoryList();
  }

  function statusFor(item) {
    if (Number(item.onHand||0) === 0) return 'out-of-stock';
    if (Number(item.onHand||0) <= Number(item.reorderAt||0)) return 'low-stock';
    return 'ok';
  }

  const rows = inv.length ? [...inv].map(item => {
    const s = statusFor(item);
    const badge = R ? R.InvtStatusBadge(s) : `<span class="ops-inv-badge">${_p6InvtLabel(s)}</span>`;
    const pct = item.reorderAt > 0 ? Math.min(100, Math.round(Number(item.onHand||0)/Number(item.reorderAt||1)*100)) : 100;
    return `
    <div class="invt-row" style="cursor:default">
      <span class="invt-name">${escapeHtml(item.name||'—')}</span>
      <span class="invt-cat">${escapeHtml(item.category||'—')}</span>
      <span class="invt-qty">
        <span style="font-weight:700;font-size:13px">${item.onHand||0}</span>
        <span style="font-size:10px;color:var(--gw-text-muted)">${escapeHtml(item.unit||'ea')}</span>
      </span>
      <span class="invt-bar-wrap">
        <div class="invt-bar"><div class="invt-bar-fill invt-bar-fill--${s}" style="width:${pct}%"></div></div>
        <span class="invt-reorder-label">reorder @ ${item.reorderAt||0}</span>
      </span>
      <span>${badge}</span>
      <span class="invt-vendor">${escapeHtml(item.vendor||'—')}</span>
      <span class="wo-actions">
        <button class="rp-btn-sm" onclick="_p6EditInvt('${item.id}')">Edit</button>
        <button class="rp-btn-sm rp-btn-sm--danger" onclick="_p6DeleteInvt('${item.id}')">✕</button>
      </span>
    </div>`;
  }).join('')
  : `<div class="rp-empty-state" style="padding:48px 24px;text-align:center"><p style="color:var(--gw-text-muted);margin-bottom:12px">No inventory items yet.</p></div>`;

  view.innerHTML = `
  <div class="wo-list-shell">
    <header class="rp-header">
      <div class="rp-header-left">
        <h1 class="rp-title">Inventory</h1>
        <p class="rp-subtitle">${inv.length} items · ${needReorder.length} need reorder</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('opsHub')">← Ops Hub</button>
        <button class="rp-btn rp-btn--primary" onclick="_p6NewInvt()">+ Add Item</button>
      </div>
    </header>
    ${statsHtml}
    <div style="border:1px solid var(--gw-border);border-radius:var(--gw-r-md);overflow:hidden;background:var(--gw-bg-surface-2);margin-top:16px">
      <div class="invt-row" style="background:var(--gw-bg-surface-3);cursor:default;font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">
        <span>Item Name</span><span>Category</span><span>On Hand</span><span>Stock Level</span><span>Status</span><span>Vendor</span><span></span>
      </div>
      ${rows}
    </div>
  </div>`;
  window._p6NewInvt = newItem;
}
window.inventoryList = inventoryList;

window._p6EditInvt = function(id) {
  const item = (state.inventory||[]).find(i => i.id===id);
  if (!item) return;
  const name     = prompt('Item name:', item.name) || item.name;
  const onHand   = prompt('On hand quantity:', item.onHand);
  const reorderAt= prompt('Reorder at:', item.reorderAt);
  const vendor   = prompt('Vendor:', item.vendor||'');
  state.inventory = (state.inventory||[]).map(i => i.id===id ? {...i, name, onHand:Number(onHand)||0, reorderAt:Number(reorderAt)||0, vendor } : i);
  saveState();
  inventoryList();
};
window._p6DeleteInvt = function(id) {
  if (!confirm('Remove this inventory item?')) return;
  state.inventory = (state.inventory||[]).filter(i => i.id!==id);
  saveState();
  inventoryList();
};

// ── 11. Material Allocation ───────────────────────────────────────────────────
function materialAllocation(woId) {
  const wos = state.workOrders || [];
  const inv  = state.inventory  || [];
  const wo   = wos.find(w => w.id === woId);
  if (!wo) { show('workOrderList'); return; }

  const allocs = (state.allocations||[]).filter(a => a.woId === woId);

  function addAlloc() {
    if (!inv.length) { alert('No inventory items. Add items to inventory first.'); return; }
    const names = inv.map((i,n) => `${n+1}. ${i.name} (${i.onHand} ${i.unit||'ea'})`).join('\n');
    const idx   = parseInt(prompt('Select item number:\n'+names)) - 1;
    if (isNaN(idx) || idx<0 || idx>=inv.length) return;
    const item  = inv[idx];
    const qty   = parseFloat(prompt(`Quantity for "${item.name}":`, '1'));
    if (!qty || isNaN(qty)) return;
    const id = 'alloc-' + Date.now();
    state.allocations = [...(state.allocations||[]), { id, woId, itemId:item.id, itemName:item.name, qty, unit:item.unit||'ea', status:'allocated' }];
    // Add to WO materials for display
    if (!wo.materials) wo.materials = [];
    wo.materials.push({ name:item.name, qty, unit:item.unit||'ea', itemId:item.id });
    state.workOrders = (state.workOrders||[]).map(w => w.id===woId ? wo : w);
    saveState();
    materialAllocation(woId);
  }

  const allocRows = allocs.map(a => {
    const item = inv.find(i => i.id===a.itemId);
    return `
    <div class="alloc-item">
      <div class="alloc-item-head">
        <span class="alloc-item-name">${escapeHtml(a.itemName||a.itemId||'—')}</span>
        <span class="alloc-item-qty">${a.qty} ${escapeHtml(a.unit||'ea')}</span>
        <button class="rp-btn-sm rp-btn-sm--danger" onclick="_p6RemoveAlloc('${a.id}','${woId}')">Remove</button>
      </div>
      <div class="alloc-item-detail">
        ${item ? `On Hand: ${item.onHand} · Reserved: ${item.reserved||0}` : 'Item not found in inventory'}
      </div>
    </div>`;
  }).join('') || '<p style="color:var(--gw-text-muted);font-style:italic">No materials allocated yet.</p>';

  const totalCost = allocs.reduce((sum,a) => {
    const item = inv.find(i => i.id===a.itemId);
    return sum + (a.qty * (item?.unitCost||0));
  }, 0);

  view.innerHTML = `
  <div class="rp-shell">
    <div class="rp-breadcrumb">
      <button class="rp-crumb" onclick="show('workOrderList')">Work Orders</button>
      <span class="rp-crumb-sep">›</span>
      <button class="rp-crumb" onclick="show('workOrderDetail','${woId}')">${_p6WONum(wo)}</button>
      <span class="rp-crumb-sep">›</span>
      <span class="rp-crumb-current">Material Allocation</span>
    </div>
    <div style="max-width:700px;margin:0 auto;padding:20px 24px">
      <div class="rp-card">
        <div class="rp-card-head">
          <span class="rp-card-title">Materials for ${_p6WONum(wo)}</span>
          <button class="rp-btn rp-btn--primary" onclick="_p6AddAlloc()">+ Allocate Item</button>
        </div>
        <div class="alloc-summary" style="margin-bottom:12px">
          <span class="alloc-summary-text">${allocs.length} items allocated${totalCost>0?' · Est. Cost: '+_p5Money(totalCost):''}</span>
        </div>
        ${allocRows}
      </div>
      <div style="margin-top:16px;display:flex;gap:8px">
        <button class="rp-btn" onclick="show('workOrderDetail','${woId}')">← Back to Work Order</button>
        <button class="rp-btn" onclick="show('inventoryList')">View Inventory</button>
      </div>
    </div>
  </div>`;

  window._p6AddAlloc = addAlloc;
}
window.materialAllocation = materialAllocation;

window._p6RemoveAlloc = function(allocId, woId) {
  if (!confirm('Remove this material allocation?')) return;
  const alloc = (state.allocations||[]).find(a => a.id===allocId);
  state.allocations = (state.allocations||[]).filter(a => a.id!==allocId);
  // Also remove from WO materials
  if (alloc) {
    const wo = (state.workOrders||[]).find(w => w.id===woId);
    if (wo && wo.materials) {
      wo.materials = wo.materials.filter(m => !(m.itemId===alloc.itemId && m.qty===alloc.qty));
      state.workOrders = (state.workOrders||[]).map(w => w.id===woId ? wo : w);
    }
  }
  saveState();
  materialAllocation(woId);
};

